var e=JSON.parse(`{"wrist-circles":{"name":"Círculos de muñeca","description":"De pie, con los codos suaves y los antebrazos frente a ti. Dibuja círculos lentos con ambas muñecas, cuatro tiempos hacia un lado y cuatro hacia el otro, manteniendo los dedos relajados.","goodFor":"Calienta las muñecas y los antebrazos, que hacen la mayor parte del trabajo con cualquier implemento.","alignmentCues":["Los codos se quedan quietos; solo se mueven las muñecas.","Mantén los círculos amplios y fluidos."],"commonMistakes":["Apurar los círculos hasta que se conviertan en latigazos."]},"arm-circles":{"name":"Círculos de brazos","description":"Pies al ancho de las caderas, brazos largos. Balancea ambos brazos en círculos amplios hacia adelante durante cuatro tiempos, luego hacia atrás otros cuatro, dejando que los omóplatos se deslicen.","goodFor":"Abre los hombros para los giros de staff y el trabajo de hoop por encima de la cabeza.","alignmentCues":["Las costillas se mantienen abajo mientras los brazos pasan por encima de la cabeza.","Exhala en el descenso."]},"shoulder-rolls":{"name":"Rodamientos de hombros","description":"Brazos relajados a los lados. Sube los hombros hacia las orejas, ródalos hacia atrás y abajo, y repite en un bucle lento.","goodFor":"Libera la tensión que vuelve los lanzamientos rígidos y cortos."},"neck-rolls":{"name":"Medios círculos de cuello","description":"Baja el mentón hacia el pecho y deslízalo lentamente de hombro a hombro en medio círculo. Evita que la cabeza se incline hacia atrás.","goodFor":"Alivia el cuello antes de mirar hacia arriba los lanzamientos durante largos periodos.","avoidIf":["Lesión de cuello o mareo al mover la cabeza."]},"hip-circles":{"name":"Círculos de cadera","description":"Manos en las caderas, rodillas suaves. Circula las caderas lentamente hacia un lado durante dos compases y hacia el otro durante dos, manteniendo la cabeza nivelada.","goodFor":"Prepara las caderas para el waist hooping y el cuerpo para el flow."},"torso-twists":{"name":"Torsiones de torso","description":"Pies anchos, brazos sueltos. Gira las costillas a izquierda y derecha y deja que los brazos se balanceen y se envuelvan alrededor de ti como mangas vacías.","goodFor":"Despierta la rotación para los weaves de staff y los pases de hoop."},"knee-bounce":{"name":"Rebote de rodillas","description":"De pie con los pies bajo las caderas y rebota suavemente con las rodillas en cada beat, con los brazos balanceándose sueltos. Encuentra la música en tus piernas.","goodFor":"Pone el beat en tu cuerpo antes de que tomes un implemento."},"one-ball-toss":{"name":"Lanzamiento de una pelota","description":"Sostén una pelota en tu mano derecha a la altura de la cintura. Recógela hacia adentro, luego lánzala en un arco que alcance su punto más alto justo por encima del nivel de los ojos y caiga en la mano izquierda. Lánzala de vuelta de la misma manera. Mantén la vista en la cima del arco, no en tus manos.","goodFor":"Construye el arco del que está hecho cada patrón de malabares.","alignmentCues":["Codos pegados a los costados, antebrazos nivelados.","La cima tiene la misma altura en cada lanzamiento.","Atrapa a la altura de la cintura y deja que la mano ceda un poco."],"commonMistakes":["Lanzar hacia adelante y tener que dar un paso tras la pelota.","Mirar las manos en vez de la cima."]},"two-ball-exchange":{"name":"Intercambio de dos pelotas","description":"Una pelota en cada mano. Lanza la pelota derecha en su arco; cuando llegue a la cima, lanza la pelota izquierda por debajo de ella, por dentro. Atrapa ambas y pausa. Luego empieza con la mano izquierda.","goodFor":"Enseña el intercambio: el segundo lanzamiento sale cuando el primero llega a la cima.","alignmentCues":["Segundo lanzamiento en la cima, nunca antes.","Lanza la segunda pelota por dentro de la primera."],"commonMistakes":["Pasar la segunda pelota al otro lado en lugar de lanzarla.","Lanzar ambas a la vez."]},"cascade":{"name":"Cascada de tres pelotas","description":"Dos pelotas en la mano derecha, una en la izquierda. Lanza desde la derecha; cuando llegue al punto más alto, lanza desde la izquierda; cuando esa llegue al punto más alto, lanza desde la derecha otra vez. Cada lanzamiento va al ritmo, cruzando a la otra mano en un arco en forma de 8.","goodFor":"El patrón fundamental del malabarismo.","modifications":["Practica el flash: tres lanzamientos, tres recepciones, para."],"deepen":["Haz malabares a un tempo más rápido con puntos más bajos.","Cuenta 20 recepciones sin que se caiga ninguna."],"alignmentCues":["Lanza desde dentro, recibe por fuera.","Puntos altos nivelados, a la altura de los ojos.","Ponte contra una pared si sigues avanzando."],"commonMistakes":["Lanzar hacia adelante y perseguir el patrón.","Apurarse apenas un lanzamiento sale mal."]},"reverse-cascade":{"name":"Cascada inversa","description":"La cascada al revés: cada pelota se lanza desde fuera, por encima del patrón, y cae por el centro hacia la otra mano.","goodFor":"Entrena lanzamientos desde fuera y abre trucos como el Mills Mess.","alignmentCues":["Los lanzamientos pasan por encima de la pelota que llega.","Recibe en el centro."]},"siteswap-423":{"name":"423","description":"Un patrón de tres pelotas: un autolanzamiento alto (4), una pelota sostenida (2), luego un lanzamiento de cascada (3). El 4 sube por el mismo lado; el 2 simplemente se sostiene durante un tiempo.","goodFor":"Tu primer truco de siteswap: enseña lanzamientos altos y sostenes."},"siteswap-441":{"name":"441","description":"Dos lanzamientos altos que se quedan de su propio lado (4, 4) seguidos de un zip rápido cruzado (1) de mano a mano.","goodFor":"Construye el timing entre lanzamientos altos y pases rápidos."},"two-in-one":{"name":"Dos en una mano","description":"Haz malabares con dos pelotas en una mano en columnas lado a lado o pequeños círculos hacia afuera, un lanzamiento cada dos tiempos. Practica cada mano.","goodFor":"El bloque de construcción del malabarismo con cuatro pelotas."},"siteswap-531":{"name":"531","description":"Un lanzamiento cruzado muy alto (5), un lanzamiento de cascada (3) y un zip rápido (1). El 5 sube mientras las otras dos pelotas siguen trabajando por debajo.","goodFor":"Control de altura y un truco de tres pelotas para lucir."},"shower":{"name":"Ducha de tres pelotas","description":"Las pelotas viajan en círculo: la mano derecha lanza cada pelota alto hacia la izquierda, y la mano izquierda pasa cada una directo de vuelta a la derecha.","goodFor":"Patrón circular clásico; entrena pases rápidos de mano a mano."},"mills-mess":{"name":"Mills Mess","description":"Una cascada de tres pelotas donde los brazos se cruzan y descruzan continuamente, así que cada lanzamiento sale del lado opuesto del cuerpo. Las trayectorias de las pelotas trazan un patrón entrelazado.","goodFor":"Un favorito del público que agudiza la coordinación."},"four-ball-fountain":{"name":"Fuente de cuatro pelotas","description":"Cada mano hace malabares con dos pelotas en su propia columna, las manos alternan los lanzamientos para que el patrón nunca se cruce.","goodFor":"Tu primer patrón de cuatro pelotas."},"sync-fountain":{"name":"Fuente sincrónica","description":"Cuatro pelotas con ambas manos lanzando exactamente en el mismo momento, cada una hacia su propio lado.","goodFor":"Construye simetría y lleva a trucos sincrónicos."},"five-ball-cascade":{"name":"Cascada de cinco pelotas","description":"La cascade con cinco pelotas: lanzamientos altos y rápidos en un patrón cruzado elevado. Cuenta con meses de práctica.","goodFor":"Un hito para malabaristas dedicados."},"tennis":{"name":"Tenis","description":"Una cascada en la que una pelota, la \\"pelota de tenis\\", siempre viaja por encima del patrón en lugar de por el medio. La mano que la tenga la lanza por fuera, de modo que pase por arriba como un peloteo sobre una red.","goodFor":"Primer paso hacia los lanzamientos por fuera, con el ritmo de una cascada normal.","alignmentCues":["Ten siempre a la vista cuál es la pelota de tenis.","Lánzala desde fuera, a la misma altura que las demás."],"commonMistakes":["Perder la pista de qué pelota va por encima.","Lanzar la pelota de arriba más alto que las demás."]},"half-shower":{"name":"Media ducha","description":"Una mano lanza todas las pelotas por arriba mientras la otra las lanza por debajo. Los dos arcos se separan en una trayectoria alta por fuera y otra baja por dentro, y las pelotas se persiguen dando vueltas en bucle.","goodFor":"Dividir las manos en dos roles mientras el ritmo se mantiene uniforme.","alignmentCues":["La mano de arriba lanza por fuera y un poco más alto.","La mano de abajo mantiene sus lanzamientos ajustados y por dentro."],"commonMistakes":["Ambas manos volviendo a los lanzamientos de cascada normal.","Colisiones en el centro cuando los arcos tienen la misma altura."]},"claw-cascade":{"name":"Cascada de garra","description":"La cascada atrapada con la palma hacia abajo. Cada mano sube y atrapa la pelota desde arriba, luego la baja y gira la muñeca para lanzar. Las manos parecen arañar las pelotas.","goodFor":"Desarrolla atrapadas activas y un giro de muñeca potente.","alignmentCues":["Sube a por la pelota con los dedos abiertos.","Baja y gira la muñeca en un solo movimiento."],"commonMistakes":["Atrapar tarde y que la pelota golpee el dorso de la mano.","Lanzar bajo porque el giro tarda demasiado."]},"chops":{"name":"Chuleta","description":"Tras cada atrapada, la mano lleva la pelota en alto a través del cuerpo y corta hacia abajo, lanzando desde el lado opuesto. Los brazos se cruzan con un movimiento de corte, y las pelotas caen en una cascada compacta por debajo.","goodFor":"Grandes llevadas del brazo, con el ritmo de la cascada por debajo.","alignmentCues":["Atrapa en alto, lleva al otro lado, corta hacia abajo y lanza.","Lanza desde el lado opuesto de tu cuerpo."],"commonMistakes":["Llevar la pelota demasiado lejos y llegar tarde a la siguiente atrapada.","Brazos chocando en el centro."]},"penguin-cascade":{"name":"Cascada pingüino","description":"Los brazos cuelgan rectos a los lados con las palmas hacia abajo. Cada atrapada se hace baja y hacia fuera, y los lanzamientos suben con un impulso desde la cadera. Pareces un pingüino aleteando al ritmo.","goodFor":"Lanzamientos impulsados desde la muñeca y atrapadas lejos de la posición habitual de las manos.","alignmentCues":["Codos rectos, manos junto a las caderas.","Impulsa con la muñeca, palmas hacia atrás."],"commonMistakes":["Doblar los codos y volver a la cascada normal.","Lanzamientos que se van hacia delante porque la muñeca está doblada hacia atrás."]},"under-the-leg":{"name":"Bajo la pierna","description":"Una cascada en la que cada sexto lanzamiento pasa bajo la pierna derecha. Levanta la rodilla cuando llega la pelota, mete la mano bajo el muslo y lanza hacia arriba desde fuera; luego apoya el pie para la siguiente atrapada.","goodFor":"El primer lanzamiento con el cuerpo: subir la pierna y estirar el brazo en un solo tiempo.","alignmentCues":["Levanta la rodilla antes del lanzamiento, no durante.","Lanza un poco más alto para cubrir el alcance extra."],"commonMistakes":["Inclinarse hacia la pierna en vez de levantar la rodilla.","Apresurar el siguiente lanzado tras bajar la pierna."]},"behind-the-back":{"name":"Detrás de la espalda","description":"Cada sexto lanzado, la mano derecha pasa por detrás de la cintura y lanza la pelota por encima del hombro contrario para que caiga de nuevo en el patrón, delante. Los demás lanzados siguen siendo una cascada normal.","goodFor":"Lanzar a ciegas hacia un patrón que no puedes ver.","alignmentCues":["Lleva la mano por detrás temprano, justo cuando cae la pelota.","Apunta por encima del hombro lejano, un poco más alto de lo normal."],"commonMistakes":["Lanzar demasiado hacia delante y que la pelota caiga delante de ti.","Girar todo el torso."]},"over-the-shoulder":{"name":"Sobre el hombro","description":"Cada sexto lanzamiento, la mano derecha envía su bola alta desde el frente, hacia arriba y atrás sobre el hombro izquierdo. La mano izquierda gira detrás de la cadera y la atrapa a ciegas, luego lanza su siguiente bola hacia arriba desde al lado de la cadera. Todo lo demás es una cascada simple.","goodFor":"Una atrapada a ciegas detrás de la espalda, sincronizada por el sentido en lugar de la vista.","alignmentCues":["Lanza lo suficientemente alto como para pasar por encima de la cabeza, justo detrás del hombro izquierdo.","Coloca la mano que atrapa detrás de la cadera temprano, con la palma hacia arriba."],"commonMistakes":["Girar la cabeza para buscar la bola.","Lanzar demasiado bajo, haciendo que la bola roce la cabeza o el hombro."]},"knee-bounce-cascade":{"name":"Rebote en la rodilla","description":"Cada sexto lanzamiento, la mano derecha deja caer la bola sobre la rodilla derecha mientras la rodilla sube. La bola rebota en la parte superior del muslo, sube y cruza hacia la mano izquierda, y el pie vuelve a bajar para la siguiente atrapada.","goodFor":"Equilibrio sobre una pierna mientras la rodilla entra al patrón a tiempo.","alignmentCues":["Levanta la rodilla para recibir la bola, con el muslo en horizontal.","Deja caer la bola, no la lanzes hacia abajo."],"commonMistakes":["Patear la bola hace que salga volando hacia adelante.","Inclinar el cuerpo hacia la rodilla en lugar de levantarla."]},"head-bounce-cascade":{"name":"Rebote en la frente","description":"Cada sexto lanzamiento sube por encima de tu cabeza. Inclina la cabeza hacia atrás para que la bola caiga en la frente, luego asiente para bajarla y mandarla hacia adelante a la mano izquierda. Los demás lanzamientos se mantienen como una cascada normal por debajo.","goodFor":"Seguir con la mirada una bola justo encima de ti mientras las manos mantienen la cascada.","alignmentCues":["Inclina la cabeza hacia atrás con antelación y mantén la vista en la bola.","Flexiona un poco las rodillas para suavizar el rebote."],"commonMistakes":["Golpear la bola con la cabeza en lugar de dejarla rebotar.","Perder la cascada al mirar hacia arriba."]},"crossed-arm-cascade":{"name":"Cascada con brazos cruzados","description":"Cruza los antebrazos con la mano derecha del lado izquierdo y mantenlos cruzados. Haz una cascada desde esa posición. Los lanzados se sienten al revés, aunque el patrón se ve normal.","goodFor":"Romper el hábito de dónde vive cada mano.","alignmentCues":["Mantén el cruce en las muñecas, no en los codos.","Los lanzados llegan a la altura de los ojos, como siempre."],"commonMistakes":["Descruzar los brazos entre lanzados.","Las manos chocan al cambiar de lado."]},"burkes-barrage":{"name":"Barrage de Burke","description":"Se construye sobre el 423. La pelota lanzada como 4 se atrapa en claw y se lleva cruzada, el 2 es una pequeña elevación en la misma mano y el 3 baja al patrón con un chop. Los brazos se entrelazan en un floreo constante.","goodFor":"Combinar carries y claws sobre un siteswap que ya conoces.","alignmentCues":["Aprende primero el ritmo del 423 y luego añade el carry.","El 2 apenas sale de la mano."],"commonMistakes":["Lanzar el 2 tan alto que rompe el ritmo.","Olvidar el chop en el 3."]},"rubensteins-revenge":{"name":"La venganza de Rubenstein","description":"Un enredo de carries sobre el 52233. Un lanzado alto da tiempo mientras las manos atrapan en claw, cortan y se cruzan entre sí; luego el patrón se desenreda y vuelve a ser una cascada. Apréndelo despacio, una mano a la vez.","goodFor":"Una pieza de exhibición que entrena a la vez los carries, los claws y el cruce de brazos.","alignmentCues":["El 5 es el único lanzado alto.","Aprende el recorrido de las manos dejando fuera la pelota alta."],"commonMistakes":["Ponerse nervioso durante los carries y lanzar antes de tiempo.","El lanzado alto se va hacia delante."]},"siteswap-42":{"name":"42 con dos pelotas","description":"Dos pelotas: cada mano lanza una pelota alta hacia sí misma y sostiene la otra durante un beat. Las pelotas altas suben en columnas a cada lado mientras las manos se turnan. Una forma tranquila de aprender los lanzados hacia uno mismo.","goodFor":"Lanzas al mismo lado a altura cuatro, la base de dos en una mano.","alignmentCues":["Las lanzas se quedan en su propio lado.","Mantén el 2 quieto en la palma."],"commonMistakes":["Lanzas que se desvían hacia el centro.","Lanzar por error la bola retenida."]},"snake":{"name":"Serpiente","description":"Tres bolas lanzadas como cincos cruzados y altos, con un tiempo vacío después de cada una. Las bolas van una tras otra por el mismo arco alto, como una serpiente deslizándose sobre tu cabeza.","goodFor":"Lanzas altas constantes sin la presión de un ritmo completo de cinco bolas.","alignmentCues":["Todos los cincos a la misma altura.","Usa el tiempo vacío para resetear la mano."],"commonMistakes":["Cincos que se adelantan.","Lanzar en el tiempo vacío por costumbre."]},"grace":{"name":"Gracia","description":"Un multiplex suave: una mano lanza dos bolas a la vez, una cruzada normal y un pase pequeñito directo a la otra mano. Después un tiempo retenido y de vuelta a la cascada.","goodFor":"Una introducción suave a lanzar dos bolas desde una sola mano.","alignmentCues":["Suelta las dos bolas a la vez.","La pequeña apenas sube."],"commonMistakes":["Soltar las dos bolas en momentos distintos.","Lanzar la bola pequeña demasiado alto."]},"orinoco-flow":{"name":"Flujo Orinoco","description":"Dos rondas de 42 con una lanza de cascada cosida al final, así que las lanzas al mismo lado cambian de mano en cada vuelta. Ondula entre columnas y cascada.","goodFor":"Cambio fluido entre lanzas al mismo lado y lanzas cruzadas.","alignmentCues":["Cuatros rectos hacia arriba, a tu lado.","El 3 es una lanza normal de cascada."],"commonMistakes":["Cuatros que se inclinan hacia dentro.","Perder la cuenta del ciclo de cinco lanzas."]},"relfs-rhythm":{"name":"Ritmo de Relf","description":"Una lanza al mismo lado y una retención, luego tres lanzas de cascada. Como el ciclo es impar, la lanza al mismo lado cae en la otra mano en cada vuelta.","goodFor":"Insertar un truco en una cascada en marcha, desde cualquier lado.","alignmentCues":["Primero la cascada, luego cuela el 42.","Mantén el cuatro en su propio lado."],"commonMistakes":["Hacerlo solo con la mano fuerte.","La cascada se acelera después."]},"frostbite":{"name":"Congelación","description":"Dos cuatros rápidos, un pase veloz al otro lado y luego dos lanzas de cascada. El pase se cuela por debajo mientras los cuatros flotan en lo alto.","goodFor":"Mezclar pases rápidos con lanzas altas en un mismo ciclo.","alignmentCues":["El 1 es un latigazo directo al otro lado.","Los cuatros se mantienen verticales."],"commonMistakes":["Lanzar el 1 en alto en vez de pasarlo.","Olvidar el segundo cuatro."]},"siteswap-52512":{"name":"52512","description":"Dos cincos altos separados por una retención, luego un cinco, un pase rápido y una retención. El patrón mezcla lanzamientos altos cruzados con otros cortos y bajos.","goodFor":"Control preciso del alto-bajo con tres pelotas.","alignmentCues":["Los cincos llegan todos a la misma altura.","Los 2 se quedan en la mano."],"commonMistakes":["Lanzando los 2.","Cincos desiguales."]},"high-low-shower":{"name":"Cascada circular alta-baja","description":"Una cascada circular con un giro: una pelota sube muy alto mientras las demás pasan zumbando por debajo, bajas y rápidas. El ritmo suena a galope.","goodFor":"Gran contraste de alturas y manos rápidas en un patrón de tres pelotas.","alignmentCues":["El siete va alto y recto.","Los 1 son pases planos."],"commonMistakes":["Los sietes se desvían hacia delante.","Los 1 se arquean demasiado."]},"siteswap-612":{"name":"612","description":"Un lanzamiento propio bien alto, un pase rápido y una retención. El seis sube junto a ti, sin cambiar de lado, mientras las otras dos pelotas se cruzan por debajo.","goodFor":"Lanzamientos propios altos mezclados con pases bajos y rápidos.","alignmentCues":["El seis se queda en su lado.","Pasa el 1 plano y rápido."],"commonMistakes":["El seis se está cruzando.","Demasiada retención en el 2."]},"three-in-one":{"name":"Tres en una mano","description":"Tres pelotas en el aire usando solo la mano derecha, en columnas altas o en una fuente pequeña. Cada lanzamiento es bien alto, así que hay tiempo para atrapar y volver a lanzar.","goodFor":"Control con una sola mano y constancia en la altura.","alignmentCues":["Los lanzamientos llegan bien por encima de la cabeza.","Mantén la mano dibujando un círculo pequeño."],"commonMistakes":["Los lanzamientos se abren hacia fuera.","Lanzamientos demasiado bajos para mantener las tres."]},"columns":{"name":"Columnas","description":"Tres pelotas subiendo en columnas verticales. Las dos manos lanzan a la vez sus pelotas exteriores y luego la derecha lanza sola la del centro. Arriba, arriba, arriba, como pistones.","goodFor":"Primeros lanzamientos simultáneos y base para muchos trucos en síncrono.","alignmentCues":["Las columnas exteriores suben juntas.","La columna central sube recta desde el centro."],"commonMistakes":["Las columnas se inclinan y las pelotas chocan.","Ritmo desigual en la pareja."]},"infinity":{"name":"Infinito","description":"Un patrón de columnas en el que el lanzamiento suelto cruza en vez de subir recto, así que la pelota del centro cambia de lado cada vez. Las pelotas dibujan un ocho.","goodFor":"Cambiar de lado un patrón en síncrono.","alignmentCues":["La pareja sube recta, el suelto cruza.","Los lados se alternan en cada ciclo."],"commonMistakes":["El suelto sube recto por inercia.","La pareja se desvía."]},"rainbow-cross":{"name":"Cruce Arcoíris","description":"Dos pelotas se cruzan entre sí en pareja y luego una sube recta por el medio. Los arcos cruzados forman un arcoíris sobre tu cabeza.","goodFor":"Lanzamientos cruzados sincronizados sin colisiones.","alignmentCues":["Un lanzamiento cruzado ligeramente por delante del otro.","El lanzamiento central sube recto."],"commonMistakes":["Las pelotas chocan al cruzarse.","El lanzamiento central se inclina."]},"crossunder":{"name":"cruce inferior","description":"Todos los lanzamientos se cruzan: una pareja cruzada y luego un lanzamiento cruzado individual que cambia de lado en cada ciclo. Las pelotas se trenzan por encima y por debajo.","goodFor":"Control sincronizado con todos los lanzamientos cruzados.","alignmentCues":["Mantén los lanzamientos cruzados en planos ligeramente distintos.","Altura uniforme en todo el patrón."],"commonMistakes":["Choques en el centro.","El lanzamiento individual es demasiado corto."]},"yo-yo":{"name":"Yo-yo","description":"Una mano lanza columnas mientras la otra sostiene una pelota y la mueve arriba y abajo por debajo de una de ellas, como si las dos pelotas estuvieran unidas por un hilo.","goodFor":"Una ilusión que enseña a mover una pelota sostenida junto a una columna.","alignmentCues":["La pelota sostenida imita el movimiento de la pelota de la columna.","Las columnas se mantienen verticales."],"commonMistakes":["La pelota sostenida se queda atrás.","Las columnas se van separando."]},"box":{"name":"La Caja","description":"Las pelotas dibujan un cuadrado. Una mano lanza una pelota hacia arriba mientras la otra pasa una pelota al otro lado, y luego intercambian roles. Lados altos, parte superior e inferior planas.","goodFor":"Un patrón clásico en sincronía que entrena los pases horizontales.","alignmentCues":["Los pases cruzan rectos a la altura de la mano.","Los lanzamientos verticales suben rectos."],"commonMistakes":["Los pases arquean demasiado alto.","Las columnas se inclinan hacia adentro."]},"broken-box":{"name":"La Caja Rota","description":"Una caja que cambia de lado en cada lanzamiento: el lanzamiento vertical y el pase cruzado alternan de mano, así que el cuadrado se pliega sobre sí mismo una y otra vez.","goodFor":"Cambio de roles rápido y sincronizado.","alignmentCues":["Alterna el lanzamiento vertical en cada beat.","Pasa plano y rápido."],"commonMistakes":["Repetir el lanzamiento vertical en el mismo lado.","Apresurar el pase."]},"als-slide":{"name":"Diapositiva de Al","description":"Un lanzamiento alto cruzado combinado con un pase plano, luego una retención y otro lanzamiento alto cruzado. Las pelotas se deslizan por arriba y por abajo en un movimiento suave y fluido.","goodFor":"Lanzamientos cruzados sincronizados combinados con pases y retenciones.","alignmentCues":["Los 4 cruzados llegan a su punto más alto a la vez.","Mantén el 2 quieto."],"commonMistakes":["Lanzando la bola que sujetas.","Chocando en el centro."]},"factory":{"name":"Fábrica","description":"Una mano funciona como una cinta transportadora, llevando bolas de lado a lado a la altura de la cintura, mientras la otra lanza columnas. Las bolas giran en un ciclo mecánico.","goodFor":"Coordinación de llevar y lanzar en un ritmo síncrono.","alignmentCues":["La mano que lleva se mueve en un bucle amplio.","Los lanzamientos verticales se mantienen altos."],"commonMistakes":["La mano que lleva deja caer las bolas en la columna.","Las columnas se inclinan."]},"broken-shower":{"name":"Ducha rota","description":"Una ducha síncrona: la mano derecha lanza alto cruzando mientras la izquierda pasa bajo al mismo tiempo. Las bolas circulan en un bucle cerrado.","goodFor":"Una versión síncrona del bucle de la ducha.","alignmentCues":["Las dos manos sueltan a la vez.","Arco alto para la derecha, pase plano para la izquierda."],"commonMistakes":["Soltando una tras otra.","El pase sube en arco hacia la bola alta."]},"crossed-arm-shower":{"name":"Ducha con brazos cruzados","description":"La ducha con los antebrazos cruzados. Los lanzamientos altos salen del lado izquierdo de tu cuerpo y los pases rápidos vuelven por debajo.","goodFor":"Control de la ducha en una posición de brazos poco habitual.","alignmentCues":["Mantén los brazos cruzados todo el tiempo.","Pasa cerca del cuerpo."],"commonMistakes":["Descruzando los brazos para atrapar.","Pases demasiado altos."]},"siteswap-534":{"name":"534","description":"Un patrón de cuatro bolas que mezcla un cinco cruzado, un tres en cascada y un cuatro a la misma mano. Se siente como un 423 de cuatro bolas y enlaza perfectamente con la fuente.","goodFor":"El truco de cuatro bolas más popular, y una puerta de entrada a siteswaps más altos.","alignmentCues":["El cinco más alto, el tres más bajo.","El cuatro se queda en su lado."],"commonMistakes":["Aplanando las alturas.","Apresurando el tres."]},"siteswap-552":{"name":"552","description":"Dos cincos cruzados y una bola quieta. Se malabarean cuatro bolas en un ritmo de cinco bolas, con un tiempo para respirar.","goodFor":"Lanzamientos a altura de cinco con tiempo para recuperarte.","alignmentCues":["Ambos cincos idénticos.","Mantén el 2 quieto."],"commonMistakes":["Lanzando la bola que hay que sujetar.","Los cincos se adelantan."]},"siteswap-5551":{"name":"5551","description":"Tres cincos seguidos y un pase rápido. Un buen peldaño hacia la cascada de cinco bolas.","goodFor":"Practicar series de cincos con cuatro bolas.","alignmentCues":["Los cincos, todos a la misma altura.","Pase plano y rápido para el 1."],"commonMistakes":["Los cincos bajan poco a poco.","Lanzando el 1 en arco."]},"siteswap-55550":{"name":"55550","description":"Cuatro cincos y una mano vacía. Una cascada de cinco pelotas a la que le falta una pelota, lo que la convierte en un gran ensayo para cinco.","goodFor":"El último paso antes de la cascada de cinco pelotas.","alignmentCues":["Aprovecha el hueco para asentarte.","Cincos consistentes."],"commonMistakes":["Lanzando hacia el hueco.","Cincos desviándose."]},"siteswap-633":{"name":"633","description":"Un self alto y luego dos lanzamientos de cascada. El seis flota arriba mientras la cascada corre por debajo.","goodFor":"Selfs altos tejidos en un ritmo de cuatro pelotas.","alignmentCues":["El seis se queda sobre su propia mano.","Los tres se mantienen bajos."],"commonMistakes":["El seis se desvía hacia el otro lado.","Tres demasiado altos."]},"siteswap-53":{"name":"53","description":"Una mano lanza cincos cruzados en alto mientras la otra lanza tres de cascada a baja altura. Un shower mitad y mitad con cuatro pelotas.","goodFor":"Control de alturas entre las dos manos.","alignmentCues":["Mano derecha alta, mano izquierda baja.","Ritmo parejo."],"commonMistakes":["Las alturas se van igualando.","Apurando los tres."]},"wimpy":{"name":"Patrón Wimpy","description":"Cuatro pelotas donde cada par cruza a la vez. Los arcos cambian de lado en cada tiempo, en un amplio cruce.","goodFor":"Sincronía de cruces con cuatro pelotas.","alignmentCues":["Una mano lanza un poco más adelante.","Suelta a la vez."],"commonMistakes":["Chocando en el medio.","Desfasando la suelta."]},"four-ball-shower":{"name":"Shower de cuatro pelotas","description":"Cuatro pelotas en círculo: lanzamientos muy altos de una mano y pases planos de la otra.","goodFor":"Consistencia en los lanzamientos altos con cuatro pelotas.","alignmentCues":["Sietes altos y rectos.","Pases rápidos y planos."],"commonMistakes":["Sietes desviándose hacia adelante.","Pases subiendo."]},"tsunami":{"name":"Tsunami","description":"Un siete alto, una retención, un self de cuatro, un pase y un self de seis bien alto. Olas de altura recorren el patrón.","goodFor":"Control avanzado de alturas mixtas con cuatro pelotas.","alignmentCues":["Aprende los lanzamientos despacio y en orden.","El siete y el seis van ambos en alto."],"commonMistakes":["Alturas inconsistentes.","Perdiendo la cuenta."]},"siteswap-645":{"name":"645","description":"La versión a cinco bolas del 534: un seis alto a la misma mano, un cuatro a la misma mano y un cinco cruzado.","goodFor":"Un primer truco a partir de la cascada a cinco bolas.","alignmentCues":["El seis, el más alto.","El cuatro se queda en su lado."],"commonMistakes":["Alturas que se igualan.","Deriva."]},"siteswap-744":{"name":"744","description":"Un siete cruzado muy alto seguido de dos cuatros a la misma mano.","goodFor":"Inserción de lanzas altas a cinco bolas.","alignmentCues":["Siete recto y alto.","Cuatros verticales."],"commonMistakes":["El siete deriva.","Los cuatros se cruzan."]},"five-ball-shower":{"name":"Ducha a cinco bolas","description":"Cinco bolas en bucle: nueves altísimos desde una mano y pases planos de vuelta por debajo.","goodFor":"Altura y precisión en lo más alto de la escala.","alignmentCues":["Nueves rectos y constantes.","Pases planos."],"commonMistakes":["Los nueves derivan.","Los pases suben."]},"five-ball-half-shower":{"name":"Media ducha a cinco bolas","description":"Lanzas cruzadas en síncrono, una mano más alta que la otra, con cinco bolas.","goodFor":"Control de cruces en síncrono a cinco bolas.","alignmentCues":["Derecha más alta, izquierda más baja.","Suelta a la vez."],"commonMistakes":["Alturas que convergen.","Choques."]},"martins-one-count":{"name":"Patrón de Martin","description":"Un multiplex: un seis alto y una bola retenida se sueltan a la vez, luego una retención y un cinco cruzado.","goodFor":"Sincronización del multiplex a cinco bolas.","alignmentCues":["El multiplex se suelta limpio.","El cinco cruza."],"commonMistakes":["El multiplex se separa.","El seis deriva."]},"six-ball-fountain":{"name":"Fuente a seis bolas","description":"Tres bolas en cada mano, malabareadas en fuentes altas en paralelo.","goodFor":"El hito de los números a seis bolas.","alignmentCues":["Cada mano lleva su propia fuente.","Lanzas altas y constantes."],"commonMistakes":["Las fuentes derivan juntas.","Lanzas demasiado bajas."]},"club-swing":{"name":"Giro simple de maza","description":"Sostén una maza por el mango, con el pomo encajado en la base de la palma. Balancéala desde la cintura hacia arriba para que dé un giro en el aire y el mango llegue primero a la otra mano. Devuélvela de la misma manera.","goodFor":"Aprender el giro simple en el que se basan todos los patrones de mazas.","alignmentCues":["Impulsa desde el codo y deja que la muñeca haga girar la maza.","Atrapa el mango a la altura de la cintura."],"commonMistakes":["Azotar la muñeca, haciendo que la maza gire de más.","Lanzar hacia adelante hace que el mango caiga demasiado lejos."]},"club-exchange":{"name":"Intercambio de dos mazas","description":"Una maza en cada mano. Lanza un giro simple con la derecha; en el punto más alto, lanza la maza izquierda por debajo. Atrapa ambas por el mango, haz una pausa y luego guía con la otra mano.","goodFor":"Sincronizar dos mazas girando sin choques.","alignmentCues":["La segunda maza sale en el punto más alto de la primera.","Lanzar la segunda maza por dentro de la primera."],"commonMistakes":["Las mazas se entrechocan en el centro.","Giro desigual entre las manos."]},"club-cascade":{"name":"Cascada de tres mazas","description":"La cascada con mazas, donde cada una da un giro. Los lanzamientos salen del centro del cuerpo y cruzan al otro lado, con los mangos siempre apuntando hacia ti.","goodFor":"El patrón base de todos los malabares con mazas.","alignmentCues":["Lanza desde el codo y mantén las muñecas sueltas.","Las mazas se mantienen paralelas a tu pecho."],"commonMistakes":["Las mazas se inclinan y giran de lado.","Giran demasiado rápido y chocan con el cuerpo."]},"club-doubles":{"name":"Dobles con mazas","description":"Una cascada de tres mazas donde cada maza da dos giros en el aire. Los lanzamientos son más altos y más lentos, y las mazas se difuminan en grandes círculos.","goodFor":"Control del giro y la altura necesaria para cuatro mazas.","alignmentCues":["Impulsa más desde el brazo, no desde la muñeca.","Mantén el doble giro suave y uniforme."],"commonMistakes":["Azotar la muñeca y dar giros de más.","Lanzar los dobles demasiado bajos."]},"club-flats":{"name":"Flats con mazas","description":"Una cascada donde las mazas no giran en absoluto. Cada maza cruza flotando con el mango hacia abajo, empujada hacia arriba por una muñeca recta, y se atrapa en vertical.","goodFor":"Control de muñeca y un contraste fácil con los lanzamientos con giro.","alignmentCues":["Bloquea la muñeca y empuja desde el codo.","La maza se mantiene vertical durante todo el recorrido."],"commonMistakes":["Medios giros accidentales.","Lanzar demasiado alto hace que la maza se tambalee."]},"club-under-leg":{"name":"Maza bajo la pierna","description":"Una cascada de mazas donde cada sexto lanzamiento pasa bajo la pierna derecha. Sube la rodilla, pasa la maza bajo el muslo y deja que gire hacia arriba para volver al patrón.","goodFor":"El primer lanzamiento bajo el cuerpo con mazas.","alignmentCues":["Rodilla arriba temprano.","Un poco de altura extra en el lanzamiento bajo la pierna."],"commonMistakes":["Golpear la pierna con la maza.","Inclinarse hacia delante en vez de levantar la rodilla."]},"club-behind-back":{"name":"Maza por detrás de la espalda","description":"Una cascada de mazas en la que cada sexto lanzamiento se balancea por detrás de la cintura y se envía sobre el hombro contrario hacia el patrón.","goodFor":"Lanzamientos de maza a ciegas por detrás del cuerpo.","alignmentCues":["Balancea el brazo hacia atrás con antelación.","Apunta sobre el hombro contrario."],"commonMistakes":["La maza cae demasiado adelante.","Girando el torso."]},"club-four-fountain":{"name":"Fuente de cuatro mazas","description":"Dos mazas en cada mano, y cada mano lanza dobles en su propia fuente. Las mazas nunca cruzan el centro.","goodFor":"El hito de las cuatro mazas.","alignmentCues":["Dobles en su propio lado.","Las manos se alternan de forma uniforme."],"commonMistakes":["Las mazas se desvían hacia el centro.","Giros desiguales entre las manos."]},"ring-cascade":{"name":"Cascada de tres aros","description":"La cascada con los aros sujetos de canto, como un volante visto de lado. Cada aro vuela por el patrón sin girar, así que los cantos cortan el aire con limpieza.","goodFor":"Una forma sencilla de probar los aros y sentir cómo flotan.","alignmentCues":["Sujeta el aro de canto frente a ti.","Suelta con la muñeca recta."],"commonMistakes":["Aros que se tambalean por una muñeca doblada.","Lanzarlos de frente para que el viento los desvíe."]},"ring-pancakes":{"name":"Pancakes de aro","description":"Una cascada de aros en la que cada aro se voltea plano en el punto más alto del lanzamiento y vuelve a quedar de canto para la recepción, como una tortita que se da la vuelta en la sartén.","goodFor":"Control de muñeca y un floreo de aros vistoso.","alignmentCues":["Un giro rápido de muñeca al soltar.","Atrapa el aro de nuevo de canto."],"commonMistakes":["Voltear en exceso.","Lanzar tan bajo que el aro no llega a girar."]},"ring-four-fountain":{"name":"Fuente de cuatro aros","description":"Dos aros en cada mano, malabareados en fuentes separadas, con los cantos cortando recto hacia arriba y abajo.","goodFor":"Cuatro objetos con un prop ligero y flotante.","alignmentCues":["Los aros se mantienen de canto.","Cada mano lleva su propia columna."],"commonMistakes":["Los aros se tocan en el centro.","Lanzamientos que se desvían hacia adelante."]},"hoop-juggle-single":{"name":"Lanzamiento con un solo aro","description":"Sujeta un aro por el borde, colgando a tu lado. Lánzalo en un arco suave hacia la otra mano, de modo que viaje de canto y llegue a la misma altura desde la que salió.","goodFor":"Aprender cómo vuela un aro de tamaño completo antes de añadir más.","alignmentCues":["Mantén el aro de canto hacia tu pecho.","Lanza desde el hombro, no desde la muñeca."],"commonMistakes":["Lanzarlo de cara hace que flote y se aleje.","Lanzar bajo y agarrar."]},"hoop-juggle-exchange":{"name":"Intercambio de dos aros","description":"Un aro en cada mano. Lanza el aro derecho; cuando llega al punto más alto, lanza el izquierdo por debajo. Los aros pasan cerca, uno delante del otro.","goodFor":"El ritmo con dos aros y evitar que choquen.","alignmentCues":["El segundo aro en el punto más alto del primero.","Lanza el segundo un poco por delante."],"commonMistakes":["Los aros chocan entre sí.","Lanzar los dos demasiado rápido."]},"hoop-juggle-cascade":{"name":"Cascada de tres aros","description":"La cascada con aros de tamaño completo. Las manos se mantienen separadas, los lanzamientos son amplios y lentos, y cada aro gira de canto a lo largo del patrón.","goodFor":"El patrón base de los malabares con aros.","alignmentCues":["Brazos abiertos, codos relajados.","Todos los aros en el mismo plano."],"commonMistakes":["Los aros se desvían hacia adelante.","Apresurar los lanzamientos."]},"hoop-juggle-reverse":{"name":"Cascada inversa de aros","description":"Aros lanzados desde fuera por arriba y atrapados por dentro: la cascada inversa en grande.","goodFor":"Lanzamientos exteriores con aros.","alignmentCues":["Lanza desde fuera, por arriba.","Atrapa cerca del centro."],"commonMistakes":["Los aros caen demasiado abiertos.","Arcos desiguales."]},"hoop-juggle-shower":{"name":"Ducha de aros","description":"Tres aros en círculo: lanzamientos altos desde una mano y pases rápidos de vuelta por debajo.","goodFor":"Control de la altura y del pase con aros.","alignmentCues":["Lanzamientos altos, rectos hacia arriba y cruzados.","Pasa cerca del cuerpo."],"commonMistakes":["Los lanzamientos altos se desvían.","Los pases suben."]},"hoop-juggle-two-in-one":{"name":"Dos aros en una mano","description":"Dos aros lanzados solo con la mano derecha, subiendo en columnas a tu lado.","goodFor":"Control del aro con una mano.","alignmentCues":["Las columnas se mantienen verticales.","Lanza alto para ganar tiempo."],"commonMistakes":["Los aros se desvían hacia afuera.","Demasiado bajo."]},"hoop-juggle-423":{"name":"Aro 423","description":"El siteswap 423 con tres aros: un cuatro self, un dos retenido y un tres cruzado.","goodFor":"Variedad de siteswaps con aros.","alignmentCues":["El cuatro se queda en su lado.","Retén el 2."],"commonMistakes":["Lanzando el 2.","El cuatro desplazándose al otro lado."]},"hoop-juggle-441":{"name":"441 con aros","description":"Dos cuatros self y un pase de mano rápido con aros. El pase de mano se desliza bajo el par alto.","goodFor":"Pases de mano rápidos entre lanzamientos altos de aros.","alignmentCues":["Cuatros verticales.","Pase de mano plano."],"commonMistakes":["Pase de mano en parábola.","Cuatros desplazándose."]},"hoop-juggle-four":{"name":"Fuente de cuatro aros","description":"Dos aros en cada mano, en fuentes lado a lado.","goodFor":"El hito de los cuatro aros.","alignmentCues":["Cada lado por separado.","Ritmo uniforme."],"commonMistakes":["Aros desplazándose juntos.","Lanzamientos demasiado bajos."]},"hoop-juggle-under-leg":{"name":"Aro bajo la pierna","description":"Una cascada de aros donde cada sexto lanzamiento pasa por debajo de la pierna derecha levantada.","goodFor":"Lanzamientos corporales con un accesorio grande.","alignmentCues":["Levanta la rodilla bien alto.","Lanza un poco más alto."],"commonMistakes":["El aro rozando el pie.","Inclinándote hacia adelante."]},"hoop-juggle-back-throw":{"name":"Lanzamiento de aro por la espalda","description":"Una cascada de aros donde cada sexto lanzamiento va por detrás de la espalda y por encima del hombro lejano.","goodFor":"Lanzamientos a ciegas con aros.","alignmentCues":["Empieza el swing por detrás antes.","Por encima del hombro lejano."],"commonMistakes":["El aro aterrizando delante.","Girando el torso."]},"hoop-juggle-body-hoop":{"name":"Malabares mientras giras el aro en la cintura","description":"Mantén un aro girando en la cintura mientras haces malabares con tres más en cascada. Las caderas llevan su propio ritmo bajo los brazos.","goodFor":"Repartir la atención entre el aro en la cintura y los malabares.","alignmentCues":["Las caderas impulsan el aro del cuerpo, los brazos se mantienen independientes.","Mantén el plano de los malabares delante del aro del cuerpo."],"commonMistakes":["El aro del cuerpo se frena al concentrarte en los malabares.","Los brazos caen dentro del aro del cuerpo."]},"pass-one-ball":{"name":"Pase con una bola","description":"Colócate frente a tu pareja a unos dos metros y medio de distancia. Lanza una bola desde tu mano derecha en un arco suave hacia su mano izquierda. Tu pareja se la pasa a su mano derecha y te la lanza de vuelta a tu izquierda, y tú la vuelves a pasar a tu derecha.","goodFor":"Aprender la altura y la distancia del pase antes de hacer malabares.","alignmentCues":["Lanza recto hacia el otro lado, sin cruzar.","El punto más alto queda justo por encima de la cabeza, a mitad de camino entre los dos.","Mira a tu pareja, no la bola que tienes en la mano."],"commonMistakes":["Lanzar a la cara de tu pareja en vez de hacer un arco hacia arriba.","Apuntar a su mano derecha, haciendo que el pase se cruce."]},"pass-hand-across":{"name":"Pase con dos bolas","description":"Dos bolas cada uno. Los dos pasan desde la derecha en el mismo tiempo. Cada mano izquierda atrapa el pase que llega y lo entrega directamente a la mano derecha, lista para el siguiente pase. No se lanza nada a uno mismo, así que todo consiste en sincronizar los pases.","goodFor":"Pasar en un tiempo compartido antes de añadir la cascada.","alignmentCues":["Pasa a la vez: mano derecha en la cuenta.","Atrapa con la izquierda y pásala a la derecha, rápido y por abajo."],"commonMistakes":["Uno de los dos pasa antes de tiempo, y los pases se cruzan en el aire en momentos distintos.","Lanzar la bola de la izquierda a la derecha en vez de entregarla."]},"pass-six-count":{"name":"Seis tiempos","description":"Los dos hacen una cascada de tres bolas y pasan cada sexto lanzamiento, siempre desde la mano derecha hacia la izquierda de tu pareja. Entre pase y pase tienes cinco selfs para asentar el patrón.","goodFor":"El primer patrón de pases completo: hay mucho tiempo entre pase y pase.","alignmentCues":["Cuenta en voz alta: pase, dos, tres, cuatro, cinco, seis.","Mantén tus selfs a la misma altura que el pase.","Mira a tu pareja, no tus propias manos."],"commonMistakes":["Perder la cuenta y pasar en el tiempo equivocado.","Pasar corto, obligando a tu pareja a abalanzarse."]},"pass-four-count":{"name":"Cuatro tiempos","description":"Pasa cada cuarto lanzamiento, es decir, cada dos lanzamientos con la derecha. Pase, self, self, self, y vuelve a pasar. Es el calentamiento estándar de passing con mazas y la base de la mayoría de las variaciones.","goodFor":"El patrón de pases de siempre; la mayoría de los trucos empiezan desde aquí.","alignmentCues":["Las derechas pasan a la vez.","Tres selfs, y el pase vuelve a llegar."],"commonMistakes":["Reducir los selfs para ganar tiempo para el pase.","Girar los hombros para lanzar en vez de usar el antebrazo."]},"pass-three-count":{"name":"Tres Tiempos","description":"Pasa cada tercer lanzamiento, así los pases alternan de mano: derecha, luego izquierda, luego derecha. Cada pase con la izquierda va recto hacia la mano derecha de tu pareja.","goodFor":"Pasar con ambas manos y atrapar pases con ambas.","alignmentCues":["Los pases con la izquierda van rectos, como los de la derecha.","Mantén la misma altura de pase con ambas manos."],"commonMistakes":["Un pase débil con la izquierda que se queda corto.","Cruzar el pase de la izquierda hacia su mano izquierda."]},"pass-two-count":{"name":"Dos Tiempos","description":"Cada lanzamiento con la derecha es un pase y cada lanzamiento con la izquierda es un self. Pase, self, pase, self. El doble de pases que en un cuatro tiempos, con el mismo juego de pies.","goodFor":"Ritmo de pase rápido y uniforme; la puerta de entrada a los patrones de siete objetos.","alignmentCues":["La derecha pasa, la izquierda lanza selfs.","Mantén el self izquierdo por dentro, bajo el pase que llega."],"commonMistakes":["Dejar que los selfs bajen cada vez más.","Atrapar los pases demasiado cerca del cuerpo."]},"pass-left-two-count":{"name":"Dos Tiempos con la Izquierda","description":"El dos tiempos en espejo: cada lanzamiento con la izquierda es un pase, recto hacia la mano derecha de tu pareja, y la derecha lanza selfs.","goodFor":"Equilibrar tu mano de pase más débil.","alignmentCues":["Los pases con la izquierda van rectos, sin cruzar.","La misma altura y empuje que tus pases con la derecha."],"commonMistakes":["Pasar corto con la mano débil.","Volver por costumbre a los pases con la derecha."]},"pass-ultimates":{"name":"The Ultimates","description":"Cada lanzamiento es un pase. Las derechas pasan recto hacia las izquierdas y las izquierdas pasan recto hacia las derechas; nadie lanza selfs. Las bolas forman un flujo constante entre los dos.","goodFor":"Precisión y ritmo de pase bajo presión.","alignmentCues":["Cada lanzamiento cruza: derecha, izquierda, derecha, izquierda.","Atrapa y pasa en una sola cuchara fluida."],"commonMistakes":["Quedarte con una bola en la mano y cortar el flujo.","Pases cada vez más planos cuando sube el tempo."]},"club-pass-four-count":{"name":"Cuatro Tiempos con Mazas","description":"El cuatro tiempos con mazas. Cada pase es una vuelta sencilla lanzada desde la derecha hacia la izquierda de tu pareja, llegando con el mango por delante. Tres selfs sencillos entre pases.","goodFor":"El inicio estándar de toda sesión de pases con mazas.","alignmentCues":["Pasa desde el lado de la cadera derecha con un swing recto hacia adelante.","Una vuelta sencilla: el mango debe caer en la mano de tu pareja."],"commonMistakes":["Darle demasiadas vueltas, de modo que el pase llega con el pomo por delante.","Pasar cruzando el cuerpo hacia la derecha de tu pareja."]},"club-pass-two-count":{"name":"Dos Tiempos con Mazas","description":"Cada lanzamiento con la derecha es un pase sencillo y cada lanzamiento con la izquierda es un self sencillo. El ritmo esencial de los pases con mazas.","goodFor":"Ritmo constante de pases con mazas.","alignmentCues":["Pase, self, pase, self, en los tiempos pares.","Mantén el self izquierdo compacto y por dentro."],"commonMistakes":["El self izquierdo pierde giro.","Los pases se desvían a izquierda y derecha."]},"club-pass-three-count":{"name":"Tres Tiempos con Mazas","description":"Con mazas, el pase sale cada tercer lanzamiento, así que van alternando de mano. Los pases de la mano izquierda van directos hacia la mano derecha de tu pareja.","goodFor":"Pases de mazas con la mano menos hábil.","alignmentCues":["El mismo swing con las dos manos.","Derecha, luego izquierda, luego derecha: ve contando."],"commonMistakes":["Los pases con la izquierda salen con muy poco giro.","Giras el cuerpo para el pase con la izquierda."]},"club-pass-doubles":{"name":"Cuatro Tiempos con Mazas y Dobles","description":"Un cuatro tiempos donde cada pase es un doble, lanzado más alto para que caiga un tiempo más tarde. Para hacer espacio, la mano izquierda retiene su maza un tiempo tras el pase en lugar de lanzarla.","goodFor":"El pase doble, el primer paso hacia los pases con siete mazas.","alignmentCues":["Un pase doble es más alto y más lento: dos vueltas completas.","Sostén la maza izquierda durante el pase, luego continúa."],"commonMistakes":["Lanzas el doble tan rápido como un sencillo, así que gira de más.","Lanzas la maza izquierda en lugar de sostenerla."]},"club-pass-ultimates":{"name":"Ultimates con Mazas","description":"Cada lanzamiento es un pase sencillo, alternando derecha e izquierda. Seis mazas fluyen entre los dos, sin selfs.","goodFor":"Precisión en los pases con mazas a pleno ritmo.","alignmentCues":["Atrapa y pasa en un solo swing.","Pases rectos: de derecha a izquierda y de izquierda a derecha."],"commonMistakes":["Los pases se van al centro y chocan.","Retienes una maza y cortas el flujo."]},"club-pass-seven-doubles":{"name":"Dobles Cruzados con Siete Mazas","description":"Siete mazas entre los dos. Tu mano derecha lanza un doble cruzado a la mano derecha de tu pareja cada dos lanzamientos, y su mano izquierda responde un lanzamiento después con un doble cruzado hacia tu izquierda. Los sencillos llenan los huecos.","goodFor":"Un primer patrón de siete mazas, construido sobre los dobles.","alignmentCues":["Tus dobles cruzan hacia la mano derecha de tu pareja.","Atrapa su doble con tu izquierda, justo después de tu propio pase."],"commonMistakes":["Pases rectos en lugar de cruzados.","Dobles demasiado bajos para completar dos vueltas."]},"staff-wheel-spin":{"name":"Giro de rueda a dos manos","description":"Sostén el staff por el centro con ambas manos, palmas hacia abajo, a la altura del pecho. Gíralo a tu lado como una rueda pasando la rotación entre las manos, manteniéndolo junto a tu cuerpo.","goodFor":"El primer giro de staff; desarrolla el agarre y la rotación de muñeca.","alignmentCues":["El staff se mantiene paralelo a tu cuerpo, sin inclinarse.","Agarre suave: deja que ruede entre los dedos."],"props":["bastón"],"commonMistakes":["Apretar tanto que el giro se detiene.","Inclinar el plano hacia adelante."]},"staff-front-spin":{"name":"Molino frontal","description":"Gira el staff frente a ti como una hélice, en el plano de pared, pasándolo suavemente de mano en mano alrededor de su centro.","goodFor":"Añade el plano de pared y el paso mano sobre mano.","props":["bastón"]},"staff-figure-8":{"name":"Tejido en ocho","description":"Gira el staff en el plano de rueda a tu lado derecho, luego crúzalo hacia tu lado izquierdo y gira allí, trazando un ocho frente a ti.","goodFor":"Conecta ambos lados del cuerpo; la base del flow con staff.","alignmentCues":["Cambia de lado cuando las puntas pasen por el suelo.","Rota un poco el torso con cada lado."],"props":["bastón"]},"staff-pass-through":{"name":"Paso a través","description":"Gira en el plano de pared pero suelta en cada media vuelta: una mano libera el staff y la otra lo atrapa por el centro, de modo que el staff pasa entre tus manos.","goodFor":"Enseña el timing de soltar y atrapar.","props":["bastón"]},"staff-one-hand-spin":{"name":"Giro a una mano","description":"Gira el staff frente a ti con una mano, haciéndolo rodar sobre el dorso de la mano y entre los dedos. Practica con ambas manos.","goodFor":"Fuerza de dedos y muñeca; libera la otra mano para trucos.","props":["bastón"]},"staff-helicopter":{"name":"Helicóptero sobre la cabeza","description":"Levanta el staff sobre tu cabeza y gíralo plano en el plano del suelo con una mano, como las aspas de un helicóptero.","goodFor":"Introduce el plano del suelo.","props":["bastón"]},"staff-butterfly":{"name":"Mariposa","description":"Gira frente a ti, luego pliega el staff detrás de tu hombro y sácalo de nuevo, alternando frente y atrás en cada lado como alas.","goodFor":"Movilidad de hombros y una transición fluida de frente a atrás.","props":["bastón"]},"staff-behind-back-pass":{"name":"Pase por detrás de la espalda","description":"Pasa el staff girando de una mano a la otra por detrás de tu espalda en la parte baja del giro, luego tráelo de vuelta al frente.","goodFor":"Enrolles corporales y pases de exhibición.","props":["bastón"]},"staff-isolation":{"name":"Aislamiento con staff","description":"Sostén el staff cerca de un extremo y gira la mano alrededor del centro del staff, de modo que el centro parezca quedarse fijo en el aire mientras el staff gira a su alrededor.","goodFor":"Trabajo de ilusión y trayectorias de mano precisas.","props":["bastón"]},"staff-antispin-flower":{"name":"Antispin de cuatro pétalos","description":"Gira la mano en una dirección mientras el staff gira en la otra tres veces más rápido, de modo que el staff dibuja una flor de cuatro pétalos.","goodFor":"La flor VTG característica; control profundo del timing.","props":["bastón"]},"staff-neck-roll":{"name":"Rodada por el cuello","description":"Suelta el staff sobre la parte posterior de los hombros y déjalo rodar por el cuello hasta la otra mano. Empieza despacio con un staff acolchado.","goodFor":"Contact staff: el staff se mueve sobre el cuerpo sin las manos.","avoidIf":["Dolor de cuello."],"props":["bastón"]},"staff-reverse-wheel":{"name":"Giro de rueda inverso","description":"El giro de rueda en sentido contrario: el extremo delantero del báculo sube y vuelve por arriba. Las dos manos se mantienen en el medio y lo hacen rodar, exactamente igual que en el giro hacia adelante.","goodFor":"Equilibrar ambas direcciones de giro para que cada movimiento posterior funcione en cualquier sentido.","alignmentCues":["La misma rueda plana a tu lado; solo cambia la dirección.","Guía con los nudillos rodando hacia atrás."],"props":["báculo"],"commonMistakes":["El plano se desplaza cruzando el cuerpo.","Volver al giro hacia adelante sin darte cuenta."]},"staff-reverse-front-spin":{"name":"Giro frontal inverso","description":"Un giro frontal a dos manos en sentido contrario. El extremo superior cae hacia tu derecha en lugar de hacia tu izquierda.","goodFor":"Ambas direcciones del giro frontal antes de los pases o los weaves.","alignmentCues":["Mantén el báculo de frente al pecho.","Las manos se intercambian igual, solo que al revés."],"props":["báculo"],"commonMistakes":["Los extremos se inclinan hacia ti.","Perder el ritmo en el cambio de manos."]},"staff-one-hand-wheel":{"name":"Giro de rueda a una mano","description":"Gira el báculo a tu lado en el plano de rueda con una sola mano, haciéndolo rodar sobre el dorso de la mano y entre los dedos.","goodFor":"Control con una mano junto al cuerpo: la base de los aislamientos de rueda y del doble báculo.","alignmentCues":["El báculo pasa justo por fuera de la cadera.","El codo se mantiene cerca de las costillas."],"props":["báculo"],"commonMistakes":["El extremo roza la pierna.","La muñeca se bloquea."]},"staff-wheel-pass":{"name":"Pase de rueda","description":"Un giro de rueda que cambia de mano cada media vuelta. Cada mano toma el báculo cuando está en horizontal, lo lleva alrededor y lo entrega.","goodFor":"Cambios de mano fluidos junto al cuerpo.","alignmentCues":["Atrapa en horizontal.","La mano libre espera cerca."],"props":["báculo"],"commonMistakes":["Agarrar antes de que el báculo esté en horizontal.","El plano se desvía con cada pase."]},"staff-two-hand-helicopter":{"name":"Helicóptero a dos manos","description":"El báculo gira en horizontal sobre tu cabeza con ambas manos en él, pasando una por encima de la otra como un rotor.","goodFor":"Un primer vistazo suave al plano del suelo.","alignmentCues":["Brazos relajados, báculo justo por encima de la cabeza.","Las manos se intercambian frente a la cara."],"props":["báculo"],"commonMistakes":["El báculo se inclina hacia adelante.","Hombros encogidos."]},"staff-overhead-pass":{"name":"Pase sobre la cabeza","description":"El helicóptero se pasa de mano a mano sobre la cabeza, cada mano lo lleva media vuelta.","goodFor":"Cambios de mano en el plano del suelo.","alignmentCues":["Pase cuando el staff apunta hacia adelante y hacia atrás.","Mantén los codos relajados."],"props":["báculo"],"commonMistakes":["El staff se cae detrás de la cabeza.","Agarras demasiado pronto."]},"staff-one-hand-reverse":{"name":"Giro inverso a una mano","description":"Un giro frontal a una mano en sentido contrario, rodando primero por el lado del pulgar.","goodFor":"Control con una mano en ambas direcciones.","alignmentCues":["Mismo plano, misma velocidad, al revés.","Los dedos se relajan mientras el staff rueda."],"props":["báculo"],"commonMistakes":["Tensión en la muñeca.","El giro se frena en una mitad."]},"staff-reverse-helicopter":{"name":"Helicóptero inverso","description":"El helicóptero a una mano girando en sentido contrario sobre la cabeza.","goodFor":"Ambas direcciones sobre la cabeza.","alignmentCues":["Puntas niveladas.","La mano se mantiene sobre la frente."],"props":["báculo"],"commonMistakes":["Se inclina hacia adelante.","El brazo se estira por completo."]},"staff-extension":{"name":"Extensión","description":"Sujeta el staff cerca de un extremo y deja que trace un gran círculo alrededor de tu mano, que apenas se mueve. El extremo lejano dibuja un anillo grande frente a ti.","goodFor":"Formas grandes y el rodar de la muñeca que necesitas para las isolaciones.","alignmentCues":["La mano es el eje del círculo.","Gira la muñeca, no balancees el brazo."],"props":["báculo"],"commonMistakes":["Balanceo desde el hombro.","El círculo se aplana en un óvalo."]},"staff-wheel-extension":{"name":"Extensión de rueda","description":"Una extensión al lado del cuerpo: el staff traza una gran rueda alrededor de la mano a la altura de la cadera.","goodFor":"Círculos grandes en el plano de rueda.","alignmentCues":["Mantén el círculo por fuera de la pierna.","La muñeca gira, el brazo se queda quieto."],"props":["báculo"],"commonMistakes":["El staff roza el pie.","Te inclinas alejándote del báculo."]},"staff-floor-extension":{"name":"Extensión sobre la cabeza","description":"Una extensión plana sobre la cabeza: el báculo barre alrededor de la mano alzada como una larga aspa de rotor.","goodFor":"Alcance sobre la cabeza y una forma dramática en el plano del suelo.","alignmentCues":["Mano por encima de la cabeza.","El aspa se mantiene horizontal."],"props":["báculo"],"commonMistakes":["El báculo se hunde por detrás.","El brazo se desplaza hacia adelante."]},"staff-wheel-isolation":{"name":"Aislamiento de rueda","description":"El aislamiento junto al cuerpo: el centro del báculo se mantiene fijo mientras la mano gira a su alrededor.","goodFor":"Control del aislamiento en un segundo plano.","alignmentCues":["Elige un punto junto a tu cadera para el centro.","La mano se mueve en un círculo pequeño."],"props":["báculo"],"commonMistakes":["El centro se va de su sitio.","El plano se inclina."]},"staff-floor-isolation":{"name":"Aislamiento sobre la cabeza","description":"Un aislamiento plano sobre la cabeza, con el báculo pivotando sobre un punto fijo mientras la mano gira.","goodFor":"Aislamientos sobre la cabeza.","alignmentCues":["Punto fijo por encima de ti.","Círculo pequeño con la mano."],"props":["báculo"],"commonMistakes":["El centro se desplaza.","El círculo de la mano crece."]},"staff-isolation-pass":{"name":"Pase de aislamiento","description":"Un aislamiento que se pasa entre las manos en cada media vuelta, de modo que el punto fijo se queda quieto mientras las manos se relevan.","goodFor":"Control del aislamiento a dos manos.","alignmentCues":["Pasa en la parte baja del círculo.","Mantén el centro fijo durante el pase."],"props":["báculo"],"commonMistakes":["El centro salta en el pase.","Las manos chocan."]},"staff-antispin-3":{"name":"Antispin de tres pétalos","description":"La mano gira en un sentido y el báculo en el contrario, dibujando una flor de tres pétalos.","goodFor":"La primera flor de antispin.","alignmentCues":["Círculo de mano lento y redondo.","El báculo gira en sentido contrario."],"props":["báculo"],"commonMistakes":["Pétalos desiguales.","El círculo de la mano se deshace."]},"staff-antispin-5":{"name":"Antispin de cinco pétalos","description":"Una flor de antispin más delicada, con cinco pétalos; la mano circula más despacio, en contra del giro.","goodFor":"Sincronización precisa del antispin.","alignmentCues":["Cuenta los pétalos.","La mano se mueve despacio."],"props":["báculo"],"commonMistakes":["Los pétalos se funden.","Apretar el ritmo de la mano."]},"staff-wheel-antispin":{"name":"Antispin de rueda","description":"Una flor de antispin trazada junto al cuerpo en el plano de rueda.","goodFor":"Flores en un segundo plano.","alignmentCues":["Plano vertical.","Pétalos uniformes."],"props":["báculo"],"commonMistakes":["El plano se inclina.","Los pétalos se desvían hacia adelante."]},"staff-floor-antispin":{"name":"Antispin sobre la cabeza","description":"Una flor de antispin trazada en horizontal sobre la cabeza.","goodFor":"Flores sobre la cabeza.","alignmentCues":["Plano horizontal.","La mano por encima de la cabeza."],"props":["báculo"],"commonMistakes":["Se inclina.","Pétalos desiguales."]},"staff-inspin-3":{"name":"Inspin de tres pétalos","description":"La mano circula en el mismo sentido que el giro, pero más despacio, y el báculo traza tres pétalos que apuntan hacia adentro.","goodFor":"La flor más suave para aprender.","alignmentCues":["La mano y el báculo giran en el mismo sentido.","Círculo de la mano amplio y lento."],"props":["báculo"],"commonMistakes":["La mano se acelera para igualar el ritmo del báculo.","Pétalos desequilibrados."]},"staff-inspin-4":{"name":"Inspin de cuatro pétalos","description":"Una flor de inspin con cuatro pétalos hacia adentro.","goodFor":"Más control del inspin.","alignmentCues":["Cuenta cuatro pétalos.","Mano estable."],"props":["báculo"],"commonMistakes":["Los pétalos se funden.","La mano se desvía."]},"staff-wheel-inspin":{"name":"Inspin de rueda","description":"Un inspin de tres pétalos dibujado junto al cuerpo.","goodFor":"Inspins en el plano de rueda.","alignmentCues":["Plano vertical.","Mano lenta."],"props":["bastón"],"commonMistakes":["Se inclina.","Roza la pierna."]},"staff-reverse-figure-8":{"name":"Ocho invertido","description":"El ocho al revés: el bastón sube por delante y baja por detrás a cada lado.","goodFor":"Ambas direcciones del weave.","alignmentCues":["Cruce delante del cuerpo.","Cada lado vertical."],"props":["bastón"],"commonMistakes":["El plano se cierra en el cruce.","Torso rígido."]},"staff-front-weave":{"name":"Weave frontal","description":"Un giro frontal que pasa de un lado del cuerpo al otro en cada vuelta, mientras el pecho gira con él.","goodFor":"Mover el giro de lado a lado del cuerpo.","alignmentCues":["El pecho sigue al bastón.","El giro se mantiene de frente."],"props":["bastón"],"commonMistakes":["Los pies también giran.","El plano se inclina en el cruce."]},"staff-overhead-weave":{"name":"Weave sobre la cabeza","description":"Un helicóptero a dos manos que oscila de un lado de la cabeza al otro en cada vuelta.","goodFor":"Weave en el plano del suelo.","alignmentCues":["Extremos al mismo nivel todo el tiempo.","El torso gira con el bastón."],"props":["bastón"],"commonMistakes":["Se hunde de un lado.","La cabeza estorba."]},"staff-fountain":{"name":"Fuente","description":"Un weave a tiempo dividido en el plano de rueda: los extremos brotan hacia arriba y por encima en lados alternos, como el agua de una fuente.","goodFor":"Tiempo dividido junto al cuerpo.","alignmentCues":["Los extremos suben en lados alternos.","Mantén el cruce rápido."],"props":["bastón"],"commonMistakes":["Se deshace en un ocho sencillo.","Inclinación de planos."]},"staff-reel":{"name":"Carrete","description":"Un ocho que cambia de mano en cada cruce, con el staff enrollándose de un lado al otro.","goodFor":"Combinando weaves y pases.","alignmentCues":["Pase en el cruce.","Cada lado en vertical."],"props":["báculo"],"commonMistakes":["Agarrando demasiado pronto.","Torso rígido."]},"staff-wall-wheel-hybrid":{"name":"Híbrido Pared-Rueda","description":"En cada vuelta, el giro alterna entre el plano frontal y el plano rueda a tu lado, cambiando cuando el staff está vertical.","goodFor":"Cambiando de plano sin parar.","alignmentCues":["Cambia cuando el staff apunte recto hacia arriba.","La muñeca gira un cuarto de vuelta."],"props":["báculo"],"commonMistakes":["Cambiando en horizontal.","Perdiendo velocidad en el cambio."]},"staff-floor-wall-hybrid":{"name":"Híbrido Pared-Suelo","description":"El giro alterna entre delante de ti y por encima de la cabeza, cambiando cada vez que el staff queda en horizontal.","goodFor":"Encadenando front spins y helicópteros.","alignmentCues":["Cambia en horizontal.","Levanta el brazo con suavidad."],"props":["báculo"],"commonMistakes":["Cambiando en vertical.","Codo bloqueado."]},"staff-floor-wheel-hybrid":{"name":"Híbrido Suelo-Rueda","description":"Un helicóptero que baja a una rueda a tu lado y vuelve a subir en cada vuelta.","goodFor":"El set completo de cambios de plano.","alignmentCues":["El brazo sube y baja con suavidad.","Planos limpios."],"props":["báculo"],"commonMistakes":["Plano intermedio difuso.","La velocidad baja."]},"staff-under-leg-pass":{"name":"Pase bajo la pierna","description":"Un pase que pasa por debajo de la pierna derecha levantada cada dos pases.","goodFor":"Añadiendo las piernas a los movimientos de pase.","alignmentCues":["Levanta la rodilla alto hacia el bastón.","Dobla en las caderas con la espalda larga y siéntate sobre la rodilla de pie.","Vuelve a subir cuando el bastón pase por encima de la pierna."],"props":["báculo"],"commonMistakes":["Arquear la espalda para alcanzar hacia abajo en lugar de doblar en las caderas.","Dejar la rodilla baja, haciendo que el bastón tenga que pasar por debajo.","Apresurar el pase por debajo de la pierna."]},"staff-reverse-behind-back":{"name":"Pase por la espalda invertido","description":"El pase por la espalda recorriendo el cuerpo en sentido contrario, con el giro al revés.","goodFor":"Llevar el bastón alrededor del cuerpo en ambas direcciones.","alignmentCues":["La mano de atrás espera abajo.","Mantén el giro por detrás."],"props":["bastón"],"commonMistakes":["Perder el plano por detrás.","Detener el giro."]},"staff-fishtail":{"name":"cola de pescado","description":"El bastón se balancea adelante y atrás sobre la palma abierta, como un pez que mueve la cola, sin llegar a dar la vuelta completa.","goodFor":"Control con la mano abierta y cambio de dirección del giro.","alignmentCues":["Pivota entre el pulgar y los dedos.","Pequeños flicks de muñeca invierten el balanceo."],"props":["bastón"],"commonMistakes":["Agarrar con demasiada fuerza.","El balanceo crece demasiado."]},"staff-wheel-fishtail":{"name":"Fishtail en rueda","description":"Un fishtail al lado del cuerpo en el plano rueda.","goodFor":"Fishtails en un segundo plano.","alignmentCues":["Plano vertical.","Mano abierta."],"props":["bastón"],"commonMistakes":["Inclinación.","Agarrar."]},"staff-steering-wheel":{"name":"Volante","description":"Gira el bastón mano sobre mano con las palmas abiertas y planas, como si giraras un gran volante frente a ti.","goodFor":"Manos relajadas y contacto con la palma abierta.","alignmentCues":["Palmas planas, dedos relajados.","Mano sobre mano en la parte alta."],"props":["bastón"],"commonMistakes":["Agarrar en vez de guiar.","Los codos se abren."]},"staff-palm-spin":{"name":"Giro en palma","description":"Equilibra el centro del bastón sobre la palma alzada y plana, y deja que gire ahí como una hélice.","goodFor":"Equilibrio y un toque ligero por encima de la cabeza.","alignmentCues":["Palma plana y nivelada.","Pequeños círculos lo mantienen girando."],"props":["bastón"],"commonMistakes":["La palma se inclina.","Empujar en vez de dar un toque suave."]},"staff-hand-roll":{"name":"Roll de mano","description":"El staff rueda sobre el dorso de la mano abierta y alrededor del pulgar sin agarrarlo.","goodFor":"El primer roll de contacto de verdad.","alignmentCues":["Mano abierta y relajada.","Deja que el staff haga el trabajo."],"props":["báculo"],"commonMistakes":["Cerrar los dedos.","La mano se mueve demasiado."]},"staff-forearm-roll":{"name":"Roll de antebrazo","description":"Suelta el giro sobre el antebrazo, deja que el staff ruede sobre él y recógelo de nuevo en el giro de mano.","goodFor":"Llevar el giro al brazo y de vuelta.","alignmentCues":["Antebrazo en horizontal y quieto.","Abre la mano cuando cae."],"props":["báculo"],"commonMistakes":["El antebrazo se inclina.","Agarrar demasiado pronto."]},"staff-elbow-roll":{"name":"Roll de codo","description":"El giro pasa al hueco del codo flexionado, gira allí con la mano levantada y vuelve a la mano.","goodFor":"Control de contacto avanzado.","alignmentCues":["Antebrazo en vertical.","Codo quieto."],"props":["báculo"],"commonMistakes":["El codo baja.","El staff se resbala."]},"staff-shoulder-roll":{"name":"Roll de hombro","description":"Un giro tipo rueda que se eleva hasta la parte superior del hombro, donde gira junto a la cabeza antes de caer de vuelta a la mano.","goodFor":"Rolls de contacto en la parte alta del cuerpo.","alignmentCues":["Hombro ligeramente elevado.","La cabeza se inclina hacia el otro lado."],"props":["báculo"],"commonMistakes":["La cabeza estorba.","El hombro baja."]},"staff-chest-roll":{"name":"Roll de pecho","description":"El staff rueda en horizontal por el pecho, de una mano a la otra, y luego de vuelta.","goodFor":"Contacto con el cuerpo por delante.","alignmentCues":["Pecho elevado.","El staff se mantiene horizontal."],"props":["báculo"],"commonMistakes":["El pecho se hunde.","El staff se inclina."]},"staff-angel-roll":{"name":"Rollo de ángel","description":"Los brazos bien abiertos y el staff rueda por detrás de los hombros y a lo largo de ambos brazos, de una mano a la otra.","goodFor":"Una rodada de contact para lucirte.","alignmentCues":["Brazos en horizontal, palmas hacia arriba.","Omóplatos apretados."],"props":["báculo"],"commonMistakes":["Los brazos caen.","Cabeza adelante."]},"staff-toss":{"name":"Lanzamiento de staff","description":"Suelta el giro a una mano cuando esté horizontal, deja que dé una vuelta en el aire y atrápalo retomando el mismo giro.","goodFor":"Soltar y atrapar un staff en pleno giro.","alignmentCues":["Suelta cuando esté horizontal.","Atrapa por el medio."],"props":["báculo"],"commonMistakes":["Lanzamiento hacia adelante.","Atrapada en un extremo."]},"staff-double-toss":{"name":"Doble lanzamiento","description":"Un lanzamiento más alto, con dos vueltas completas antes de la atrapada.","goodFor":"Control de altura y de giro en el aire.","alignmentCues":["Más impulso, mismo giro.","Ojos en el medio."],"props":["báculo"],"commonMistakes":["Exceso de giro.","Desvío hacia adelante."]},"staff-flat-toss":{"name":"Lanzamiento plano","description":"Lanza el helicóptero recto hacia arriba para que gire plano en el aire, y atrápalo sobre la cabeza.","goodFor":"Lanzar en el plano del suelo.","alignmentCues":["Suelta en horizontal.","Atrapa sobre la cabeza."],"props":["báculo"],"commonMistakes":["Se inclina al soltar.","Lanzamiento hacia atrás."]},"double-staff-same-time":{"name":"Doble staff a la vez","description":"Un staff corto en cada mano, ambos girando frente a ti en la misma dirección y en sincronía.","goodFor":"El primer patrón de doble staff.","alignmentCues":["Staffs lado a lado, uno ligeramente por delante.","Las dos manos a la misma velocidad."],"props":["dos staffs cortos"],"commonMistakes":["Los staffs chocan.","Una mano va retrasada."]},"double-staff-split-time":{"name":"Doble Bastón a Tiempo Partido","description":"Ambos bastones giran en el mismo sentido, pero uno va un cuarto de giro por detrás, así que uno está vertical cuando el otro está horizontal.","goodFor":"Cada mano lleva su propio tiempo.","alignmentCues":["Uno vertical, uno horizontal.","Desfase constante."],"props":["dos bastones cortos"],"commonMistakes":["Volviendo al mismo tiempo.","Se chocan."]},"double-staff-wheels":{"name":"Doble Bastón en Ruedas","description":"Una rueda a cada lado del cuerpo, ambas girando hacia adelante al mismo tiempo.","goodFor":"Doble bastón junto al cuerpo.","alignmentCues":["Cada rueda por fuera de su cadera.","Misma velocidad."],"props":["dos bastones cortos"],"commonMistakes":["Ruedas inclinándose hacia adentro.","Las manos se van separando."]},"double-staff-split-wheels":{"name":"Doble Bastón en Ruedas a Tiempo Partido","description":"Ruedas a ambos lados, con un cuarto de giro de diferencia, como piernas al caminar.","goodFor":"Tiempo partido junto al cuerpo.","alignmentCues":["Uno arriba, uno horizontal.","Desfase constante."],"props":["dos bastones cortos"],"commonMistakes":["Sincronizándose.","Inclinándose."]},"double-staff-windmill":{"name":"Doble Bastón en Molino","description":"Ruedas a ambos lados girando en direcciones opuestas, como un molino visto de lado.","goodFor":"Direcciones opuestas en las dos manos.","alignmentCues":["Uno hacia adelante, uno hacia atrás.","Velocidad uniforme."],"props":["dos bastones cortos"],"commonMistakes":["Ambos se van hacia el mismo lado.","Velocidad irregular."]},"double-staff-reverse":{"name":"Doble Bastón en Reversa","description":"Giros frontales a tiempo partido con ambos bastones en reversa.","goodFor":"Ambas direcciones con dos bastones.","alignmentCues":["Mantén el desfase.","Ambos en el mismo plano."],"props":["dos bastones cortos"],"commonMistakes":["Se chocan.","Perdiendo el desfase."]},"double-staff-helicopters":{"name":"Helicópteros con doble bastón","description":"Un helicóptero sobre cada hombro, ambos girando en sincronía.","goodFor":"Doble bastón sobre la cabeza.","alignmentCues":["Puntas niveladas.","Brazos relajados."],"props":["dos bastones cortos"],"commonMistakes":["Puntas en contacto.","Los brazos se cansan y caen."]},"double-staff-isolations":{"name":"Aislamientos con doble bastón","description":"Un aislamiento en cada mano a la vez, con los dos centros fijos, lado a lado.","goodFor":"Dos aislamientos a la vez.","alignmentCues":["Dos puntos fijos.","Las manos giran juntas."],"props":["dos bastones cortos"],"commonMistakes":["Los centros se desplazan.","Una mano se retrasa."]},"hoop-waist":{"name":"Hula hoop en la cintura","description":"Párate con un pie ligeramente delante del otro. Sostén el hoop contra la parte baja de la espalda, lánzalo alrededor de la cintura y empuja el vientre hacia delante y hacia atrás (no en círculos) cada vez que el hoop pase por delante.","goodFor":"La primera habilidad con hoop; construye el ritmo del core.","modifications":["Usa un hoop más grande y pesado: gira más despacio."],"alignmentCues":["Balancea de delante hacia atrás, no en círculos.","Empuja el hoop cuando pase por tu vientre."],"props":["aro"],"commonMistakes":["Mover las caderas en círculos como un hula dancer.","Un hoop demasiado pequeño o ligero."]},"hoop-hand-spin":{"name":"Giro con la mano","description":"Sostén el hoop delante de ti con la mano dentro de él, pulgar hacia arriba. Empújalo para que gire alrededor de la membrana de tu mano, manteniendo el hoop plano delante de ti.","goodFor":"Base del hoop off-body.","props":["aro"]},"hoop-chest":{"name":"Hula hoop en el pecho","description":"Levanta los brazos por encima de la cabeza y haz hoop alrededor del pecho, meciendo la caja torácica de delante hacia atrás mientras mantienes las caderas quietas.","goodFor":"Aísla la caja torácica y desarrolla el control de la parte superior del cuerpo.","props":["aro"]},"hoop-lasso":{"name":"Lazo","description":"Sostén el hoop por encima de la cabeza y gíralo plano sobre ella como un lazo, con el hoop girando alrededor de tu mano.","goodFor":"Control del plano del suelo por encima de la cabeza.","props":["aro"]},"hoop-wedgie":{"name":"Calzón chino","description":"Gira el hoop en el plano de pared y atrápalo en el hueco entre el pulgar y los dedos, dejando que ruede y se balancee ahí antes de seguir girando.","goodFor":"Control del agarre y una transición fluida.","props":["aro"]},"hoop-knees":{"name":"Hula hoop en las rodillas","description":"Con los pies juntos, mantén el hoop girando alrededor de las rodillas empujándolas hacia delante y hacia atrás.","goodFor":"Práctica de hula hoop de tren inferior y escalator.","props":["aro"]},"hoop-pass":{"name":"Pase mano a mano","description":"Gira el hoop frente a ti y pásalo de una mano a la otra en cada revolución, manteniendo el plano estable.","goodFor":"Enlaza trucos fuera del cuerpo por ambos lados.","props":["aro"]},"hoop-isolation":{"name":"Isolation con hoop","description":"Mueve la mano alrededor del hoop para que su centro quede fijo en el aire frente a ti mientras el hoop gira sobre ese punto.","goodFor":"La ilusión clásica del hoop.","props":["aro"]},"hoop-escalator":{"name":"Escalera mecánica","description":"Mantén el hoop girando mientras lo bajas de la cintura a las rodillas y lo subes de nuevo al pecho, una zona del cuerpo por compás.","goodFor":"Une todas las zonas del body hooping en un solo flow.","props":["aro"]},"hoop-neck":{"name":"Hoop en el cuello","description":"Inclina ligeramente la cabeza y deja que un hoop ligero gire alrededor del cuello, guiado por pequeños impulsos de cabeza y hombros.","goodFor":"Un movimiento de show que entrena impulsos pequeños y precisos.","avoidIf":["Dolor de cuello."],"props":["aro"]},"hoop-reverse-waist":{"name":"Hula hoop invertido en la cintura","description":"Gira el aro en la cintura en el sentido contrario. Cambia el pie que va delante, lanza el aro en la nueva dirección y mantén el mismo impulso de adelante hacia atrás.","goodFor":"Equilibrando ambos sentidos para que los siguientes trucos funcionen en cualquier dirección.","alignmentCues":["Cambia el pie que va delante.","Mismo impulso, nueva dirección."],"props":["aro"],"commonMistakes":["Rodeando las caderas.","Rendirse demasiado pronto del lado débil."]},"hoop-hips":{"name":"Hula hoop en las caderas","description":"Deja que el aro baje de la cintura hasta los huesos de la cadera y mantenlo ahí con un impulso más bajo y pequeño desde la pelvis.","goodFor":"Control por debajo de la cintura y un paso hacia las rodillas.","alignmentCues":["Rodillas sueltas.","Impulso desde la pelvis, no desde el vientre."],"props":["aro"],"commonMistakes":["Déjalo resbalar hacia abajo.","Impulso demasiado grande."]},"hoop-thighs":{"name":"Aro en los muslos","description":"Con los pies juntos, mantén el aro girando alrededor de la parte superior de los muslos con un rebote de rodillas rápido y pequeño.","goodFor":"El ritmo de las piernas y la conexión entre caderas y rodillas.","alignmentCues":["Pies juntos.","Rebotes rápidos y pequeños."],"props":["aro"],"commonMistakes":["Pies separados.","Rebotes demasiado lentos."]},"hoop-reverse-chest":{"name":"Aro en el pecho en reversa","description":"Aro en el pecho en la otra dirección, con los brazos en alto y las costillas impulsando el aro.","goodFor":"Ambas direcciones en la parte alta del cuerpo.","alignmentCues":["Brazos en alto y sin estorbar.","La caja torácica se mece de adelante hacia atrás."],"props":["aro"],"commonMistakes":["Brazos bajando hacia el aro.","Las caderas hacen el trabajo."]},"hoop-shoulder":{"name":"Aro en los hombros","description":"El aro gira alrededor de los hombros y la parte superior del pecho con los brazos levantados sobre la cabeza.","goodFor":"Aro en la parte alta del cuerpo.","alignmentCues":["Brazos estirados hacia arriba.","Pequeños impulsos de hombros."],"props":["aro"],"commonMistakes":["Brazos doblándose hacia adentro.","El aro se resbala hacia el pecho."]},"hoop-arm":{"name":"Aro en el brazo","description":"Levanta un brazo estirado hacia arriba y haz girar el aro alrededor del antebrazo; la mano dibuja un pequeño círculo para mantenerlo en movimiento.","goodFor":"Aro en las extremidades y sensación de lasso con el brazo en alto.","alignmentCues":["Brazo estirado, mano sobre la cabeza.","Pequeño círculo con la mano."],"props":["aro"],"commonMistakes":["Girando todo el brazo.","El brazo se va hacia adelante."]},"hoop-elbow":{"name":"Aro en el codo","description":"El brazo se mantiene a un lado, doblado por el codo, y el aro gira alrededor de la articulación del codo.","goodFor":"Control de extremidades lejos del cuerpo.","alignmentCues":["A la altura de la parte superior del brazo.","Círculos pequeños con el codo."],"props":["aro"],"commonMistakes":["El codo baja.","El aro se desliza hacia el hombro."]},"hoop-foot":{"name":"Hooping en la pierna","description":"Levanta una pierna y haz girar el aro alrededor de la espinilla; el pie dibuja pequeños círculos para mantenerlo girando.","goodFor":"Equilibrio y control de la pierna.","alignmentCues":["Pierna de apoyo firme.","Círculos pequeños con el pie."],"props":["aro"],"commonMistakes":["Pierdes el equilibrio.","Círculos demasiado grandes."]},"hoop-full-escalator":{"name":"Escalator completo","description":"Acompaña el aro todo el trayecto, de las rodillas a los hombros y de regreso hacia abajo, sin parar.","goodFor":"Todo el recorrido del cuerpo en un solo movimiento continuo.","alignmentCues":["Acelera el pulso mientras subes.","Los brazos suben junto con el aro."],"props":["aro"],"commonMistakes":["Lo pierdes en el salto de cintura al pecho.","Los brazos estorban."]},"hoop-vortex":{"name":"Vórtice","description":"Haz un lasso con el aro sobre la cabeza, deja que caiga rodeando hombros y pecho, y atrápalo en la cintura en un solo descenso en espiral.","goodFor":"Conectar el hooping off-body con el on-body.","alignmentCues":["Mantén la velocidad del lasso al soltar.","Empieza a dar pulso antes de que caiga."],"props":["aro"],"commonMistakes":["Lo sueltas demasiado despacio.","El aro se inclina al bajar."]},"hoop-duck-out":{"name":"Duck Out","description":"Sube el aro caminándolo desde la cintura hasta pasar el pecho, agárralo sobre la cabeza en un lasso y bájalo hasta convertirlo en un giro de mano al frente.","goodFor":"Salir del cuerpo con limpieza.","alignmentCues":["Levántalo con las costillas.","Agárralo sobre la cabeza al compás."],"props":["aro"],"commonMistakes":["Lo agarras demasiado pronto.","Pierdes velocidad."]},"hoop-drop-in":{"name":"Descenso","description":"Desde un lasso sobre la cabeza, suelta y atrapa el aro en el pecho, y déjalo caer hasta la cintura.","goodFor":"La forma más sencilla de volver del off-body al cuerpo.","alignmentCues":["Brazos arriba mientras baja.","Atrapa con un pulso."],"props":["aro"],"commonMistakes":["Lo bajas demasiado rápido.","Brazos apretando hacia abajo."]},"hoop-chest-lift":{"name":"Elevación al pecho","description":"Sube el aro de la cintura al pecho y de vuelta con un pulso más fuerte.","goodFor":"Movimiento entre zonas del cuerpo.","alignmentCues":["Pulso más rápido para subir.","Brazos arriba demasiado pronto."],"props":["aro"],"commonMistakes":["Pierdes el aro en el cambio.","Brazos bajando."]},"hoop-knee-drop":{"name":"Caída a las rodillas","description":"Deja que el aro baje de la cintura a las rodillas, mantenlo ahí y hazlo rebotar de vuelta a la cintura.","goodFor":"Transiciones con la parte baja del cuerpo.","alignmentCues":["Pies juntos para las rodillas.","Rebote más grande para subir."],"props":["aro"],"commonMistakes":["Pies separados.","Pierdes el aro al subir."]},"hoop-side-spin":{"name":"Giro lateral","description":"Un giro de mano al lado del cuerpo en el plano de rueda, con el aro girando como una rueda a tu lado.","goodFor":"El plano de rueda del aro.","alignmentCues":["Aro plano a tu lado.","Mano a la altura de la cadera."],"props":["aro"],"commonMistakes":["El aro golpea la pierna.","El plano se inclina."]},"hoop-reverse-hand-spin":{"name":"Giro de mano inverso","description":"El giro de mano en sentido contrario, frente a ti.","goodFor":"Ambas direcciones fuera del cuerpo.","alignmentCues":["Mismo plano, otra dirección.","El pulgar se mantiene arriba."],"props":["aro"],"commonMistakes":["Se bambolea.","Se frena."]},"hoop-reverse-lasso":{"name":"Lazo inverso","description":"El lazo sobre la cabeza girando al revés.","goodFor":"Ambas direcciones del lazo.","alignmentCues":["Aro a nivel.","Círculo pequeño de mano."],"props":["aro"],"commonMistakes":["Inclinando.","Círculos grandes de brazo."]},"hoop-palm-spin":{"name":"Palm Spin sobre la cabeza","description":"Un giro de mano elevado sobre la palma abierta, con el aro girando de frente sobre ti.","goodFor":"Alcanzando giros fuera del cuerpo en lo alto.","alignmentCues":["Brazo estirado.","Palma abierta."],"props":["aro"],"commonMistakes":["El aro se va hacia atrás.","El brazo se dobla."]},"hoop-coin-flip":{"name":"Vuelta de monedas","description":"Equilibra el aro en vertical sobre las puntas de los dedos y dale un toque para que gire sobre su eje vertical, como una moneda al aire.","goodFor":"Control fino de los dedos y un eje nuevo.","alignmentCues":["Aro en vertical.","Dale un toque y deja que gire."],"props":["aro"],"commonMistakes":["El aro se inclina.","Agarrando."]},"hoop-cateye":{"name":"Ojo de Gato","description":"Sujeta el aro por el costado del borde y balancéalo sobre su eje vertical, de modo que de frente se estreche y se ensanche como un ojo de gato.","goodFor":"Movimientos de balanceo y una ilusión llamativa.","alignmentCues":["Mano quieta en el borde.","Balancea de forma uniforme."],"props":["aro"],"commonMistakes":["La mano se mueve.","Balanceo desigual."]},"hoop-weave":{"name":"Entrelazar","description":"Un giro de mano que se desliza de un lado del cuerpo al otro, con el plano girando junto con el pecho.","goodFor":"Llevando el giro a través del cuerpo.","alignmentCues":["El pecho gira junto con él.","Mantén el giro."],"props":["aro"],"commonMistakes":["Parada a mitad de camino.","Inclinando."]},"hoop-halo":{"name":"Halo","description":"El aro orbita en horizontal alrededor de la cabeza, con la mano elevada recorriendo el borde por encima de ti.","goodFor":"Órbitas a la altura de la cabeza.","alignmentCues":["Hoop a la altura de la cabeza.","Mano cerca de la cabeza."],"props":["aro"],"commonMistakes":["El hoop baja por delante.","Agacharse."]},"hoop-toss":{"name":"Lanzamiento de hoop","description":"Lanza el hoop en hand spin recto hacia arriba, sin dejar de girar, y atrápalo de vuelta en el giro.","goodFor":"Soltar y atrapar el hoop girando.","alignmentCues":["Lánzalo recto hacia arriba.","Atrápalo donde lo lanzaste."],"props":["aro"],"commonMistakes":["Lanzar hacia adelante.","Agarrar el borde tarde."]},"hoop-boomerang":{"name":"Bumerán","description":"Lanza el hoop hacia abajo y hacia fuera con backspin, para que ruede por el suelo y vuelva a ti.","goodFor":"Backspin y un truco de suelo divertido.","alignmentCues":["Da un golpe de muñeca hacia atrás.","Lánzalo bajo y hacia adelante."],"props":["aro"],"commonMistakes":["Falta backspin.","Lanzar demasiado alto."]},"hoop-jump-through":{"name":"Saltar","description":"Sujeta el hoop con las dos manos como una cuerda de saltar: balancéalo por encima de la cabeza y salta a través cuando pase bajo tus pies.","goodFor":"Ritmo, coordinación y una dosis de cardio.","alignmentCues":["Salto pequeño, rodillas relajadas.","Balancea desde las muñecas."],"props":["aro"],"commonMistakes":["Saltar demasiado pronto.","Demasiado balanceo de brazos."]},"hoop-behind-back-pass":{"name":"Pase por la espalda","description":"Un hand spin que pasa por detrás de la espalda de una mano a la otra y luego vuelve por delante.","goodFor":"Pasar el hoop alrededor de todo el cuerpo.","alignmentCues":["Mantén el giro por detrás.","La mano que espera se extiende hacia atrás."],"props":["aro"],"commonMistakes":["El hoop se detiene por detrás.","El hoop golpea la espalda."]},"hoop-under-leg-pass":{"name":"Pase bajo la pierna","description":"Un pase de mano a mano que pasa por debajo de la pierna derecha levantada.","goodFor":"Añadir las piernas a los pases.","alignmentCues":["Levanta la rodilla alto hacia el aro.","Dobla en las caderas con la espalda larga y siéntate sobre la rodilla de pie.","Vuelve a subir cuando el aro salga por el otro lado."],"props":["aro"],"commonMistakes":["Arquear la espalda para alcanzar hacia abajo en lugar de doblar en las caderas.","Dejar la rodilla baja, haciendo que el aro toque el muslo.","Rushing."]},"hoop-corkscrew":{"name":"Sacacorchos","description":"Un lasso que baja en espiral hasta las caderas y vuelve a subir, mientras el aro dibuja un corkscrew.","goodFor":"Llevando el lasso por distintos niveles.","alignmentCues":["Flexiona las rodillas para bajar.","Mantén el aro horizontal."],"props":["aro"],"commonMistakes":["El aro se inclina al bajar.","El giro pierde velocidad."]},"hoop-barrel-roll":{"name":"tonel en espiral","description":"Un giro de mano que da una vuelta completa al cuerpo cada cuatro tiempos, mientras el aro rueda a tu alrededor.","goodFor":"Flujo off-body en círculos completos.","alignmentCues":["Gira con el aro.","Sigue girando sin parar."],"props":["aro"],"commonMistakes":["El aro se engancha en el cuerpo.","El giro se frena a la espalda."]},"hoop-chest-roll":{"name":"Rodada de pecho","description":"Suelta un giro de mano sobre el pecho y deja que ruede hasta la otra mano.","goodFor":"La primera rodada del aro.","alignmentCues":["Pecho en alto.","Brazos abiertos mientras rueda."],"props":["aro"],"commonMistakes":["Pecho hundido.","Agarrando antes de tiempo."]},"hoop-back-roll":{"name":"Rodada de espalda","description":"El aro rueda por la parte trasera de los hombros de una mano a la otra.","goodFor":"Rueda por detrás del cuerpo.","alignmentCues":["Omóplatos juntos.","Cabeza un poco hacia adelante."],"props":["aro"],"commonMistakes":["Encorvando la espalda.","El aro se cae."]},"hoop-isopop":{"name":"Iso Pop","description":"Un aislamiento que hace un stall y lanza el aro a un lado cada dos tiempos antes de continuar.","goodFor":"Acentos y stalls en los aislamientos.","alignmentCues":["Pop en el tiempo.","El aislamiento se mantiene limpio entre pops."],"props":["aro"],"commonMistakes":["Pops demasiado grandes.","El centro se mueve."]},"hoop-wheel-isolation":{"name":"Aislamiento lateral","description":"Un aislamiento al lado del cuerpo en el plano de rueda.","goodFor":"Aislamientos en un segundo plano.","alignmentCues":["Centro fijo a tu lado.","La mano hace círculos a su alrededor."],"props":["aro"],"commonMistakes":["El centro se desvía.","Se inclina."]},"hoop-floor-isolation":{"name":"Aislamiento plano","description":"Un aislamiento con el aro en horizontal y el centro fijo, mientras la mano hace círculos.","goodFor":"Aislamientos en el plano del suelo.","alignmentCues":["Aro a nivel.","Centro fijo."],"props":["aro"],"commonMistakes":["Se inclina.","El centro se desvía."]},"doubles-hand-spins":{"name":"Giros de mano con dobles","description":"Un aro en cada mano, ambos girando delante de ti en espejo.","goodFor":"El primer movimiento de dobles.","alignmentCues":["Aros lado a lado.","Iguala la velocidad."],"props":["dos aros"],"commonMistakes":["Los aros chocan.","Uno va más lento."]},"doubles-offset-spins":{"name":"Giros desfasados con dobles","description":"Giros de mano con dobles girando en el mismo sentido, con medio giro de desfase.","goodFor":"Cada mano lleva su propio tiempo.","alignmentCues":["Uno sube mientras el otro baja.","Mismo sentido."],"props":["dos aros"],"commonMistakes":["Sincronizándose.","Chocan."]},"doubles-side-spins":{"name":"Giros laterales con dobles","description":"Un aro girando junto a cada cadera en el plano de rueda.","goodFor":"Dobles en el plano de rueda.","alignmentCues":["Aros verticales.","Sin tocar las piernas."],"props":["dos aros"],"commonMistakes":["Golpean las piernas.","Inclinándose."]},"doubles-floor-spins":{"name":"Lazos dobles","description":"Un lazo sobre la cabeza en cada mano, en espejo.","goodFor":"Dobles sobre la cabeza.","alignmentCues":["Ambos al mismo nivel.","Círculos pequeños con las manos."],"props":["dos aros"],"commonMistakes":["Los aros se tocan.","Se cansan los brazos."]},"doubles-wedgies":{"name":"Wedgies dobles","description":"Un wedgie en cada mano, los dos aros oscilando en los huecos de los pulgares.","goodFor":"Movimientos de balanceo con dobles.","alignmentCues":["Pulgares hacia afuera.","Balanceo parejo."],"props":["dos aros"],"commonMistakes":["Los aros chocan.","Ritmo desigual."]},"doubles-coin-flips":{"name":"Coin Flips dobles","description":"Un coin flip en cada mano a la vez.","goodFor":"Control de dedos con dobles.","alignmentCues":["Ambos verticales.","Impulso simultáneo."],"props":["dos aros"],"commonMistakes":["Volcándose.","Chocan."]},"doubles-isolations":{"name":"Aislaciones dobles","description":"Una aislación en cada mano, los dos centros fijos y lado a lado.","goodFor":"Dos aislaciones a la vez.","alignmentCues":["Dos centros quietos.","Las manos giran juntas."],"props":["dos aros"],"commonMistakes":["Los centros se desvían.","Los aros chocan."]},"doubles-toss":{"name":"Lanzamiento doble","description":"Lanza los dos aros girando al aire a la vez y atrápalos de nuevo en giros dobles.","goodFor":"Lanzamientos con dobles.","alignmentCues":["Lanza ambos rectos hacia arriba a la vez.","Atrapa donde lanzaste."],"props":["dos aros"],"commonMistakes":["Lanzamientos desiguales.","Se desplazan hacia adelante."]},"doubles-waist-and-hand":{"name":"Aro en la cintura y giro en la mano","description":"Mantén un aro girando en la cintura mientras haces girar otro en la mano izquierda.","goodFor":"Atención dividida entre el cuerpo y la mano.","alignmentCues":["Las caderas mantienen su pulso.","Giro en la mano delante del aro del cuerpo."],"props":["dos aros"],"commonMistakes":["El aro del cuerpo se frena.","El aro de la mano golpea el aro del cuerpo."]},"doubles-chest-and-hand":{"name":"Aro en el pecho y giro en la mano","description":"Aro en el pecho con un brazo levantado mientras la otra mano hace girar un segundo aro.","goodFor":"Aro en el cuerpo en alto con un truco de mano.","alignmentCues":["Un brazo en alto.","Las costillas impulsan el aro del cuerpo."],"props":["dos aros"],"commonMistakes":["El brazo baja hacia el aro del pecho.","Se pierde el pulso."]},"doubles-waist-and-lasso":{"name":"Aro en la cintura y lazo","description":"Aro en la cintura abajo, lazo por encima de la cabeza: dos aros en dos niveles a la vez.","goodFor":"Dos niveles de aro a la vez.","alignmentCues":["Las caderas marcan el pulso, la mano hace círculos.","El lazo por encima de la cabeza."],"props":["dos aros"],"commonMistakes":["El aro del cuerpo se cae.","El lazo se inclina."]},"poi-one-hand-spin":{"name":"Spin frontal con un poi","description":"Un poi girando frente a ti como la manecilla de un reloj, con la cabeza rozándote el costado. La muñeca traza un círculo pequeño y constante, y la cuerda se mantiene tensa.","goodFor":"Siente el tirón de la cuerda y el ritmo de un giro por beat.","alignmentCues":["Círculos pequeños de muñeca, círculos grandes de poi.","Mantén el círculo plano frente a ti, como el cristal de una ventana."],"props":["un poi"],"commonMistakes":["Girando desde el hombro.","Dejando que el círculo se incline hacia ti."]},"poi-wall-spin":{"name":"Wall Spin hacia adelante","description":"Ambos poi girando hacia adelante juntos frente a ti, uno junto a cada hombro, lado a lado como dos ruedas en un eje. El primer movimiento con dos poi.","goodFor":"Dos poi sincronizados entre sí y con el beat.","alignmentCues":["Ambas cabezas llegan arriba a la vez.","Manos separadas más o menos al ancho de los hombros."],"props":["par de poi"],"commonMistakes":["Un poi va retrasado respecto al otro.","Los círculos se van juntando y se superponen."]},"poi-reverse-wall-spin":{"name":"Wall Spin hacia atrás","description":"El wall spin al revés: las cabezas suben por fuera y bajan por el medio.","goodFor":"Ambas direcciones antes de los weaves y las flowers.","alignmentCues":["Mismos planos, solo cambia la dirección.","Guía los círculos con el dorso de la muñeca."],"props":["par de poi"],"commonMistakes":["Volviendo sin querer al spin hacia adelante.","Planos inclinados hacia adelante."]},"poi-split-time":{"name":"Wall Spin en split time","description":"Ambos poi girando en el mismo sentido, pero desfasados medio giro: cuando uno está arriba, el otro está abajo. El timing sobre el que se construye cada weave.","goodFor":"Timing independiente en las dos manos.","alignmentCues":["Arriba, abajo, arriba, abajo: las cabezas se alternan.","Cuenta el punto más alto de cada poi en el tiempo y en el contratiempo."],"props":["par de poi"],"commonMistakes":["Volviendo poco a poco al mismo tiempo.","Las manos se mueven a distintas velocidades."]},"poi-butterfly":{"name":"Mariposa","description":"Manos juntas al frente y los poi girando en direcciones opuestas, de modo que se encuentran arriba y abajo como las alas de una mariposa.","goodFor":"Giros en direcciones opuestas y manos juntas.","alignmentCues":["Las cabezas se besan arriba y abajo.","Las muñecas casi se tocan."],"props":["par de poi"],"commonMistakes":["Las cabezas chocan al cruzarse los planos.","Las manos se van separando."]},"poi-reverse-butterfly":{"name":"Mariposa inversa","description":"La mariposa con ambas alas girando al revés: las cabezas suben juntas por el centro y bajan por los lados exteriores.","goodFor":"Equilibrando la mariposa en ambas direcciones.","alignmentCues":["Encuéntrate en el centro, arriba.","Manos igual de juntas que en la mariposa hacia adelante."],"props":["par de poi"],"commonMistakes":["Las cabezas se enredan arriba.","Un ala caída."]},"poi-chase-the-sun":{"name":"Persigue al Sol","description":"Manos juntas al frente y en tiempo dividido: las dos cabezas se persiguen por un gran círculo, siempre a media vuelta de distancia.","goodFor":"Tiempo dividido con las manos juntas, listo para los weaves.","alignmentCues":["Una cabeza siempre opuesta a la otra.","Las manos se mueven como una sola."],"props":["par de poi"],"commonMistakes":["Una cabeza alcanza a la otra.","Las manos se separan."]},"poi-wheels":{"name":"Ruedas hacia adelante","description":"Ambos poi giran a tu lado como las ruedas de una bicicleta, con la parte superior rodando hacia adelante.","goodFor":"El plano de rueda, al lado del cuerpo.","alignmentCues":["Los círculos corren paralelos a tus costados.","Codos relajados y cerca del cuerpo."],"props":["par de poi"],"commonMistakes":["Los poi rozan las piernas.","Las ruedas se abren hacia afuera."]},"poi-reverse-wheels":{"name":"Ruedas hacia atrás","description":"Ruedas que giran hacia atrás a tu lado: las cabezas suben por delante y caen por detrás.","goodFor":"Ambas direcciones en el plano de rueda.","alignmentCues":["Las mismas ruedas, al revés.","Hombros abajo y relajados."],"props":["par de poi"],"commonMistakes":["Las ruedas se quedan detrás del cuerpo.","Las muñecas se tensan."]},"poi-fountain":{"name":"Fuente","description":"Ruedas en tiempo dividido: un poi sube mientras el otro baja, como el agua de una fuente a tu lado.","goodFor":"Tiempo dividido en el plano de rueda, la base del weave caminante.","alignmentCues":["Uno arriba, otro abajo.","Mantén el mismo ritmo en ambas manos."],"props":["par de poi"],"commonMistakes":["El ritmo se pierde y ambas manos van al mismo tiempo.","Las ruedas se inclinan hacia dentro."]},"poi-opposite-wheels":{"name":"Ruedas opuestas","description":"Una rueda gira hacia delante mientras la otra gira hacia atrás. Las cabezas se cruzan arriba y abajo.","goodFor":"Coordinación con las manos girando en sentidos opuestos.","alignmentCues":["Ambas llegan arriba a la vez.","Cada mano mantiene su propio sentido."],"props":["par de poi"],"commonMistakes":["Ambas manos pasan a girar en el mismo sentido.","Una de las ruedas se encoge."]},"poi-overhead":{"name":"Giro de suelo sobre la cabeza","description":"Ambos poi giran planos sobre tu cabeza como las aspas de un helicóptero, quedando un poco más bajos hacia fuera mientras rotan.","goodFor":"El plano de suelo y unos hombros estables sobre la cabeza.","alignmentCues":["Manos justo por encima de la cabeza.","Deja que los poi encuentren el plano; no los fuerces."],"props":["par de poi"],"commonMistakes":["Los hombros se encogen.","Los poi se hunden por delante."]},"poi-low-floor":{"name":"Giro de suelo a la altura de la cadera","description":"El plano de suelo bajado hasta las caderas: los poi barren a la altura de la cintura, a tu lado.","goodFor":"El plano de suelo bajo que se usa en los híbridos de suelo a pared.","alignmentCues":["Manos extendidas a los lados de las caderas.","Mantén los círculos nivelados."],"props":["par de poi"],"commonMistakes":["Los poi golpean los muslos.","El cuerpo se inclina hacia delante."]},"poi-three-beat-weave":{"name":"Weave de tres tiempos","description":"El movimiento insignia del poi: en tiempo dividido, los poi pasan de un lado del cuerpo al otro mientras los brazos se cruzan y descruzan al cambiar los planos de lado.","goodFor":"El movimiento de flow del que parte todo el que gira poi.","alignmentCues":["Gira los hombros con el weave.","Los planos se inclinan ligeramente hacia cada lado."],"props":["par de poi"],"commonMistakes":["Las manos se mantienen en el centro.","Los poi chocan en el cruce."]},"poi-reverse-three-beat-weave":{"name":"Tejido de tres tiempos invertido","description":"El tejido de tres tiempos con ambos poi girando en sentido inverso. Los brazos se cruzan por arriba en vez de por debajo.","goodFor":"Tejido en ambas direcciones.","alignmentCues":["Mismo patrón de lado a lado, con giro invertido.","Mantén las manos a la altura del pecho."],"props":["par de poi"],"commonMistakes":["Las cabezas chocan arriba.","El tejido se encoge hacia un lado."]},"poi-two-beat-weave":{"name":"Tejido de dos tiempos","description":"Un tejido más rápido que cambia de lado en cada tiempo. Los cruces más rápidos lo hacen más movido y compacto.","goodFor":"Cambios de lado rápidos.","alignmentCues":["Giros de hombro más pequeños y rápidos.","Cruza las muñecas cerca del pecho."],"props":["par de poi"],"commonMistakes":["Caer de nuevo en el ritmo de tres tiempos.","Perder la separación."]},"poi-five-beat-weave":{"name":"Tejido de cinco tiempos","description":"Un tejido más largo y amplio: los poi dan más vueltas a cada lado antes de volver a cruzarse.","goodFor":"Mantener la forma del tejido durante frases más largas.","alignmentCues":["Giros de hombro amplios.","Mantén los cruces suaves."],"props":["par de poi"],"commonMistakes":["Cruzar demasiado pronto.","Los planos se aplanan."]},"poi-behind-back-weave":{"name":"Tejido por detrás de la espalda","description":"Cada segundo par de tiempos, el poi derecho pasa por detrás de tu espalda y regresa al frente sin romper el ritmo.","goodFor":"Pases alrededor del cuerpo que cambian el aspecto de un patrón sencillo.","alignmentCues":["Lleva la mano baja por detrás de las caderas.","Mira al frente y confía en el ritmo."],"props":["par de poi"],"commonMistakes":["Los poi golpean la espalda.","El poi de adelante se detiene mientras el de atrás sigue su recorrido."]},"poi-crossers":{"name":"Crossers","description":"Giros en plano de pared simultáneos mientras los brazos se cruzan delante de ti y se vuelven a abrir, con los poi cambiando de lado en cada tiempo.","goodFor":"Cruces de brazos con los poi a tiempo.","alignmentCues":["Cruza a la altura de las muñecas.","Mantén ambos poi sincronizados."],"props":["par de poi"],"commonMistakes":["Las cuerdas se enredan al cruzar los brazos.","Un poi se frena."]},"poi-reels":{"name":"Carretes","description":"Ambos poi giran juntos a un lado del cuerpo durante un compás y luego se balancean hacia el otro lado.","goodFor":"Mover ambos poi como una unidad alrededor del cuerpo.","alignmentCues":["Las manos se mantienen juntas.","Gira el cuerpo para quedar de frente a cada lado."],"props":["par de poi"],"commonMistakes":["Las manos se separan al cruzarse.","El cruce se sale del ritmo."]},"poi-thread-the-needle":{"name":"Enhebrar la aguja","description":"Poi en direcciones opuestas y a tiempo partido, con los brazos cruzados: un poi se cuela por el hueco que el otro acaba de dejar.","goodFor":"Sincronización precisa entre las dos manos.","alignmentCues":["Cruza cuando se abra el hueco.","Mantén los círculos compactos."],"props":["par de poi"],"commonMistakes":["Los poi chocan en pleno cruce.","La sincronización se desliza hacia el mismo tiempo."]},"poi-buzzsaw":{"name":"Sierra circular","description":"Las manos presionadas una contra otra y ambos poi girando como uno solo, con las cuerdas lado a lado como una sola hoja giratoria.","goodFor":"Ambos poi girando exactamente igual.","alignmentCues":["Palmas juntas, muñecas relajadas.","Un círculo, dos cabezas."],"props":["par de poi"],"commonMistakes":["Las cabezas se separan.","Las manos se van separando."]},"poi-one-hand-isolation":{"name":"Aislamiento con un poi","description":"La mano gira en círculo opuesto a la cabeza, a la misma velocidad, de modo que el punto medio de la cuerda parece fijo en el aire mientras el poi gira a su alrededor.","goodFor":"La primera ilusión: un punto fijo en el espacio.","alignmentCues":["La mano siempre opuesta a la cabeza.","Mira el punto medio de la cuerda, no la cabeza."],"props":["un poi"],"commonMistakes":["El círculo de la mano es demasiado pequeño y el punto se desplaza.","Se acelera en la parte de arriba."]},"poi-isolation":{"name":"Aislamientos","description":"Aislamientos con las dos manos a la vez, con los dos puntos fijos lado a lado frente a ti.","goodFor":"Control de la ilusión con las dos manos.","alignmentCues":["Cada mano opuesta a su cabeza.","Codos relajados, hombros abajo."],"props":["par de poi"],"commonMistakes":["Una mano pierde la aislación.","Los puntos se van hacia adelante."]},"poi-split-isolation":{"name":"Aislaciones en tiempo dividido","description":"Aislaciones separadas media vuelta: una mano arriba mientras la otra está abajo, con los puntos quietos bien firmes.","goodFor":"El ritmo de la aislación en tiempo dividido.","alignmentCues":["Las manos se alternan arriba y abajo.","Los puntos se mantienen a la misma altura."],"props":["par de poi"],"commonMistakes":["Las manos se van sincronizando.","Los puntos pierden altura."]},"poi-wheel-isolation":{"name":"Aislaciones en plano de rueda","description":"Aislaciones junto a ti en el plano de rueda, con los puntos quietos flotando a los costados.","goodFor":"Aislaciones en un segundo plano.","alignmentCues":["Puntos a la altura de las caderas.","Las manos giran en paralelo a tus lados."],"props":["par de poi"],"commonMistakes":["Los planos se giran hacia afuera.","Las manos demasiado cerca del cuerpo."]},"poi-extension":{"name":"Extensiones","description":"Brazo y cuerda en una sola línea recta, con la mano describiendo círculos amplios para que el poi trace el círculo más grande posible.","goodFor":"Figuras grandes y abiertas, y la mitad de extensión del ojo de gato.","alignmentCues":["Extiende desde el hombro.","La mano y la cabeza del poi en una misma línea desde el centro."],"props":["par de poi"],"commonMistakes":["Doblando la muñeca.","Los círculos se colapsan en la parte baja."]},"poi-cateye":{"name":"Ojo de gato","description":"Una mano aísla mientras la otra extiende. Las dos trayectorias se superponen en forma de almendra, como el ojo de un gato.","goodFor":"Mezclando dos trayectorias de mano distintas a la vez.","alignmentCues":["La mano que aísla, ceñida; la mano que extiende, amplia.","Ambas empiezan arriba al mismo tiempo."],"props":["par de poi"],"commonMistakes":["Las dos manos hacen lo mismo.","La figura queda ladeada."]},"poi-one-hand-antispin":{"name":"Antispin con un poi","description":"La mano gira en un sentido mientras el poi gira en el otro, con tres giros por cada círculo de la mano, dibujando una flor de cuatro pétalos.","goodFor":"La sensación del antispin antes de las flores con dos poi.","alignmentCues":["Círculo de la mano amplio y lento.","Cada punta de pétalo en el borde del círculo de la mano."],"props":["un poi"],"commonMistakes":["El poi volviendo al spin simple.","Pétalos desiguales."]},"poi-antispin-flower":{"name":"Antispin de Cuatro Pétalos","description":"Flores en antispin con ambas manos a la vez, dos flores de cuatro pétalos floreciendo una junto a la otra.","goodFor":"La flor de poi clásica.","alignmentCues":["Las manos hacen círculos juntas.","Los pétalos se alinean: arriba, lado, abajo, lado."],"props":["par de poi"],"commonMistakes":["Una mano cayendo en spin.","Las flores desplazándose hacia adelante."]},"poi-split-antispin":{"name":"Antispin en Split Time","description":"Flores de cuatro pétalos con los poi desfasados medio giro, los pétalos de una flor llenando los huecos de la otra.","goodFor":"El ritmo de las flores en split time.","alignmentCues":["Las manos opuestas entre sí en sus círculos.","Los pétalos se intercalan."],"props":["par de poi"],"commonMistakes":["Cayendo en mismo tiempo.","Las manos haciendo círculos a distintas velocidades."]},"poi-three-petal-antispin":{"name":"Antispin de Tres Pétalos","description":"Una flor de tres pétalos: dos antispins por cada círculo de la mano, dando una floración triangular.","goodFor":"Cambiar el número de pétalos variando la velocidad de la mano.","alignmentCues":["Mano más rápida que en el de cuatro pétalos.","Pétalos en tres puntos equidistantes."],"props":["par de poi"],"commonMistakes":["Volviendo sin querer a cuatro pétalos.","El círculo de la mano encogiéndose."]},"poi-five-petal-antispin":{"name":"Antispin de Cinco Pétalos","description":"Cuatro antispins por cada círculo de la mano, una flor de cinco pétalos con una mano más lenta y amplia.","goodFor":"Control fino de la proporción mano-poi.","alignmentCues":["Mano muy lenta.","Cuenta cuatro vueltas del poi por cada círculo de la mano."],"props":["par de poi"],"commonMistakes":["Perdiendo la cuenta de los pétalos.","La mano deteniéndose."]},"poi-wheel-antispin":{"name":"Antispin en Plano de Rueda","description":"Flores de antispin de cuatro pétalos a tu lado en el plano de rueda.","goodFor":"Flores en el plano de rueda.","alignmentCues":["Flores paralelas a tus lados.","Las manos dibujan círculos junto a las caderas."],"props":["par de poi"],"commonMistakes":["Los planos se inclinan hacia adentro.","Los pétalos rozan las piernas."]},"poi-overhead-antispin":{"name":"Antispin sobre la cabeza","description":"Flores de antispin planas sobre la cabeza, con los pétalos abriéndose sobre ti.","goodFor":"Flores en el plano del suelo.","alignmentCues":["Las manos justo por encima de la cabeza.","Los pétalos se mantienen nivelados."],"props":["par de poi"],"commonMistakes":["Las flores se inclinan hacia adelante.","Los hombros se cansan y caen."]},"poi-antispin-and-spin":{"name":"Antispin y giro","description":"La mano derecha dibuja una flor de antispin de cuatro pétalos mientras la izquierda mantiene un giro sencillo hacia adelante.","goodFor":"Independencia de manos: dos figuras distintas a la vez.","alignmentCues":["La mano que gira mantiene el círculo compacto.","La mano de la flor dibuja círculos amplios."],"props":["par de poi"],"commonMistakes":["Las dos manos se copian.","El giro del poi se frena."]},"poi-inspin-flower":{"name":"Inspin de cuatro pétalos","description":"La mano gira despacio en el mismo sentido que el poi, con cinco vueltas por cada círculo de la mano, dibujando bucles que apuntan hacia adentro.","goodFor":"Flores de inspin, la contraparte del antispin.","alignmentCues":["La mano y el poi giran en el mismo sentido.","Los bucles de los pétalos miran hacia el centro."],"props":["par de poi"],"commonMistakes":["Círculo de la mano demasiado rápido.","Los bucles salen desiguales."]},"poi-three-petal-inspin":{"name":"Inspin de tres pétalos","description":"Inspin con cuatro giros por cada círculo de la mano, dibujando una flor de tres bucles.","goodFor":"Cambiar el número de pétalos del inspin.","alignmentCues":["Mano un poco más rápida que en el de cuatro pétalos.","Tres bucles, igualmente espaciados."],"props":["par de poi"],"commonMistakes":["Contando mal.","Los bucles se achatan."]},"poi-wall-wheel-hybrid":{"name":"Híbrido pared–rueda","description":"En cada vuelta, los poi cambian de plano, primero delante y luego al lado, girando cuando la cabeza pasa recta hacia abajo.","goodFor":"Cambiar de plano sin cortar el giro.","alignmentCues":["Cambia cuando el poi apunte al suelo.","Gira la muñeca, no todo el brazo."],"props":["par de poi"],"commonMistakes":["Cambiar de plano a mitad del círculo.","Los poi se tambalean entre planos."]},"poi-wheel-floor-hybrid":{"name":"Híbrido Rueda–Suelo","description":"Los poi alternan entre girar a tu lado y barrer en horizontal, cambiando cuando apuntan hacia adelante.","goodFor":"Un segundo híbrido con un plano horizontal.","alignmentCues":["Cambia cuando el poi apunte hacia adelante.","Mantén las manos a la altura de la cadera."],"props":["par de poi"],"commonMistakes":["Los poi se hunden durante el cambio.","Perder el ritmo."]},"poi-floor-wall-hybrid":{"name":"Híbrido Suelo–Pared","description":"Del plano horizontal sobre la cabeza al vertical frente a ti, y de vuelta, cambiando cuando los poi apunten a los lados.","goodFor":"Conectar el plano sobre la cabeza y el de pared.","alignmentCues":["Cambia cuando los poi apunten a los lados.","Sube y baja las manos con suavidad."],"props":["par de poi"],"commonMistakes":["Los poi golpean la cabeza.","Cambios desiguales."]},"poi-top-stall":{"name":"Parada","description":"El poi sube hasta el punto más alto, se detiene un instante justo encima de la mano y cae de vuelta por donde vino.","goodFor":"Frenar e invertir el sentido: la base de los combos de stalls y de los hyperloops.","alignmentCues":["Levanta la mano cuando el poi llegue al punto más alto.","Déjalo colgar y luego guíalo de vuelta."],"props":["un poi"],"commonMistakes":["La cuerda se afloja y se enrolla.","Apresurar la pausa."]},"poi-stalls":{"name":"Stalls Dobles","description":"Ambos poi hacen el stall juntos en el punto más alto e invierten el sentido, lado a lado.","goodFor":"Control del stall con las dos manos.","alignmentCues":["Ambos llegan al punto más alto a la vez.","Las manos suben juntas."],"props":["par de poi"],"commonMistakes":["Un poi llega tarde al stall.","Los poi chocan al bajar."]},"poi-side-stall":{"name":"Stalls Laterales","description":"Los poi hacen el stall a los lados en vez de arriba, y cada uno se detiene a la altura del hombro antes de regresar.","goodFor":"Stalls en otro punto del círculo.","alignmentCues":["Haz una pausa cuando el poi apunte a un lado.","Brazos relajados."],"props":["par de poi"],"commonMistakes":["El poi cae en vez de quedarse suspendido.","El ritmo se va descentrando."]},"poi-chasing-stalls":{"name":"Persiguiendo puestos","description":"Stalls separados medio beat: un poi se queda suspendido arriba mientras el otro todavía sube.","goodFor":"Stalls en split time.","alignmentCues":["Un stall, luego el otro.","Mantén las manos a la altura del pecho."],"props":["par de poi"],"commonMistakes":["Ambos stalls a la vez.","Se apura el segundo stall."]},"poi-hyperloop":{"name":"Hyperloop","description":"Un stall donde el plano se voltea en el punto más alto, de modo que el poi da la vuelta y baja por la otra cara del círculo.","goodFor":"Loops tridimensionales desde el stall.","alignmentCues":["Gira la muñeca en lo alto del stall.","Mantén la cuerda tensa."],"props":["un poi"],"commonMistakes":["El plano se voltea antes de que el poi llegue arriba.","La cuerda se afloja."]},"poi-arm-wrap":{"name":"Wrap de brazo","description":"El poi se enrolla en el otro antebrazo, extendido al frente, y gira más rápido con la cuerda acortada; luego se desenrolla hasta volver al círculo completo.","goodFor":"El primer wrap, y cómo los wraps aceleran el poi.","alignmentCues":["Mantén el brazo de apoyo quieto y a la misma altura.","Mantén la mano que gira por detrás del brazo de apoyo."],"props":["un poi"],"commonMistakes":["El brazo de apoyo se mueve.","Se desenrolla en el sentido contrario."]},"poi-leg-wrap":{"name":"Wrap de pierna","description":"Sube la rodilla y deja que el poi se enrolle en el muslo; luego baja la pierna mientras se desenrolla.","goodFor":"Wraps en el cuerpo.","alignmentCues":["Rodilla en alto cuando llega el poi.","Mantén la postura erguida sobre la pierna de apoyo."],"props":["un poi"],"commonMistakes":["La rodilla sube tarde.","Se pierde el equilibrio."]},"poi-neck-wrap":{"name":"Wrap de cuello","description":"Desde un giro sobre la cabeza, baja la mano para que el poi se enrolle en la nuca y se desenrolle de vuelta sobre la cabeza.","goodFor":"Un wrap vistoso que enlaza giros sobre la cabeza.","avoidIf":["Usa poi de práctica con cabezas blandas; nunca aprendas los wraps de cuello con fuego."],"alignmentCues":["Barbilla alineada, cuello estirado.","Guía la cuerda hasta la base del cuello."],"props":["un poi"],"commonMistakes":["El wrap ocurre a la altura de la cabeza.","Cuerda demasiado floja."]},"poi-cord-wrap":{"name":"Wrap de cuerda","description":"Desde la mariposa, las dos cuerdas se enrollan entre sí por abajo, con las cabezas girando en cordones cortos antes de desenrollarse.","goodFor":"Wraps entre los dos poi.","alignmentCues":["Junta las cuerdas en la parte baja de la mariposa.","Mantén las manos quietas mientras se enrollan."],"props":["par de poi"],"commonMistakes":["Las manos se separan.","El wrap se enreda."]},"poi-toss":{"name":"Lanzamiento de poi","description":"Suelta la empuñadura cuando el poi sube. Vuela girando por el aire y atrapa la empuñadura cuando vuelve a pasar.","goodFor":"Soltar y atrapar.","avoidIf":["Practica los lanzamientos con poi blandos y con espacio a tu alrededor."],"alignmentCues":["Suelta en la subida.","Mira la empuñadura, no la cabeza."],"props":["un poi"],"commonMistakes":["Soltar demasiado tarde.","Agarrar la cuerda en lugar de la empuñadura."]},"poi-high-toss":{"name":"Lanzamiento alto","description":"Un lanzamiento más alto, con una vuelta extra en el aire antes de la atrapada.","goodFor":"Lanzamientos más grandes, con más giro.","alignmentCues":["Un empuje más firme al soltar.","Atrapa cuando la empuñadura vuelve a pasar."],"props":["un poi"],"commonMistakes":["El lanzamiento se desvía hacia adelante.","Atrapar de golpe."]},"poi-double-toss":{"name":"Lanzamiento doble","description":"Lanzas los dos poi en split time, uno tras otro, y los atrapas de vuelta en el giro.","goodFor":"Sincronización del lanzamiento con ambas manos.","alignmentCues":["Suelta uno y luego el otro.","Atrapa en el mismo orden."],"props":["par de poi"],"commonMistakes":["Soltar los dos a la vez.","Mirar un poi y perder el otro."]},"shake-out":{"name":"Sacudida","description":"Suelta los props y sacude manos y antebrazos. Deja caer los hombros.","goodFor":"Un reinicio corto entre rondas intensas."},"breathe":{"name":"Descansa y reinicia","description":"Deja los objetos, quédate relajado y deja caer los brazos. Tómate un momento antes de la siguiente ronda.","goodFor":"Baja el ritmo cardíaco y despeja la frustración después de los drops."}}`),t={"warmup-mobility":{name:`Calentamiento de flow`,description:`Muñecas, hombros, columna y caderas sueltos a un ritmo constante. Úsalo antes de cualquier sesión con props.`,focus:`Calentamiento · movilidad`},"first-throws":{name:`Primeros lanzamientos`,description:`Una pelota en arco de mano a mano a la altura de los ojos, luego el intercambio de dos pelotas del que nace todo patrón.`,focus:`Malabares · fundamentos`},"cascade-builder":{name:`Constructor de cascade`,description:`Intercambios de dos pelotas seguidos hasta que se sume la tercera: rondas cortas de cascade, reinicio, otra vez.`,focus:`Malabares · fundamentos`},"juggling-tempo-ladder":{name:`Escalera de tempo en cascade`,description:`El cascade a tres tempos, unos beats más rápido en cada peldaño. Lanzamientos más bajos en los peldaños rápidos.`,focus:`Malabares · tempo`},"siteswap-sampler":{name:`Muestrario de siteswap`,description:`Cascade hacia 423, 441 y 531, con el reverse cascade y el shower como limpiadores de paladar. Todo patrón empieza y termina en el cascade.`,focus:`Malabares · patrones`},"four-ball-session":{name:`Sesión de cuatro pelotas`,description:`Dos en una mano por cada lado, la fuente de cuatro pelotas, luego la fuente sincrónica.`,focus:`Malabares · números`},"juggling-combo-flow":{name:`Flow de combos de malabares`,description:`Un set largo y fluido: cascade, reverse cascade, Mills mess y los siteswaps enlazados en una sola pieza musical.`,focus:`Malabares · combos`},"cascade-tricks":{name:`Trucos de cascada`,description:`Tenis, media ducha y garras: cada uno entra en una cascada en marcha y vuelve a salir de ella.`,focus:`Malabares · variaciones`},"juggling-body-throws":{name:`Lanzamientos alrededor del cuerpo`,description:`Bajo la pierna, detrás de la espalda, chops y pingüinos: la cascada lanzada alrededor del cuerpo.`,focus:`Malabares · lanzamientos alrededor del cuerpo`},"sync-shapes":{name:`Figuras sincronizadas`,description:`Columnas, el cruce arcoíris, la caja y el yo-yo: tres pelotas lanzadas de dos en dos.`,focus:`Malabares · patrones sincronizados`},"club-foundations":{name:`Fundamentos con mazas`,description:`Giros simples, el intercambio de dos mazas y la cascada de tres mazas, con flats para terminar.`,focus:`Malabares · mazas`},"passing-with-a-partner":{name:`Passing en pareja`,description:`Colócate frente a tu pareja y lanza: primero una bola cruzada, luego dos cada uno, y después el six-count, el four-count y el two-count.`,focus:`Malabares · passing`},"club-passing-session":{name:`Pases con mazas`,description:`El cuatro tiempos con mazas para calentar, el dos y el tres tiempos para el ritmo, y después pases dobles.`,focus:`Malabares · pases con mazas`},"hoop-juggling-session":{name:`Malabares con aros`,description:`Aros grandes lanzados de canto: lanzamientos individuales, el intercambio, la cascada y su inversa.`,focus:`Malabares · aros`},"staff-first-spins":{name:`Primeros giros de staff`,description:`El wheel spin al lado del cuerpo, luego el front spin. Giros lentos y uniformes, uno por beat.`,focus:`Staff · fundamentos`},"staff-foundations":{name:`Fundamentos de staff`,description:`Wheel spin, front spin, figura 8 y el pass-through de mano a mano enlazados al beat.`,focus:`Staff · fundamentos`},"staff-flow-weave":{name:`Flow weave de staff`,description:`Figura 8 hacia butterfly, giros a una mano y el helicopter, unidos para que el staff nunca se detenga.`,focus:`Bastón · flow`},"staff-isolation-lab":{name:`Laboratorio de isolations de staff`,description:`Isolations y la antispin flower a un tempo más lento, con passes por detrás de la espalda entre medio.`,focus:`Staff · técnico`},"staff-advanced-flow":{name:`Flow avanzado de staff`,description:`El vocabulario completo en una sola pieza larga: weaves, wraps, isolations y el neck roll.`,focus:`Bastón · flow`},"staff-both-ways":{name:`Bastón en ambos sentidos`,description:`Cada giro básico hacia adelante y luego al revés, además del helicóptero a dos manos por encima de la cabeza.`,focus:`Bastón · dirección y planos`},"staff-contact-lab":{name:`Laboratorio de bastón de contacto`,description:`Contacto con la mano abierta y con el cuerpo: colas de pez, el volante, rodadas de mano y de antebrazo, y un lanzamiento para terminar.`,focus:`Bastón · contacto`},"double-staff-session":{name:`Sesión de doble bastón`,description:`Un bastón corto en cada mano: mismo tiempo, tiempo dividido, ruedas y ruedas divididas.`,focus:`Bastón · doble bastón`},"hoop-first-spins":{name:`Primeros giros de hoop`,description:`Hooping en cintura con un empuje adelante-atrás, luego girar el hoop alrededor de una mano.`,focus:`Hoop · fundamentos`},"hoop-body-flow":{name:`Flow on-body de hoop`,description:`Mover el hoop subiendo al pecho y bajando a las rodillas y de vuelta a la cintura, sin parar.`,focus:`Hoop · en el cuerpo`},"hoop-off-body":{name:`Hoop off-body`,description:`Giros de mano, lasso, wedgies y passes, terminando con isolations que mantienen el hoop quieto en el espacio.`,focus:`Hoop · fuera del cuerpo`},"hoop-full-flow":{name:`Flow completo de hoop`,description:`On-body y off-body juntos: escalators, neck hooping y los trucos off-body en un solo flow largo.`,focus:`Aro · flow`},"hoop-body-zones":{name:`Zonas del cuerpo con el aro`,description:`Cintura en ambos sentidos, luego caderas, muslos y pecho, subiendo y bajando el aro entre zonas.`,focus:`Aro · en el cuerpo`},"hoop-tricks-session":{name:`Trucos con el aro`,description:`Giros laterales, el coin flip, el weave, un lanzamiento y el drop-in de vuelta al cuerpo.`,focus:`Aro · fuera del cuerpo`},"hoop-doubles-session":{name:`Doble aro`,description:`Dos aros: giros de mano en espejo y desfasados, giros laterales y un aro en la cintura con un giro en la mano.`,focus:`Aro · dobles`},"poi-foundations":{name:`Fundamentos de poi`,description:`Primero un poi, luego dos: giros de pared hacia adelante y hacia atrás, ruedas a tu lado, split time y la mariposa.`,focus:`Poi · primeros giros`},"poi-weave-session":{name:`Tejidos con poi`,description:`Del tiempo dividido al tejido de tres tiempos en ambos sentidos, y luego el tejido de dos tiempos, reels y crossers.`,focus:`Poi · tejidos`},"poi-flower-lab":{name:`Laboratorio de flores con poi`,description:`Extensiones y aislamientos, luego antispin con un poi y con dos, y una flor inspin para terminar.`,focus:`Poi · flores`},"daily-mixed-flow":{name:`Flow mixto diario`,description:`Un poco de cada arte: cascade, giros de staff y hooping, con un movimiento de movilidad entre props.`,focus:`Mixto · práctica`},"poi-symmetry-lab":{name:`Poi symmetry lab`,description:`Visit vertical-axis (together-opposite), central-point (split-same) and horizontal-axis (split-opposite) patterns with catalog moves.`,focus:`Poi · geometry`},"poi-hybrid-session":{name:`Poi hybrid session`,description:`Cateye, antispin-and-spin and plane hybrids with hide-one-prop study in mind.`,focus:`Poi · hybrids`},"poi-weave-degrees":{name:`Poi weave degrees`,description:`Split foundation into three-beat and five-beat weaves — try degree-of-twist cues in Settings.`,focus:`Poi · weaves`},"staff-symmetry-lab":{name:`Staff symmetry lab`,description:`Together-opposite butterfly, split-same fountain and figure-8 weave — three cells of the timing map on one staff.`,focus:`Staff · geometry`},"staff-flower-lab":{name:`Staff flower lab`,description:`Extensions into isolations, then four-petal antispin and a slower three-petal antispin.`,focus:`Staff · flowers`},"staff-contact-session":{name:`Staff contact session`,description:`Fishtail into hand and forearm rolls, angel roll, then a calm held spin to finish.`,focus:`Staff · contact`},"hoop-plane-lab":{name:`Hoop plane lab`,description:`Visit on-body floor work, off-body wall spins and a horizontal lasso so the plane map sticks.`,focus:`Hoop · planes`},"hoop-isolation-session":{name:`Hoop isolation session`,description:`Hand spin into isolation and cateye, then weave and pass to reconnect with travel.`,focus:`Hoop · isolations`}},n=JSON.parse(`{"start-here":{"title":"Empieza aquí: tu primera semana de flow","summary":"Elige un prop, practica diez minutos al día al beat, y deja que el árbol de desbloqueo te diga qué sigue.","imageAlt":"Figura 3D lanzando una sola pelota de malabares de mano a mano","body":["Las artes de flujo parecen magia desde fuera: pelotas suspendidas en el aire, un bastón que se convierte en un borrón, un aro orbitando a una bailarina que apenas parece moverse. Desde dentro son una pila de habilidades muy pequeñas, cada una aprendible en una tarde, superpuestas hasta que la pila parece no costar esfuerzo. Tu primera semana trata de la base de esa pila.","Elige un implemento para empezar. El malabarismo enseña timing y coordinación mano-ojo; el bastón enseña planos y cambios de mano suaves; el aro enseña ritmo con todo el cuerpo. Puedes aprender los tres, pero uno a la vez mantiene tu atención donde está el progreso. El árbol de Recompensas muestra cada movimiento de cada arte, desde el primer lanzamiento o giro hasta patrones avanzados, y abre los siguientes cuando dominas aquello sobre lo que se construyen.","Practica poco y a menudo. Diez minutos enfocados al día superan a una hora el domingo, porque la coordinación se consolida entre sesiones, sobre todo durante el sueño. Una rutina corta de la página de Rutinas, un calentamiento y unos cuantos pasos contados de tu movimiento actual es una práctica completa.","Practica al ritmo desde el primer día. Cada movimiento en SynthFlow se cuenta en compases a un tempo, con música o percusión generada que coincide. El ritmo te da algo a lo que aferrarte cuando el implemento no coopera, y hace que el progreso sea medible: una ronda limpia a 90 BPM esta semana, 100 la próxima.","Espera caídas. Todo el mundo deja caer, incluidos los profesionales en ensayo. Una caída te dice qué lanzamiento o recepción necesita atención; no dice nada sobre el talento. Recoge el implemento, espera al siguiente tiempo fuerte y vuelve a intentarlo. Al final de la semana tendrás un movimiento que puedes hacer sin pensar, y ese es el momento en que empieza el flow."]},"counting-and-the-beat":{"title":"Cuentas, compases y el ritmo","summary":"Por qué cada movimiento se cuenta en compases a un tempo, y cómo encajar tus lanzamientos y giros en la música.","imageAlt":"Figura 3D haciendo malabares con una cascade de tres pelotas con arcos dibujados sobre las manos","body":["La música está hecha de pulsos agrupados en compases, normalmente cuatro pulsos por compás. Los movimientos de flujo están hechos de ciclos: un lanzamiento de cada mano, media vuelta del bastón, una órbita del aro. Cuando un ciclo cae en el pulso, el movimiento y la música se vuelven una sola cosa. Por eso SynthFlow mide cada paso de rutina en compases en lugar de segundos, y por eso cada movimiento indica cuántos pulsos dura un ciclo.","En una cascade de tres pelotas cada lanzamiento cae en un pulso, alternando derecha e izquierda. En un front spin de bastón, media vuelta suele durar un pulso. El hooping en la cintura suele ser una órbita por pulso a un tempo relajado. Las cuentas del reproductor nombran lo que ocurre en cada pulso, y la figura 3D se mueve exactamente en el mismo reloj que el audio, para que puedas copiarla a tiempo.","El tempo se mide en pulsos por minuto (BPM). Cada movimiento tiene un rango cómodo: lo bastante lento para mantenerse limpio, lo bastante rápido para que el implemento conserve su inercia. Por debajo del rango los implementos que giran se estancan y los lanzamientos suben tanto que se desvían; por encima empiezas a apresurarte y a dejar caer. El editor te avisa cuando un paso queda fuera del rango de su movimiento.","Empieza cada paso en el tiempo fuerte, el «uno» del compás. La cuenta inicial te da un compás para poner el implemento en movimiento antes de que empiecen los compases contados. Si pierdes el ritmo, no lo persigas: detente, escucha el siguiente «uno» y vuelve a entrar. Los músicos llaman a esto encontrar el inicio del compás, y también funciona para los artistas de flujo.","Contar en voz alta durante unas cuantas sesiones ayuda más de lo que parece. Decir «uno, dos, tres, cuatro» mientras haces malabares ata el ritmo a tu respiración y tu voz, así sobrevive cuando el patrón se complica. Cuando las cuentas vivan en tu cuerpo, desactiva las cuentas habladas en Ajustes y deja que la música te lleve."]},"tempo-ladders":{"title":"Escaleras de tempo: lento es fluido, fluido es rápido","summary":"Sube unos pocos BPM a la vez desde un tempo que puedas hacer limpio, y baja de nuevo en el momento en que la forma se rompa.","imageAlt":"Figura 3D girando un bastón frente al cuerpo en el plano de pared","body":["Una escalera de tempo es el mismo movimiento repetido a tempos crecientes: ocho compases a 80 BPM, ocho a 88, ocho a 96, y así. Es la forma más fiable de hacer un movimiento más rápido sin volverlo más desordenado, y varias rutinas integradas se construyen en torno a ella.","Empieza en un peldaño que puedas hacer limpio, aunque se sienta demasiado fácil. El propósito del peldaño más bajo no es el desafío; es ensayar la forma correcta para que sea la forma lo que se acelere. Sube una cantidad pequeña, alrededor del cinco al diez por ciento. Los saltos grandes cambian el movimiento: los lanzamientos bajan, los giros se vuelven más superficiales y acabas practicando un truco distinto.","Deja de subir cuando se rompa la forma, no cuando dejes caer. Vigila las primeras señales: picos que se vuelven desiguales, el bastón que se sale de su plano, el aro que sube o baja. Esas son las señales para bajar un peldaño y repetirlo. Terminar una escalera con una ronda limpia a un tempo justo por debajo de tu límite le enseña ese tempo a tu cuerpo; terminar con un desastre le enseña el desastre.","Los tempos lentos son más difíciles de lo que parecen para los implementos que giran, porque el implemento tiene menos inercia para atravesarlos. Si un bastón o un aro se estanca en la parte baja de su rango, mantén el tempo y agranda el movimiento ligeramente, o llévalo a mitad de tiempo con la música: un ciclo cada dos pulsos.","Registra tu tempo limpio máximo para cada movimiento en Progreso. Ver ese número subir con las semanas es una buena motivación, y también muestra cuándo un movimiento se ha estancado y necesita un ejercicio diferente en lugar de más de lo mismo."]},"siteswap-notation":{"title":"Siteswap: el malabarismo escrito con números","summary":"Cada número indica cuántos pulsos después se vuelve a lanzar una pelota; los números impares cruzan, los pares se quedan, y el promedio es la cantidad de pelotas.","imageAlt":"Figura 3D haciendo malabares con el siteswap 441 con dos lanzamientos altos y un zip rápido","body":["Los patrones de malabarismo son difíciles de describir con palabras y fáciles de describir con números. El siteswap, desarrollado de forma independiente a mediados de los años ochenta por malabaristas en Cambridge, en Caltech y en Santa Cruz, escribe un patrón como una secuencia repetida de dígitos. Es así como los malabaristas comparten patrones, comprueban si una idea puede funcionar y descubren trucos que nadie ha probado. SynthFlow lo usa para animar cada patrón de malabarismo desde el mismo motor.","Imagina las manos lanzando alternativamente en cada pulso: derecha, izquierda, derecha, izquierda. Cada dígito de un siteswap dice cuántos pulsos desde ahora se volverá a lanzar la pelota lanzada en este pulso. Un 3 vuelve tres pulsos después; como tres es impar, cae en la otra mano. Una cascade de tres pelotas es simplemente 3, 3, 3, 3 para siempre, escrito simplemente como 3. Un 4 vuelve cuatro pulsos después en la misma mano, que es la fountain de cuatro pelotas.","Los números pequeños tienen significados especiales. Un 2 vuelve a la misma mano dos pulsos después, lo que en la práctica significa sostener la pelota un momento. Un 1 cruza a la otra mano en el pulso inmediatamente siguiente, un zip rápido directo al otro lado. Un 0 es una mano vacía. Los números más grandes son lanzamientos más altos: un 5 es un lanzamiento cruzado alto.","Lee un patrón dígito a dígito. En 441, dos lanzamientos se quedan en su propio lado mientras una tercera pelota cruza por debajo de ellos. En 531, un lanzamiento cruzado alto sube mientras un lanzamiento de cascade y un zip mantienen las otras dos pelotas en movimiento. En 423, un lanzamiento a altura de fountain, una pelota sostenida y un lanzamiento de cascade se turnan.","El teorema del promedio te dice cuántas pelotas necesita un patrón: suma los dígitos y divide por cuántos hay. 441 suma 9 entre tres dígitos, así que tres pelotas. Si el promedio no es un número entero, la secuencia no se puede hacer malabares. Una segunda comprobación es que dos pelotas no pueden caer en la misma mano en el mismo pulso, que es como los malabaristas detectan patrones imposibles antes de intentarlos.","El siteswap también tiene notación para ambas manos lanzando juntas, escrita entre paréntesis como (4,4), y para lanzar dos pelotas desde una mano a la vez, escrita entre corchetes. No necesitas nada de esto para hacer buenos malabares, pero una vez que los números encajan, cada nuevo nombre de patrón empieza a explicarse solo. Abre el glosario de Flow para los números individuales."]},"passing-basics":{"title":"Fundamentos del passing: malabares con un compañero","summary":"Colocaos frente a frente, lanzad con las derechas a la vez, pasad recto hacia la mano izquierda del otro y contad: seis tiempos, cuatro tiempos, dos tiempos.","imageAlt":"Dos malabaristas en 3D frente a frente, pasándose pelotas en línea recta de uno a otro","body":["El passing es hacer malabares con otra persona. Dos malabaristas se colocan frente a frente, cada uno con su propia cascada, y de vez en cuando uno de los lanzamientos va hacia el compañero en lugar de hacia ti. Es una de las cosas más sociales del malabarismo: los pases con mazas son la manera en que muchos malabaristas se pasan una noche de festival, y convierten la práctica en una conversación.","Colocaos a unos dos metros y medio de distancia con pelotas, un poco más lejos con mazas. Los dos empezáis a hacer malabares en el mismo conteo, con las derechas lanzando a la vez. El pase estándar es recto: sale de tu mano derecha y aterriza en la mano izquierda de tu compañero, justo enfrente de ti. No se lanza a la cara. Apunta a su cadera izquierda y dale un arco que culmine justo por encima de la altura de la cabeza, a mitad de camino entre los dos.","Los patrones de pases se nombran según cada cuánto pasas. En un seis tiempos pasas cada sexto lanzamiento, lo que deja cinco selfs en medio para que se asienten. En un cuatro tiempos, el calentamiento estándar, pasas en cada segundo lanzamiento con la derecha: pase, self, self, self. En un dos tiempos cada lanzamiento con la derecha es un pase y cada uno con la izquierda es un self. En un tres tiempos los pases alternan de mano, así que también aprendes a pasar con la izquierda. Los Ultimates, o el patrón de un tiempo, convierten cada lanzamiento en un pase.","Contad en voz alta al principio. «Pase, dos, tres, cuatro» os mantiene en el mismo beat, y en cuanto uno de los dos pierde el ritmo, los pases dejan de llegar a tiempo. La voz de conteo de SynthFlow dice «pase» en tus pases y «self» en los demás lanzamientos, marcando el beat, así que puedes practicar el timing en solitario mientras tu compañero en pantalla hace malabares contigo.","Empieza con una pelota. Lánzala hacia tu compañero, deja que la pase de su mano izquierda a la derecha y te la devuelva. Luego coged dos pelotas cada uno y pasad con las derechas a la vez, entregando la pelota que llega de la izquierda a la derecha. Solo entonces añade la cascada. La mayoría de las caídas al pasar vienen de pases demasiado largos o demasiado planos, y ambos fallos se corrigen más fácilmente con una pelota que con seis.","En la notación de SynthFlow, un patrón de pases enumera tus lanzamientos y los de tu compañero, uno por beat, con p marcando un pase: el cuatro tiempos es <3p 3 3 3|3p 3 3 3>. Los números significan lo mismo que en siteswap. Un 4p es un pase doble que aterriza un beat más tarde; así se construyen los patrones de siete mazas."]},"planes-and-geometry":{"title":"Planos: pared, rueda y suelo","summary":"Los implementos que giran viven en planos planos; mantener el plano limpio es la mayor parte de lo que hace que un bastón o un aro se vean nítidos.","imageAlt":"Figura 3D tejiendo un bastón en un ocho en ambos lados del cuerpo","body":["Un bastón o un aro que gira barre una superficie plana, llamada su plano. Los artistas de flujo describen tres planos básicos respecto al cuerpo. El plano de pared está frente a ti, como un cristal contra el que pudieras apoyar las palmas. El plano de rueda está a tu lado, como gira una rueda de carro a lo largo de tu costado. El plano de suelo es horizontal, paralelo al suelo, como en un helicoptero por encima de la cabeza o un lazo.","Los planos limpios son lo que el público lee como habilidad. Un bastón que se tambalea fuera de su plano parece inseguro aunque nunca caiga; un aro que se mantiene perfectamente plano durante un pase parece no costar esfuerzo. La mayor parte de la práctica temprana trata en silencio sobre planos: evitar que las muñecas giren, evitar que los codos se abran y dejar que los hombros muevan el implemento en lugar de las manos.","Muchos trucos se definen por cambiar de plano. Un weave en ocho mueve el bastón del plano de rueda en un lado al plano de rueda en el otro. Un butterfly lo pliega detrás del hombro y lo devuelve. Un escalator camina un aro arriba y abajo del cuerpo mientras su plano se mantiene nivelado. Aprender dónde empieza y termina cada movimiento en el espacio es cómo los enlazas en flow.","El visor 3D puede dibujar el plano mientras practicas. Actívalo cuando aprendas un giro nuevo y compara: ¿tu bastón se inclina hacia ti en la parte superior? ¿el aro baja en la parte delantera? Un espejo o la cámara de un teléfono muestran lo mismo. Mirar desde la vista lateral es especialmente útil para movimientos de plano de pared, porque la inclinación es invisible desde el frente.","Los planos también ayudan con la seguridad y el espacio. Antes de una sesión, comprueba que cada plano que vas a usar esté despejado: la pared frente a ti, las paredes a tus lados y el techo arriba para movimientos de plano de suelo y por encima de la cabeza. Un plano limpio sin nada en él es un plano seguro."]},"spin-and-antispin":{"title":"Spin, antispin e isolations","summary":"Cómo gira el implemento en comparación con la mano da tres familias de movimiento: spin, antispin e isolation.","imageAlt":"Figura 3D dibujando una flor antispin de cuatro pétalos con un staff","body":["Cuando mueves un implemento giratorio en círculo, ocurren dos rotaciones a la vez: tu mano recorre un círculo y el implemento gira sobre su propio centro. La teoría del flow nombra los movimientos según cómo se relacionan esas dos rotaciones. Es el mismo vocabulario para staff, hoop y poi, y por eso las habilidades se transfieren tan bien entre implementos.","En spin, a veces llamado inspin, el implemento gira en el mismo sentido que el círculo de la mano. Es la dirección natural; la mayoría de los primeros giros son inspin sin que nadie los llame así. La forma trazada es una flor cuyos pétalos apuntan hacia afuera.","En antispin el implemento gira en sentido opuesto al círculo de la mano. Al principio se siente raro, como palmear tu cabeza y frotar tu panza a la vez, pero dibuja la clásica flor de pétalos. El número de pétalos depende de cuántas veces gira el implemento por cada círculo de la mano: tres contrarrotaciones por círculo dan cuatro pétalos, que es el Antispin de Cuatro Pétalos en el árbol de staff.","Una isolation es el caso especial en que la mano gira de modo que un punto del implemento parece congelado en el espacio. Con un staff el centro queda quieto mientras los extremos barren a su alrededor; con un hoop el centro del aro o un punto del borde se queda fijo. Las isolations hacen que parezca que el implemento flota y el cuerpo orbita alrededor de él. Exigen trayectorias de mano precisas, lo que las convierte en un entrenamiento excelente para todos los demás trucos.","Aprende estos movimientos despacio y al ritmo. El antispin sobre todo se beneficia de un tempo muy por debajo de tu velocidad normal de giro, con cuentas que nombren dónde debe estar el implemento: arriba, al lado, abajo, al lado. Usa el fantasma del visor 3D para ver la posición del siguiente beat, y la estela para ver si tu flor tiene pétalos parejos.","Cuando spin, antispin e isolation se sientan familiares en un plano, pruébalos en otro. La teoría sigue siendo la misma y tu cuerpo aprende que el plano es solo un ajuste, lo cual es un gran paso hacia improvisar flow."]},"timing-and-direction":{"title":"Timing and direction: the four relationships","summary":"Together or split time, same or opposite direction — four relationships that let spinners name patterns and move between them.","imageAlt":"3D figure spinning a poi butterfly with hands close together","body":["Siteswap gives jugglers a shared language for throws. Spinners have something similar for two hands and two props: timing and direction. Timing asks whether the hands (or prop heads) reach the same place in the circle at the same moment — together — or half a turn apart — split. Direction asks whether they turn the same way around that circle or opposite ways. Combine the two and you get four basic relationships: together-same, together-opposite, split-same and split-opposite.","Together-same is the first wall spin most people learn: both poi or both staff ends travel as a pair. Split-same is the classic weave foundation, where one head is at the top when the other is at the bottom. Together-opposite looks like a butterfly when the hands sit close: the heads kiss at the top and bottom. Split-opposite is the remaining corner, with opposite directions and staggered timing.","These four states are not just labels. They form a small map. Each relationship shares two cardinal positions — top, bottom, or the far sides — with two of its neighbours. At a shared position you can reverse one hand and step into the neighbouring relationship. That is Transition Theory in everyday language: a circle of legal hops, like a musician’s circle of fifths for spinning. The hops that are forbidden are the ones with no shared position, such as jumping straight between together-opposite and split-same without an intermediate stop.","Hand-to-prop speed ratios sit on top of that map. Plain spin, where the hand and the head travel together, is often called a 1:1 CAP. A four-petal antispin flower is a 1:3 relationship: three head turns for each hand circle. A six-petal antispin (or the matching inspin) is 1:5. SynthFlow’s Timing lab lets you switch CAP presets while the 3D coach keeps the beat, so you can see the flower change without leaving offline practice.","Open Learn → Timing & Direction to explore the four cells, hide one prop to read hybrids more clearly, and drill recognition quizzes that stay on your device. The same words appear in the glossary under same time / split time, butterfly, antispin and flower. Once the map clicks, catalog move names stop feeling arbitrary — they become addresses you can travel between on purpose."]},"sequencing":{"title":"Cómo se construyen las rutinas de flow","summary":"Calienta, practica un solo enfoque con enlaces que fluyan, mantén pequeños los saltos de tempo y termina con un enfriamiento fácil.","imageAlt":"Figura 3D pasando un hoop de mano en mano frente al cuerpo","body":["Una buena rutina de flow tiene la misma forma que un buen set musical: una apertura que calienta el ambiente, un medio que construye y un final que deja respirar a todos. Las rutinas integradas de SynthFlow siguen esa forma, y el copiloto del constructor revisa la tuya contra ella.","Abre con un calentamiento. Círculos de muñeca, círculos de brazos y rotaciones de hombros llevan las articulaciones que vas a cargar por todo su rango a un tempo suave. Dos o tres minutos alcanzan para una sesión corta; las sesiones más largas y los días fríos merecen más.","Dale al bloque de práctica un solo enfoque. Elige un movimiento en el que estés trabajando y rodéalo de movimientos que enlacen con él. El constructor muestra cómo se conecta cada paso con el anterior: fluir directo desde la misma posición de mano, un pequeño reajuste de agarre, dejar el implemento en el suelo o construir sobre un truco anterior. Las rutinas que fluyen se sienten como bailar; las rutinas llenas de pausas para dejar el implemento se sienten como una lista.","Mantén pequeños los cambios de tempo entre pasos. Saltar de 80 a 130 BPM reinicia tu timing e invita a las caídas. El copiloto marca los saltos de más o menos un cuarto, plegando medio y doble tiempo para que un paso de hoop a 70 BPM pueda convivir con una pista a 140 BPM.","Vuelve al movimiento enfoque más de una vez. La repetición a lo largo de una sesión, con otros movimientos en medio, construye habilidad mejor que un solo bloque largo, porque cada regreso es un intento fresco desde un punto de partida ligeramente distinto.","Termina con un enfriamiento: un movimiento fácil a tempo lento, o un breve descanso con unas cuantas respiraciones. Baja el ritmo cardíaco y le da a tu coordinación un final tranquilo para recordar. Previsualiza la rutina antes de reproducirla y elimina todo lo que sea claramente la ambición de ayer."]},"effort":{"title":"Cuándo subir el tempo","summary":"Sube cuando la forma se mantiene y estás fresco; baja cuando los picos tambalean, el agarre se tensa o las caídas empiezan a agruparse.","imageAlt":"Figura 3D haciendo malabares con cinco pelotas en una cascade alta","body":["El progreso en el flow viene de practicar al borde de tu habilidad, pero el borde se mueve. Algunos días está más lejos de lo que esperas; otros días se ha replegado. Aprender a leerlo es una habilidad que vale tanto como cualquier truco.","Sube cuando lo básico se mantiene. Si tus picos son parejos, tu staff se queda en su plano, tu hoop se mantiene nivelado y tu respiración es fácil, toma el siguiente escalón de la escalera de tempo o prueba el siguiente ejercicio de la progresión. Los primeros quince minutos de una sesión, después del calentamiento, suelen ser el mejor momento para material nuevo.","Baja cuando la calidad se resiente. Las caídas agrupadas, un agarre que se tensa, los hombros que suben hacia las orejas y la respiración contenida dicen que tu sistema nervioso está cansado. Baja el tempo, vuelve a un movimiento que domines o termina la sesión. Empujar a través de la fatiga sobre todo ensaya errores.","Vigila también las señales físicas. Los lanzamientos y giros repetitivos cargan muñecas, antebrazos y hombros. El dolor que se va en un día es adaptación normal. El dolor agudo, el dolor que crece durante la práctica, el entumecimiento o el hormigueo son razones para parar y descansar; los síntomas persistentes merecen un profesional clínico.","Usa la valoración de esfuerzo después de cada sesión. El asistente de práctica la lee: varias sesiones duras seguidas y sugiere algo más suave, varias fáciles y sugiere un poco más. Las valoraciones honestas producen mejores sugerencias."]},"drops-are-data":{"title":"Las caídas son datos","summary":"Una caída te dice qué lanzamiento o recepción arreglar; tratarla como un fracaso solo te enseña a tensarte.","imageAlt":"Figura 3D intercambiando dos pelotas de malabares entre las manos","body":["Todo malabarista tiene el suelo lleno de pelotas en algún momento. Todo spinner de staff ha escuchado el estruendo. La diferencia entre quienes siguen mejorando y quienes lo dejan rara vez es el talento; es cómo tratan la caída.","Una caída es una medición. Te dice qué lanzamiento salió mal, qué recepción estiraste de más, qué momento del giro perdió su plano. Si la misma pelota sigue cayendo delante de ti, tus lanzamientos se están yendo hacia adelante. Si las caídas llegan después de seis lanzamientos, algo en tu tercer o cuarto lanzamiento está fallando. Observa dónde y cuándo, y luego elige una sola cosa para cambiar.","Tratar las caídas como fracaso tiene un costo. El miedo tensa los hombros y acorta la respiración, y la tensión hace los movimientos más pequeños y rápidos, lo que causa más caídas. La respuesta calmada —recoger, respirar, esperar el downbeat, reiniciar— no solo es agradable; es la respuesta técnicamente correcta.","Cuenta las rondas limpias, no las caídas. SynthFlow domina un movimiento cuando tienes suficientes rondas limpias y minutos de práctica, así que las caídas en el camino son simplemente parte de los minutos. Algunos días registrarás diez rondas limpias, otros días dos. Ambos días cuentan.","A veces deja caer a propósito. Cuando aprendas un truco nuevo, practica el primer lanzamiento o el primer medio giro y deja que caiga. Luego añade la recepción. Aislar el momento riesgoso lo encoge, y aprendes que el suelo no es tu enemigo. Es solo donde va el implemento cuando estás aprendiendo."]},"safety":{"title":"Seguridad: espacio, implementos y señales de alerta","summary":"Despeja tus planos, elige implementos indulgentes, calienta y detente ante dolor agudo, entumecimiento o mareo.","imageAlt":"Figura 3D girando un staff plano por encima de la cabeza con espacio libre alrededor","body":["Las artes del flow son de bajo riesgo comparadas con la mayoría de los deportes, pero los implementos se mueven rápido y viajan más lejos de lo que esperas. Unos cuantos hábitos mantienen la práctica segura para ti, para quienes están cerca y para los muebles.","Despeja tu espacio antes de empezar. Revisa cada plano que vas a usar: al frente, a los lados y arriba. El staff y el hoop necesitan más espacio del que crees, normalmente un círculo de al menos tu envergadura más el largo del implemento en cada dirección, sin nada frágil al alcance. En interiores, cuidado con las luces del techo y los ventiladores; al aire libre, cuidado con el suelo irregular y los transeúntes.","Usa implementos indulgentes mientras aprendes. Las pelotas de malabares tipo beanbag no ruedan lejos. Los staffs acolchados o con puntas de espuma duelen menos cuando te golpean la cabeza, cosa que pasará. Un hoop más grande y pesado gira más despacio y es más fácil de mantener arriba. Sube a implementos más rápidos o vistosos cuando lo básico sea automático.","Calienta antes de cada sesión y aumenta el volumen gradualmente. Lanzar y girar son repetitivos, y la carga repetitiva sobre tejido frío es la causa habitual de muñecas y codos doloridos. Si añades mucho volumen de práctica de golpe, añade también días de descanso.","Detente ante señales de alerta: dolor agudo o eléctrico, entumecimiento u hormigueo en las manos, dolor que empeora a medida que continúas, mareo, o un golpe en la cabeza con cualquier síntoma persistente. Los movimientos de cuello y los contact rolls merecen cuidado extra; apréndelos despacio con un implemento acolchado.","Esta app enseña técnica, no es atención médica. Embarazo, lesiones recientes, problemas articulares y cualquier cosa que te preocupe son razones para consultar a un profesional cualificado antes de añadir carga nueva. El fuego es una disciplina aparte con su propia formación en seguridad; SynthFlow no la enseña."]},"warm-up":{"title":"Por qué importa calentar para el trabajo con implementos","summary":"De dos a cinco minutos de movilidad de muñecas, brazos, hombros y caderas hacen los giros más suaves y cuidan tus articulaciones.","imageAlt":"Figura 3D haciendo círculos lentos de muñeca con los brazos al frente","body":["La práctica de flow parece suave, pero exige mucho a unas pocas articulaciones. El malabarismo repite el mismo lanzamiento miles de veces; el staff gira las muñecas por todo su rango; el hoop balancea la columna y las caderas en cada órbita. El tejido caliente tolera esa repetición mucho mejor que el frío.","Un buen calentamiento de flow es corto y específico. Los círculos de muñeca en ambas direcciones preparan las articulaciones que hacen la mayor parte del trabajo. Los círculos de brazos y las rotaciones de hombros despiertan el manguito rotador y los omóplatos, que controlan el plano de cada giro. Los círculos de cadera y los giros de torso importan sobre todo para el hoop. Los semicírculos de cuello, nunca giros completos, alivian la tensión de mirar hacia arriba un patrón.","Muévete despacio y al ritmo. Los pasos de calentamiento en SynthFlow se cuentan como todo lo demás, a un tempo relajado, así que los primeros minutos de una sesión también afinan tu timing. Cuando salen los implementos, ya te estás moviendo con la música.","Termina el calentamiento con el implemento a media velocidad. Unos lanzamientos lentos, un front spin tranquilo o una órbita grande y lenta de hoop conectan el trabajo de movilidad con el movimiento que vas a practicar, y te dicen cómo se siente tu cuerpo hoy.","Los calentamientos también son una transición mental. Los mismos tres minutos al inicio de cada sesión se vuelven una señal de que la práctica ha comenzado. En días ocupados, el calentamiento a veces es toda la práctica, y eso también cuenta."]},"anatomy-basics":{"title":"El cuerpo detrás de los implementos","summary":"Los antebrazos agarran y sueltan, los hombros dirigen el plano, el core te mantiene quieto: un mapa en lenguaje sencillo para el flow.","imageAlt":"Figura 3D haciendo hoop en la cintura con la parte superior del cuerpo relajada","body":["No necesitas saber anatomía para hacer malabarismo, pero un mapa sencillo te ayuda a entender qué se cansa, qué calentar y qué descansar. La sección Músculos de Learn tiene un modelo interactivo; este artículo es el recorrido corto.","Los antebrazos hacen la mayor parte del trabajo fino. Los músculos del lado de la palma cierran los dedos y flexionan la muñeca; los músculos del dorso del antebrazo abren los dedos y extienden la muñeca. Atrapar y soltar, agarrar un staff y dejarlo rodar, todo pasa aquí. La fatiga del antebrazo es la sensación más común tras una sesión larga, y por eso el agarre relajado es una indicación tan frecuente.","Los hombros dirigen. Los deltoides levantan los brazos; el manguito rotador, cuatro músculos pequeños alrededor de la articulación, mantiene centrado el brazo mientras se mueve. Los músculos alrededor de los omóplatos mantienen todo el sistema estable. Cuando un staff se sale de su plano, la causa suele ser el hombro, no la mano.","El core te mantiene quieto. En malabarismo, un torso inmóvil evita que el patrón se desplace. En hoop, los músculos abdominales y de la espalda impulsan el hoop con pequeños pulsos adelante y atrás. Las caderas y las piernas son tu base: rodillas suaves absorben el movimiento y te permiten cambiar el peso sin perturbar el implemento.","Tus ojos y oído interno también importan. El malabarismo te entrena para mirar los picos, no las manos; el giro entrena tu equilibrio. Sesiones cortas con descansos permiten que ambos se adapten sin mareos. Trata este mapa como alfabetización, no como diagnóstico, y consulta a un profesional por dolor que no cede."]},"biomechanics-safety":{"title":"Muñecas, hombros y carga repetitiva","summary":"Agarre relajado, muñecas neutras y volumen gradual mantienen contentas las articulaciones que hacen todo el trabajo.","imageAlt":"Figura 3D girando un staff con una mano sobre el dorso de la mano","body":["Las lesiones en flow rara vez son dramáticas. Casi siempre son por sobreuso: demasiadas repeticiones, demasiado agarre, muy poco descanso. La buena noticia es que los mismos pocos hábitos previenen la mayoría.","Relaja el agarre. Una pelota de malabares solo necesita la presión suficiente para quedarse en la mano; un staff necesita un anillo flojo de dedos dentro del cual pueda rodar. Apretar cansa los músculos del antebrazo y carga los tendones del codo. Si tus nudillos se ponen blancos o los antebrazos arden tras unos minutos, afloja y baja el tempo.","Mantén las muñecas cerca de la neutra cuando puedas. El giro lleva las muñecas por rangos amplios, lo cual está bien con moderación. Mantenerlas al final de su rango por mucho tiempo, o forzar una muñeca rígida a girar, es lo que las irrita. Deja que el codo y el hombro compartan el movimiento.","Deja que los hombros trabajen, pero no se encorven. Los círculos grandes vienen de la articulación del hombro; un hombro encogido pellizca y se cansa rápido. Revisa en el espejo o en el modo cámara que tus hombros se mantengan abajo, sobre todo en movimientos por encima de la cabeza como el helicopter y el lasso.","Aumenta el volumen gradualmente. Si normalmente practicas veinte minutos, no saltes a dos horas porque se acerca un festival. Aumenta el tiempo total una cantidad modesta cada semana y mantén al menos un día fácil. Cambia de implemento para repartir la carga: el trabajo con hoop descansa los antebrazos que cansa el malabarismo.","El dolor que se desvanece en un día es adaptación normal; el dolor que persiste, crece o viene con entumecimiento no lo es. Descansa, reduce el volumen y busca consejo profesional si continúa. Esto es educación, no consejo médico."]},"choosing-props":{"title":"Elegir tus primeros implementos","summary":"Beanbags para malabares, un staff ligero con extremos acolchados y un hoop grande de adulto hacen las primeras semanas mucho más fáciles.","imageAlt":"Figura 3D girando un hoop alrededor de una mano","body":["Buenos implementos de principiante hacen el aprendizaje más rápido y menos frustrante. No necesitas equipo caro, pero algunas elecciones importan.","Para malabares, empieza con tres beanbags de unos 60 a 130 gramos cada uno. Los beanbags no rebotan ni ruedan cuando se caen, lo que ahorra mucho tiempo buscándolos. Deben caber cómodamente en tu palma. Las stage balls, que son más grandes, y las pelotas de silicona con rebote son para después. Colores iguales te ayudan a ver el patrón; tres colores distintos te ayudan a seguir pelotas individuales al aprender siteswaps.","Para staff, un staff de giro de principiante suele medir entre 1,2 y 1,5 metros, ligero, con extremos acolchados o de goma. Como guía aproximada, debe llegar entre tu pecho y tu hombro cuando se apoya en vertical. Un staff más largo y pesado gira más despacio y suave una vez que tienes lo básico, pero es más difícil para empezar y duele más cuando te golpea. Un grip en el medio ayuda.","Para hoop, empieza más grande y pesado de lo que crees. Un hoop de principiante adulto suele llegar entre la cintura y el pecho cuando se apoya en el suelo. Los hoops más grandes rotan más despacio, dándote tiempo para encontrar el ritmo del waist hooping. Los hoops más pequeños y ligeros van bien para trucos rápidos fuera del cuerpo cuando ya estás cómodo.","Elijas lo que elijas, asegúrate de que el rango de tempo del movimiento le vaya bien al implemento. Los implementos más pesados suelen preferir tempos más bajos. Si el rango cómodo de la app se siente apresurado con tu implemento, pon tu propio tempo en el builder; los conteos siguen."]},"practice-at-home":{"title":"Practicar en casa y en el parque","summary":"Sesiones cortas diarias, un espacio despejado, un borde de cama o sofá para atrapar caídas, y una jam en el parque cuando puedas.","imageAlt":"Figura 3D sacudiendo los brazos entre rondas de práctica","body":["La mayoría de los flow artists aprenden en casa, unos minutos a la vez. Un poco de preparación hace que practicar en casa sea más fácil de empezar y de mantener.","Encuentra tu sitio. Para malabares, pararte frente a una cama o un sofá hace que las pelotas caídas aterricen a la altura de la cintura en vez de rodar bajo los muebles, y también evita que camines hacia adelante. Para staff y hoop, busca el espacio despejado más grande que tengas, revisa el techo y aparta lo que sea frágil. Un jardín o parque es mejor para giros grandes.","Mantén los implementos a la vista. Las pelotas sobre el escritorio se usan durante llamadas y pausas de té; un hoop junto a la puerta se usa. Cuanto menos esfuerzo cueste empezar, más a menudo lo harás. Una rutina de cinco minutos cuenta, y varias sesiones cortas al día se suman rápido.","Usa la app como estructura. Elige una rutina o deja que el asistente te sugiera una, practícala completa y registra tu esfuerzo. Programas cortos como Zero to Cascade le dan a cada semana un objetivo claro, lo que evita que te disperses entre trucos.","Practica con otras personas cuando puedas. Existen clubes de malabares, escuelas de circo y quedadas de flow en parques en muchas ciudades. Ver a alguien un paso por delante de ti a menudo corrige algo que un tutorial no pudo, y enseñarle a alguien un paso por detrás de ti hace más clara tu propia técnica. Lleva tus implementos, pregunta en qué están trabajando y comparte lo que los conteos te han enseñado."]},"learning-with-the-app":{"title":"Aprender con el coach 3D","summary":"Bájale la velocidad, refleja el movimiento, activa el fantasma y las estelas, cambia la cámara y usa el modo cámara para recibir feedback.","imageAlt":"Figura 3D realizando una isolation de staff con una estela que muestra la trayectoria","body":["Cada movimiento en SynthFlow está animado en 3D con el mismo reloj que la música, así que la figura siempre está exactamente en el beat. Bien usado, el visor es un maestro paciente que nunca se cansa de mostrarte el mismo lanzamiento.","Primero bájale la velocidad. La escalera de progresión de cada movimiento empieza con versiones lentas y parciales, luego solo manos, y después el movimiento completo en el beat. La media velocidad mantiene intactas las relaciones de tiempo mientras le da tiempo a tus ojos para seguir.","Refleja la figura si aprendes mejor frente a un maestro, y cambia la cámara cuando una vista oculta algo. Las vistas laterales muestran la inclinación del staff y la deriva del lanzamiento; las vistas superiores muestran los planos del hoop y las trayectorias de helicóptero. Las estelas dibujan dónde ha estado cada implemento, lo que convierte un borrón en una forma que puedes estudiar. El fantasma muestra dónde estará el implemento en el siguiente beat.","Observa los errores comunes. Cada movimiento puede mostrar sus fallos típicos, como derivar hacia adelante, alturas desiguales o apurarse, reproducidos deliberadamente mal en la figura, con la señal que los corrige. Reconocer un fallo en el modelo hace mucho más fácil sentirlo en tu propio cuerpo.","El modo cámara te da feedback sobre ti. Con permiso, rastrea tus manos y tu cuerpo mientras practicas y compara tu timing con el beat. El procesamiento ocurre en tu dispositivo. No es perfecto, y una buena luz ayuda, pero incluso un feedback aproximado sobre si vas adelantado o atrasado es valioso.","Por último, cierra el visor de vez en cuando. Practica solo con música y confía en los conteos. El objetivo es un movimiento que puedas hacer sin mirar nada en absoluto."]},"music-for-flow":{"title":"Encontrar música que encaje","summary":"Tempos medidos, mitad y doble tiempo, percusión generada y tus propias pistas mantienen los conteos honestos.","imageAlt":"Figura 3D haciendo hooping al pecho con los brazos levantados","body":["La música convierte la práctica en flow, pero solo si el beat de la música es el beat de los conteos. Una pista a 118 BPM bajo una rutina a 120 BPM se desincroniza en un minuto, y terminas peleando con la música en vez de cabalgarla.","Las pistas incluidas en SynthFlow tienen tempos y downbeats medidos, así que el reproductor puede empezar cada paso en el “uno” de la música y mantener los conteos alineados. El constructor lista primero las pistas que encajan con el tempo de una sección, incluidas pistas a la mitad o al doble del tempo: una pista a 140 BPM lleva perfectamente un paso de hoop a 70 BPM.","La percusión generada funciona a cualquier tempo. Elige un kit para una sección y el reproductor sintetiza un beat que coincide exactamente, ya sea que estés haciendo una escalera de tempo o un drill lento. También es la mejor opción cuando quieres el pulso sin que una melodía te robe la atención.","Puedes analizar pistas desde tu propio dispositivo. La app estima el tempo y el downbeat y te permite verificarlos marcando el ritmo. Las pistas con un pulso electrónico o acústico estable funcionan mejor; la música con cambios de tempo, rubato o intros largas es más difícil de medir y más difícil para practicar.","El streaming de video se desactiva durante la práctica con conteos porque su timing no se puede controlar con precisión. Úsalo para calentamientos o juego libre, donde nada necesita alinearse."]},"plateaus":{"title":"Mesetas y el largo intermedio","summary":"Todo flow artist pasa semanas en las que nada mejora; cambia el drill, el tempo o el implemento antes de cambiar el objetivo.","imageAlt":"Figura 3D haciendo malabares con Mills Mess y los brazos cruzados","body":["El comienzo del flow es maravilloso: algo nuevo cada sesión. Luego, a menudo alrededor del momento en que puedes hacer una cascade estable o mantener un hoop arriba indefinidamente, el progreso parece detenerse. Este largo intermedio es donde la mayoría abandona, y donde ocurre el aprendizaje más interesante.","Las mesetas suelen ser consolidación. Tu sistema nervioso está reorganizando el movimiento para que necesite menos atención, lo cual no se manifiesta como trucos nuevos. A menudo una habilidad que se sintió estancada durante dos semanas aparece de repente una mañana. Sigue practicando durante la parte plana.","Cambia el drill, no el objetivo. Si la cascade no se acelera, practícala a un tempo más bajo con picos perfectos, luego con la mirada en un punto por encima del patrón, luego con una sola mano. Si un movimiento de staff no sale, divídelo en sus mitades y practica cada una al beat. Los drills nuevos le dan a tu cerebro información nueva sobre la misma habilidad.","Entrenamiento cruzado. Aprender un segundo implemento a menudo desbloquea el primero. El hooping mejora el ritmo detrás de los malabares; el trabajo con staff enseña los planos que hacen limpios los trucos de hoop. El árbol de Rewards de cada arte es independiente, así que la variedad nunca cuesta progreso.","Sé amable con esto. Compárate con el mes pasado, no con artistas en línea que han practicado durante diez años. La página de Progress mantiene un registro honesto de minutos, tempos máximos y movimientos dominados. En una semana plana, mírala y observa cuánto ha subido ya la línea."]},"history-of-juggling":{"title":"Una breve historia de los malabares","summary":"Desde una pintura en una tumba egipcia hasta los jongleurs medievales, el teatro de variedades y la matemática moderna.","imageAlt":"Figura 3D haciendo malabares con un shower de tres bolas en círculo","body":["Los malabares son muy antiguos. Una de las imágenes más antiguas que se conocen es una pintura mural en una tumba del Reino Medio en Beni Hasan, Egipto, de unos cuatro mil años de antigüedad, que muestra a mujeres lanzando bolas. Relatos e imágenes de China, Grecia, Roma y el Pacífico sugieren que personas de muchas culturas encontraron su camino hacia lanzar y atrapar para exhibición y juego.","En la Europa medieval, la palabra jongleur, de la que proviene “juggler”, describía a artistas viajeros que cantaban, contaban historias, hacían acrobacias y lanzaban objetos. Los malabares eran una habilidad entre muchas, parte del kit de un artista más que un arte propio.","Los teatros de variedades y circos de los siglos XIX y principios del XX convirtieron los malabares en un acto principal. Los artistas se especializaron: gentleman jugglers con sombreros y bastones, malabaristas de clavas y malabaristas de números empujando hacia siete, ocho y más bolas. Enrico Rastelli, a principios del siglo XX, sigue siendo nombrado a menudo como uno de los más grandes.","A partir de los años 70 creció una cultura de malabares como hobby alrededor de clubes, festivales y convenciones, con personas compartiendo trucos libremente. La matemática se sumó en los años 80 cuando la notación siteswap les dio a los malabaristas una forma de escribir patrones como números, lo que llevó a nuevos trucos descubiertos en papel antes de que alguien los lanzara.","Hoy los malabares se sitúan en el punto de encuentro entre circo, deporte, danza y matemática. Algunos malabaristas compiten en números y resistencia, otros interpretan coreografías con música, otros exploran patrones por sí mismos. Cada ruta empieza con el mismo intercambio de dos bolas, que puedes aprender esta semana."]},"history-of-staff":{"title":"Staff spinning: de arma a flow","summary":"Los bastones de artes marciales, el baton twirling y la performance con fuego alimentaron el moderno spin staff.","imageAlt":"Figura 3D realizando un staff butterfly detrás de los hombros","body":["Un staff es una de las herramientas más antiguas que existen, y hacerlo girar es una habilidad antigua. Muchas tradiciones marciales entrenan con un bastón largo, entre ellas el bō okinawense, el gun chino y el combate con quarterstaff europeo, y sus drills incluyen giros rápidos y cambios de mano tanto para defensa como para exhibición.","El spinning de performance tiene otras raíces también. El baton twirling se convirtió en una disciplina competitiva en el siglo XX, con lanzamientos, rolls y giros que los spinners todavía toman prestados. El teatro, los desfiles y la performance callejera en todo el mundo usaron palos y bastones giratorios mucho antes de que alguien lo llamara flow.","La escena moderna del staff de flow creció a finales del siglo XX junto con la performance con fuego y la cultura de festivales. Los staffs de fuego, con mechas en cada extremo, hicieron visible el giro en la oscuridad y empujaron el arte hacia un movimiento fluido y continuo en lugar de golpes. Los staffs LED trajeron después las mismas visuales al interior.","Casi al mismo tiempo, los flow artists empezaron a describir el giro con una teoría compartida: planos, spin y antispin, isolations, timing y dirección. Mucha de ella se desarrolló en la comunidad del poi y se trasladó al staff, al hoop y a otros props, y por eso las mismas palabras aparecen en toda esta app.","El contact staff, donde el staff rueda sobre el cuerpo en lugar de agarrarse, se convirtió en un estilo propio con rolls por el cuello, los hombros y los brazos. Hoy el staff spinning va desde la demostración marcial hasta el contact flow lento y meditativo, todo construido sobre el mismo primer giro de rueda."]},"history-of-hoop":{"title":"El hoop: de juguete antiguo a flow art","summary":"Los hoops han sido juguetes y herramientas durante milenios; una moda de los años 50 y un renacer en los festivales convirtieron el hoop dance en un arte.","imageAlt":"Figura 3D subiendo un hoop giratorio por el cuerpo","body":["Los hoops están entre los juguetes más antiguos. Se describe o representa a niños del antiguo Egipto, Grecia y Roma haciendo rodar hoops con palos y girándolos alrededor del cuerpo, y los juegos con hoop aparecen en muchas culturas desde entonces.","Los hoops también tienen un profundo significado cultural en algunas tradiciones. El Hoop Dance que se practica en muchas comunidades nativas americanas usa varios hoops para formar figuras como animales y la tierra, contando historias a través del movimiento. Es una tradición viva por derecho propio, distinta de la escena moderna del flow, y vale la pena aprender sobre ella de sus propios practicantes.","La fiebre del hula hoop de plástico de finales de los años 50, impulsada por hoops producidos en masa en Estados Unidos, puso un hoop en millones de hogares casi de la noche a la mañana. Durante décadas después, el hoop se vio sobre todo como un juguete para niños y un aparato de fitness.","Desde finales de los 90 y los 2000, los hoopers adultos en festivales y comunidades online empezaron a tratar el hoop como pareja de baile. Hoops más grandes y pesados hechos a mano facilitaron el hooping on-body para adultos, mientras que los hoops más pequeños abrieron trucos rápidos off-body. Los vídeos compartidos difundieron vocabulario como isolations, wedgies y escalators mucho más allá de una sola ciudad.","El hoop dance moderno toma teoría del staff y del poi, y ritmo de todo tipo de música. Es accesible, alegre y profundo: un principiante puede encontrar el ritmo de cintura en un día, y un experto puede pasar años refinando una sola isolation."]},"fire-and-led":{"title":"Props de fuego, LED y performance","summary":"Los props de performance cambian peso, velocidad y riesgo; aprende cada movimiento primero con props de práctica y entrena el fuego por separado.","imageAlt":"Figura 3D haciendo girar un hoop plano sobre la cabeza como un lazo","body":["Ver un staff de fuego o un hoop LED de noche suele ser lo que atrae a la gente al flow. Los props de performance son maravillosos, pero no son lo mismo que los props de práctica, y pasar a ellos merece un plan.","Los props LED suelen ser más pesados que sus versiones de práctica por las baterías y la electrónica. Eso cambia el momento: los giros llegan más lejos, los lanzamientos se sienten distintos y las muñecas trabajan más. Aprende cada movimiento primero con tu prop de práctica, y luego espera un breve periodo de adaptación con el LED. Baja el tempo en las primeras sesiones.","La performance con fuego es una disciplina aparte. El manejo del combustible, las zonas seguras de giro, los safety spotters con mantas ignífugas, la ropa adecuada y las normas locales importan, y lo mejor es aprenderlo en persona con artistas de fuego con experiencia. SynthFlow no enseña fuego, y nada en la app debe practicarse con props encendidos.","Una buena regla que se usa en muchas comunidades de flow es ejecutar un movimiento con un prop de performance solo cuando puedes hacerlo de forma fiable, muchas veces seguidas, con un prop de práctica. Bajo luces o llamas no hay espacio para experimentos.","La performance también cambia cómo secuencias. El público lee planos grandes, transiciones limpias y momentos claros de quietud. Crea rutinas de performance en el builder como cualquier otra, previsualízalas y ensaya siempre con la misma música para que los counts se vuelvan coreografía."]},"cap-notation":{"title":"Speed ratios and CAP-style notation","summary":"Read hand:head speed ratios and the Θ1 Θ2 ; ρ1 ρ2 shorthand used in community CAP papers — without confusing speed ratio with assembly CAPs.","imageAlt":"3D figure drawing a four-petal antispin flower with poi","body":["Spinners share two related languages that are easy to mix up. The first is a simple speed ratio: how many times the prop head turns for each hand circle. Plain forward spin is 1:1. A three-petal antispin flower is often 1:2, a four-petal flower is 1:3, and a six-petal flower is 1:5. SynthFlow’s Timing lab and viewer chip show this as a speed ratio so you can compare flowers without memorising petal counts alone.","The second language comes from community papers on Continuous Assembly Patterns. A pattern is written as two harmonic turns and two length moduli: Theta1 Theta2 ; Rho1 Rho2. Theta1 is usually the arm’s turn rate; Theta2 is the relative turn of the head. Rho1 and Rho2 are relative lengths of the arm path and the tether path. When the two lengths match, Rho1 equals Rho2, and the curve is a rosette — the familiar even flower. When the lengths are tuned so tip and hand appear to move at the same audience speed, the curve is a cycloid. SynthFlow shows a derived readout such as 1 −3 ; 1 1 for four-petal antispin; it does not yet let you free-edit Rho while keeping petal math intact.","Hybrid and assembly CAP are different ideas that both use the word CAP in older writing. A hybrid here means two hands running different elementary patterns in parallel — for example one hand isolating while the other extends (a cateye). An assembly CAP means chaining elementary patterns in series on one prop into one longer cycle. SynthFlow’s catalog already ships many parallel hybrids; serial assembly remains a future explorer. Quizzes ask you to tell those ideas apart so the vocabulary stays sharp.","Use the Timing lab Notation panel while you change speed-ratio presets. Watch the Θ2 sign flip for antispin, stay positive for inspin, and land on 1 1 for plain spin. Link that picture to the Transition Theory map: the same flower can sit in together-same or split-same, and legal hops still follow shared cardinals. For deeper reading, community HTML references are linked from Credits and from the Timing page footer — SynthFlow ships original coaching copy offline and does not bundle third-party PDFs.","Practice tip: pick one speed ratio for a whole practice block. Name it out loud on the downbeat — “one to three” — before you change petals. When the ratio is stable, change timing or direction instead. That separation of concerns is what makes the four-cell map and the flower language work together instead of fighting in your head."]},"spinning-geometry":{"title":"Spinning geometry: symmetry to timing and direction","summary":"Choose a symmetry — central point, vertical axis, or horizontal axis — and land on the matching timing and direction cell.","imageAlt":"3D figure in a poi butterfly, opposite direction same time","body":["One way to invent poi patterns is to start from geometry instead of from move names. Pick a shape that has a clear symmetry, then ask which rotation of the hands respects that symmetry. Community writing (often summarised as a “symmetry method”) maps three everyday symmetries onto the same Timing and Direction grid SynthFlow already uses.","Central-point symmetry means the pattern looks the same if you rotate it around a centre in the plane. That configuration lands on same direction with split time — the split-same cell, the foundation under weaves and chase patterns. Vertical-axis symmetry mirrors left and right across a vertical line through the body; that wants opposite direction with same (together) time — the butterfly family. Horizontal-axis symmetry mirrors across a waist-high line and wants opposite direction with split time — the remaining opposite corner of the map.","Together-same, the first wall spin many people learn, is not forced by those three symmetries alone. It still matters as a neighbour on the transition map: you can hop into it from together-opposite at the top or bottom, or from split-same at the sides. Thinking in symmetries does not replace Transition Theory; it gives you a reason to visit three of the four cells on purpose.","Open Learn → Timing → Symmetry and tap each symmetry while watching the coach. Hide one prop if the picture is busy. Then take the built-in poi-symmetry-lab routine and visit vertical, central, and horizontal cells with catalog moves you already own. The quiz bank asks both directions: given a clip, name the symmetry; given a symmetry label, recognise the timing and direction.","When you improvise, try one constraint per phrase: “this phrase is vertical-axis only.” Stay in together-opposite until the phrase ends, then hop legally into a neighbour. Geometry becomes a compositional tool instead of a trivia fact, and your transitions stay clean because you already know which cardinals you share with the next cell."]},"hybrid-math":{"title":"Hybrid drivers: spin, isolation, extension, cateye","summary":"Treat each hand as a driver on a unit circle where poi length matches an isolation diameter, then mix same and split timing.","imageAlt":"3D figure performing a poi cateye hybrid","body":["A hybrid in this sense is two hands doing different elementary jobs at once. One hand may spin while the other isolates; one may extend while the other draws a cateye almond; both may isolate in split time. Community hybrid maths treat those jobs as drivers on a shared configuration space. A useful picture is a unit circle where the poi length is about the diameter of an isolation — the hand path of a cateye or extension variant sits on that scale so the two shapes can nest cleanly.","SynthFlow already encodes many of these pairs. Petal tuples such as [4, 0] mean the right hand draws a four-petal antispin while the left keeps plain spin. Extension flags and isolation petals build cateyes and iso–spin pairs. Plane hybrids swap wall, wheel and floor mid-cycle. The Hybrids tab in the Timing lab lays a small grid of timing (same or split) against drivers (spin, isolation, extension, cateye) so you can see the live coach without hunting the catalog first.","Hide one prop when the pattern is asymmetric. Your eyes need a clean read of each driver’s path before you put both back. Count slowly. Name the right hand’s job on the odd beats and the left hand’s job on the even beats until the labels stick. Then restore both props and keep the same names — the hybrid is still two simple patterns, not one mysterious blob.","Quizzes ask which hand is isolating versus spinning, and whether the timing is same or split. The poi-hybrid-session routine and the progression week after antispin start give you a practice path that stays offline. For plane-change hybrids such as wall-to-wheel, remember the switch wants a shared line between planes; for driver hybrids, the switch is about roles, not planes.","Keep vocabulary honest: parallel hybrids are not the same as serial assembly CAPs. If you are chaining stalls into flowers on one hand over time, that is assembly thinking. If both hands run different drivers in the same cycle, that is hybrid thinking. The glossary entries for hybrid, assembly CAP, and speed ratio keep those three ideas separated so coaching cues stay short."]},"degrees-and-weaves":{"title":"Degree of twist and weave counts","summary":"Count weaves in beats or in degree-of-twist labels such as −1_0_+1 for three-beat and −2…+2 for five-beat patterns.","imageAlt":"3D figure in a three-beat poi weave","body":["Weaves sit on split timing: one poi is high when the other is low, and the planes trade sides of the body. The classic three-beat weave crosses after three beats of that split foundation; the two-beat weave crosses faster; the five-beat weave stays longer on each side. SynthFlow already ships these as catalog moves. Degree-of-twist language adds another counting layer without changing how long a beat is.","In that language a three-beat phrase can be written with labels that step through minus one, zero, and plus one — compactly −1_0_+1. A five-beat phrase stretches to −2_-1_0_+1_+2. The signs describe facing and twist relative to the body line: facing inside versus facing outside, outswing versus inswing. Advanced inversions and introversions belong in the glossary as future vocabulary; this pass does not add new inversion generators to the catalog.","In Settings → Timing you can choose weave count style: beats (the default spoken one–two–three) or degrees (the pattern index spoken while the degree labels are what the theory names). The beat clock length does not change — only the cue mapping. Use degrees when you are studying notation; use beats when you are linking to music phrases.","Practice the poi-weave-degrees routine after you own the three-beat weave. Add the five-beat week on the weave ladder progression when the longer side stays clean. On the Timing lab, remember that weaves live in the split-same neighbourhood of the map; legal hops out of a weave still want shared cardinals, just like any other split-same pattern.","Quiz items ask you to match a notation string or a weave clip to two-beat, three-beat or five-beat families. Say the degree string once before you spin, then spin without talking. When the string and the body agree, you can improvise crossings without losing the split foundation underneath."]},"staff-vtg":{"title":"Staff theory: two ends, timing and direction","summary":"How Vulcan Tech Gospel timing and direction apply when both ends of a staff are visible, plus snapshots and speed ratios.","imageAlt":"3D figure drawing a four-petal antispin flower with a staff","body":["Siteswap gives jugglers digits for throws. Staff spinners share a different language with poi and clubs: timing and direction. Timing asks whether the two ends (or two hands on double staff) reach matching places in the circle together or half a turn apart. Direction asks whether they turn the same way or opposite ways. Those four relationships — together-same, together-opposite, split-same, split-opposite — are the backbone of community spin theory often summarised as Vulcan Tech Gospel.","A staff shows both ends at once. When you isolate the centre, one end extends while the other draws the complementary path. Clubs show only one end, so isolation and extension feel like separate moves even when the underlying geometry is the same. In the Timing lab, switch the prop to staff and watch both tips leave trails; that picture is the snapshot idea — a still of arms and props across an axis that you can compare between patterns.","Speed ratios sit on top of the map. Plain spin is 1:1. Four-petal antispin is a 1:3 relationship; six-petal is 1:5. SynthFlow’s lab presets flip those ratios while the beat clock stays steady. Legal transitions still hop only between cells that share a cardinal — top, bottom, or the sides — just as in the poi Timing map.","Double staff borrows the same four cells with one short staff in each hand. Same-time wheels and split-time wheels are addresses on that map, not separate mysteries. Choreography systems such as The Kinetic Alphabet write sequences as pictographs on this geometry; SynthFlow links out for that sheet-music layer and does not ship letter charts.","Open Learn → Timing, choose staff, and drill the quiz in staff mode. Then take a flower or symmetry routine from the catalog. Name the cell out loud before you change petals. When the map and the ends agree, improvisation stops feeling like a list of trick names and starts feeling like travel between addresses."]},"contact-staff-map":{"title":"Contact staff: rolls, wraps and open hands","summary":"A map of contact classes — fishtail, rolls, angel, palm — by body point and plane, without inventing a siteswap for contact.","imageAlt":"3D figure performing a staff fishtail on the open hand","body":["Contact staff means the prop travels across skin and clothing instead of living in a tight grip. There is no community-wide digit system like siteswap for contact. What teachers share is a taxonomy: what kind of contact (roll, wrap, stall, fishtail), where on the body it happens, and which plane the staff sits in while it travels.","Fishtails keep the staff pivoting on an open hand or wrist while the ends draw linked circles front and back. Hand rolls and forearm rolls send the staff across a surface without a catch in the middle. Angel rolls carry that idea across the upper back from arm to arm. Palm spins and steering-wheel turns keep contact but stay more held. Neck and shoulder rolls need padding and clear space — learn them slowly with a soft staff.","Entries and exits matter as much as the middle. Many contact phrases start from a held spin, open the hand at a known beat, ride the roll, then catch again. SynthFlow’s contact explorer lets you preview catalog contacts by class and plane offline so you can see the family before you drill. The quiz asks you to name the family from a short clip.","Treat contact as a second language beside tech spinning. Timing and direction still describe held patterns; contact adds body points and roll direction. Do not force one notation to cover both. Community research notes and forum taxonomies are linked from Credits for operators; the app ships original coaching copy only.","Practice tip: pick one contact class for a week. Fishtail until both hands feel even, then add a hand roll on the same plane. Use the staff-contact-session routine after foundations. Stop when the staff chatters or your wrists tighten — contact rewards soft hands more than ambition."]},"hoop-on-off-body":{"title":"Hoop map: on-body, off-body and planes","summary":"Hoop has no siteswap. Learn the teaching map — on-body versus off-body, horizontal versus vertical planes, and the transitions between them.","imageAlt":"3D figure waist hooping with a relaxed upper body","body":["Juggling has siteswap. Staff and poi share timing and direction. Hoop dance’s closest “theory” is a map, not a digit string. The first axis is on-body versus off-body: is the hoop riding a body zone (waist, chest, knees) or spinning in the hands away from the torso? The second axis is plane: horizontal work parallel to the floor (lasso, vortex, waist orbits) versus vertical work in the wall or wheel plane (weaves, hand spins, many isolations).","Most beginner curricula walk that map on purpose. Waist hooping both ways, then hips and chest, builds on-body rhythm. Off-body vertical weaves and hand spins free the torso. Horizontal tricks above the head open a second plane. Transitions such as escalators, spirals and hinges are the roads between cells — not decorations.","SynthFlow’s Hoop lab lays those axes over live catalog moves. Pick on-body or off-body, pick a plane, pick a family, and watch the coach. Quizzes ask you to classify a clip. Routines such as hoop-plane-lab force you to visit more than one cell in a session so the map sticks in your body as well as your head.","Unit-circle thinking from spinning props still helps. A hoop cateye nests isolation and extension-like paths so the rim draws an almond; the same isolation diameter idea appears in poi hybrids. You do not need equations to use the picture — keep the hoop’s path size matched when you combine floating isolations with open extensions.","Further reading lives on community curriculum sites linked from Credits. SynthFlow does not ship paid course video. Use the lab offline, then take one transition — waist to escalator, or weave to lasso — and repeat it until the change feels boring. Boring transitions are the ones you can dance with."]},"hoop-isolations-and-breaks":{"title":"Hoop isolations and breaks","summary":"Isolations make the hoop look frozen or floating; breaks intentionally interrupt spin to change direction or plane.","imageAlt":"3D figure holding a hoop isolation in the wall plane","body":["An isolation is the illusion that one point of the hoop stays still in space while the rest of the rim turns. Linear isolations slide that freeze point along a line; circular or centred isolations keep the float in one place. Cateyes close the rim toward the audience so the hoop reads as a narrow almond before it opens again. Ghosting traces with the free hand to sell the float.","A break is different. Instead of keeping continuous spin, you interrupt the hoop’s path — a paddle, a pinch, a shoulder break — so direction, plane or body zone can change. Off-body breaks train timing with the hands first; on-body breaks ask the core and shoulders to catch the same idea. Reversals flip the spin direction without dropping the phrase.","In SynthFlow, isolation and cateye modes already exist on the hoop generator. The Hoop lab groups them under the isolation family next to body spins, weaves, escalators and passes. Quizzes ask isolation-versus-spin and family identification. The hoop-isolation-session routine drills float before you stack breaks.","Keep cues short. For isolations: “freeze the far point, walk the hands.” For breaks: “stop the circle on purpose, then choose the next plane.” Tempo should drop when you first learn either skill; momentum hides mistakes until the hoop falls behind the beat.","Link isolations to the shared geometry article trail — hoop cateye and poi/staff isolation diameter are cousins. Link breaks to sequencing: a break is a punctuation mark in a counted phrase. Once both feel clean, on–off-body transitions stop being scary because you already own the ways to interrupt and restart the hoop’s story."]}}`),r=JSON.parse(`{"the-day-the-cascade-clicked":{"title":"El día que la cascade hizo clic","summary":"Tres semanas persiguiendo pelotas por el suelo terminaron en el momento en que dejé de mirarme las manos y empecé a contar.","body":["Durante tres semanas mi cascade de tres pelotas duró exactamente cuatro lanzamientos. Derecha, izquierda, derecha, y luego la tercera pelota estaba en algún lugar detrás del sofá. Vi vídeos, bajé el ritmo, lo subí. Me puse delante de la cama como dicen todos los tutoriales. Nada cambió, excepto mi vocabulario.","La solución, cuando llegó, era vergonzosamente simple. Puse una pista a 90 BPM y dije los counts en voz alta: uno, dos, tres, cuatro, un lanzamiento en cada beat. De repente los lanzamientos tenían un lugar donde estar. En vez de lanzar cuando la mano se sentía lista, lo que significaba cuando el pánico se lo ordenaba, cada lanzamiento esperaba su beat. El patrón se volvió más lento, más alto y más tranquilo.","La segunda solución fue dónde miraba. Había estado mirándome las manos, que es como leer un libro mirándote los párpados. Cuando levanté la mirada hacia los picos, los dos puntos en lo alto de los arcos, mis manos empezaron a atrapar solas. Los picos me decían si los lanzamientos eran parejos; las manos no necesitaban supervisión.","Doce lanzamientos se volvieron veinte, luego cincuenta. Una tarde hice malabares durante todo un paso de ocho compases sin una caída y le sonreí al techo como un idiota. La app lo llamó una clean run. Yo lo llamé la primera vez que los malabares se sintieron como música en vez de una pelea.","Si estás atascado en cuatro lanzamientos, prueba lo que me funcionó: cuenta en voz alta, lanza en el beat, mira los picos. Y suelta sin drama. El suelo es donde empieza toda cascade."]},"why-we-count-in-bars":{"title":"Por qué contamos en compases, no en segundos","summary":"Un aguante de cuarenta segundos tiene sentido para un estiramiento; un patrón de malabares vive en un beat, así que medimos la práctica en compases.","body":["Cuando empezamos a construir SynthFlow, la primera gran decisión fue cómo medir un paso de rutina. Nuestra app hermana SynthYoga cuenta los aguantes en segundos y respiraciones. Eso funciona para una postura que mantienes. No funciona para un patrón que se repite en un beat.","Un lanzamiento de malabares, un medio giro de staff y una órbita de hoop son todos ciclos. Si la música va a 100 BPM y tu cascade va a 103, no estás haciendo malabares con la música; los estás haciendo cerca de ella, y en un minuto vas un beat por detrás. Medir los pasos en compases a un tempo hace que la música, los counts, la figura 3D y el siguiente paso empiecen todos en el mismo downbeat.","Los compases también hacen concreto el progreso. “Haz malabares durante un minuto” es vago: ¿un minuto de qué, a qué velocidad? “Ocho compases de cascade a 96 BPM” es un reto específico y repetible. Si lo consigues limpiamente, la siguiente sesión puede pedir 104. Así funcionan las escaleras de tempo, y por eso la maestría en la app depende de clean runs y no solo del tiempo.","Requiere ingeniería seria. Cada animación está impulsada por el mismo reloj de audio que la música, programada con antelación para que nada se entrecorte. Las pistas incluidas tienen tempos y downbeats medidos. La percusión generada llena cualquier tempo que elijas. Las pistas de tu dispositivo se analizan y se comprueban con una prueba de taps. El vídeo en streaming se desactiva en la práctica contada porque no podemos mantenerlo en el beat.","El resultado es que el beat se convierte en maestro. Cuando te desvías, lo oyes. Cuando te sincronizas, lo sientes. Contar en compases resultó ser la decisión de diseño más importante que tomamos."]},"staff-hit-me-in-the-head":{"title":"El staff me golpeó en la cabeza (y otras lecciones)","summary":"Todo staff spinner recibe golpes; el acolchado, los planos y la paciencia convierten los golpes en progreso.","body":["Mi primer figure-8 terminó con el staff rebotando en mi cráneo y el perro saliendo de la habitación. Mi segundo terminó igual, menos el perro. Si estás aprendiendo staff, te van a golpear. La pregunta es con cuánta fuerza, y qué aprendes de ello.","Lección uno: el acolchado no es cobardía. Un staff de práctica con extremos blandos convirtió los golpes de gritos en encogimientos de hombros. Encogerse importa, porque el miedo te hace flaquear, y una muñeca que flaquea saca el staff de su plano, lo que causa el siguiente golpe.","Lección dos: la mayoría de los golpes vienen de planos inclinados. Cuando me grabé desde el lado, pude ver el staff inclinándose hacia mi cara en lo alto de cada giro. Mis muñecas rodaban hacia dentro. La superposición de planos en el visor 3D mostraba la versión limpia: el staff en una hoja plana al lado del cuerpo, sin inclinarse nunca hacia dentro. Arreglar la muñeca arregló los golpes.","Lección tres: lento y contado vence a rápido y con esperanza. Bajé el tempo al mínimo del rango del figure-8 y conté “lado derecho, lado izquierdo” con la música. A esa velocidad podía sentir el cambio de mano y mantener el plano plano. Una semana después pude volver a subir.","Lección cuatro: ríete. El staff spinning es ridículo y maravilloso. Los golpes son parte de la historia que comparte todo el mundo en la escena. Ponte un gorro si lo necesitas, despeja las luces del techo y sigue girando."]},"hooping-for-people-who-cant-hoop":{"title":"Hula hoop para quienes creen que no pueden hacer hula hoop","summary":"La mayoría de los adultos que “no pueden hacer hula hoop” recibieron un aro del tamaño de un juguete; un aro más grande y un pulso hacia adelante y hacia atrás solucionan casi todo.","body":["“No puedo hacer hula hoop” es algo que los profesores de hoop escuchan constantemente, normalmente de alguien que lo intentó por última vez con un aro de juguete para niños. Los aros pequeños y ligeros giran rápido y caen rápido. Exigen caderas rápidas y frenéticas. Los adultos con un aro de tamaño adulto suelen encontrarlo mucho más manejable.","Empieza grande. Un aro que llega más o menos entre tu cintura y tu pecho cuando lo apoyas en el suelo gira lo bastante despacio para que sientas el ritmo. Los aros más pesados también llevan más impulso. Puedes pasar a uno más pequeño después para velocidad y trucos fuera del cuerpo.","Pulsa, no dibujes círculos. El error más común es intentar hacer círculos grandes con las caderas. El hoop en cintura suele ser un pequeño balanceo hacia adelante y hacia atrás, o de lado a lado, al ritmo del aro. Un pie ligeramente adelantado ayuda. El aro toca tu frente y tu espalda; empujas suavemente cuando pasa.","Cuéntalo. Un tempo relajado, una órbita por beat, le da a tu cuerpo un ritmo en el que asentarse. La app empieza el hoop en cintura lento y luego te deja subir. Si el aro se hunde, añade un poco de velocidad a tu pulso, no un movimiento más grande.","Espera que se caiga mucho durante unas sesiones, y luego, de repente, que no se caiga. El hoop es una de esas habilidades que hacen clic. Cuando lo hace, hay todo un mundo de flow en el cuerpo y fuera de él esperándote, y mucho no necesita ni la cintura."]},"unlocking-is-not-a-race":{"title":"Desbloquear no es una carrera","summary":"El árbol de recompensas abre movimientos más difíciles a medida que dominas sus bases; lo importante son las bases.","body":["Las recompensas de SynthFlow son movimientos. Domina la cascade y se abre la reverse cascade; domina el front spin y aparece el figure-8. Es satisfactorio ver el árbol iluminarse, y lo diseñamos para que lo sea. Pero hay una trampa en cualquier sistema de desbloqueo, y vale la pena nombrarla.","La trampa es tratar el dominio como una casilla que marcar. Técnicamente puedes registrar las rondas limpias de un movimiento en un buen día, desbloquear el siguiente y seguir adelante con una base que solo funciona cuando todo sale bien. Entonces los movimientos más difíciles parecen imposibles, porque asumen que la base funciona cuando las cosas salen mal.","Dominio en el flow significa que el movimiento sobrevive a la distracción: un poco de fatiga, un tempo diferente, alguien que pasa caminando. Por eso el dominio pide rondas limpias a lo largo de varias sesiones, no solo en una. Y por eso sugerimos volver regularmente a los movimientos dominados. La cascade no es un nivel que terminas; es el suelo sobre el que se sostiene todo el árbol del malabarismo.","Los movimientos bloqueados también tienen páginas. Puedes leer sobre ellos, verlos en 3D y ver qué necesitan. Mirar hacia adelante motiva. Practicar hacia adelante, sin las bases, es sobre todo frustrante.","Así que disfruta los desbloqueos, pero mídete por lo fáciles que se sienten tus movimientos más antiguos. Cuando la cascade sea aburrida, estarás listo para Mills Mess. Cuando Mills Mess sea aburrido, el árbol tendrá más que ofrecer."]},"practice-in-ten-minutes":{"title":"Una práctica real en diez minutos","summary":"Calentamiento, un movimiento foco, un enlace, una subida corta de tempo y una vuelta a la calma: diez minutos, cada día.","body":["La razón más común que la gente da para no practicar es el tiempo. La verdad es que las habilidades de flow responden de maravilla a sesiones cortas y frecuentes. Esta es la forma de diez minutos que usamos nosotros mismos.","Minuto uno a dos: calentamiento. Círculos de muñeca, círculos de brazos, rotaciones de hombros, algunos círculos de cadera si haces hoop. Contados, a un tempo relajado, para que tu timing despierte junto con tus articulaciones.","Minuto tres a cinco: tu movimiento foco. Un movimiento en el que estás trabajando, a un tempo que puedas hacer limpio. Varios pasos cortos contados en lugar de uno largo, con una respiración entre ellos.","Minuto seis a siete: un enlace. Empareja el movimiento foco con algo hacia lo que fluya o desde lo que fluya. Cascade a reverse cascade. Front spin a figure-8. Cintura a pecho. Los enlaces son lo que hace que la práctica se sienta como flow en lugar de ejercicios.","Minuto ocho a nueve: una pequeña subida de tempo. Dos o tres peldaños, unos pocos BPM cada uno, parando antes de que se rompa la forma. Termina en un peldaño limpio.","Minuto diez: vuelta a la calma. Un movimiento lento y fácil o un breve descanso. Registra tu esfuerzo. Listo.","Diez minutos al día son más de una hora a la semana de práctica enfocada, repartida de la forma que más le gusta a la coordinación. El asistente de práctica construye sesiones de este tamaño cuando le dices que andas corto de tiempo, y las rutinas cortas integradas siguen la misma forma."]},"antispin-broke-my-brain":{"title":"El antispin me rompió el cerebro (por una semana)","summary":"Girar el staff contra el círculo de la mano parece imposible hasta que los conteos le dan un beat a cada pétalo.","body":["El antispin es donde el staff spinning empieza a sentirse como tarea de geometría. Tu mano dibuja un círculo en una dirección mientras el staff gira en la otra, y los extremos trazan una flor. La primera vez que lo intenté, produje algo más parecido a un diente de león marchito.","Lo que ayudó fue hacer la forma contable. Un antispin de cuatro pétalos tiene cuatro momentos en los que un extremo apunta directamente hacia fuera del círculo. Le di un beat a cada uno: arriba, lado, abajo, lado. Luego bajé la música muy por debajo de mi tempo normal de giro y simplemente apunté a las posiciones en los beats.","El ghost del visor 3D, que muestra dónde debería estar el staff en el siguiente beat, fue mi mejor amigo esa semana. También lo fue el trail, que dibujaba mi flor para que pudiera ver cuándo los pétalos estaban desiguales. Normalmente el pétalo de abajo quedaba aplastado, porque iba con prisa en la parte baja del círculo.","Después de aproximadamente una semana, algo cambió. Dejé de pensar en la mano y el staff como dos cosas y empecé a sentir la flor como una sola forma. El tempo volvió a subir por sí solo.","Si el antispin te está rompiendo el cerebro, se supone que lo haga. Dale un beat a cada pétalo, baja la música y deja que tu cuerpo lo resuelva. Es una de las mejores sensaciones en el flow cuando lo logra."]},"siteswaps-for-the-maths-shy":{"title":"Siteswaps para los que le huyen a las matemáticas","summary":"No necesitas que te gusten las matemáticas para usar siteswap; solo necesitas saber que los números más grandes van más alto.","body":["La notación siteswap tiene reputación de asustar a la gente. Los malabaristas dicen alegremente “prueba 531” como si eso explicara algo. Lo hace, pero solo una vez que sabes un par de cosas, y esas cosas son más simples de lo que parecen.","Aquí está casi todo lo que necesitas. Cada número es un lanzamiento. Los números más grandes van más alto. Los números impares cruzan a la otra mano; los pares vuelven a la misma mano. Un 3 es un lanzamiento normal de cascade. Un 1 es un zip rápido de un lado a otro. Un 2 normalmente es solo sostener la pelota.","Eso es suficiente para leer 441: dos lanzamientos más altos que se quedan en su propio lado, luego un zip al otro lado. Ya puedes intentarlo sin leer otra palabra. Lanza, lanza, zip, en el beat.","Si quieres una pieza más: suma los números y divide por cuántos hay, y obtienes el número de pelotas. 4 + 4 + 1 = 9, dividido por 3 son 3 pelotas. Si la respuesta no es un número entero, el patrón no se puede hacer malabares. Eso es todo el famoso teorema del promedio.","En SynthFlow, cada movimiento de malabarismo tiene un siteswap, y el motor 3D se anima directamente a partir de él. Eso significa que la figura siempre lanza exactamente las alturas que describen los números, en los beats exactos. Ver un siteswap animado lentamente es la forma más rápida que conocemos de hacer que los números tengan sentido. No se requiere título en matemáticas."]},"music-that-fights-you":{"title":"Cuando la música te pelea","summary":"Una pista que se desvía contra los conteos hace que cada movimiento sea más difícil; los tempos medidos y los beats generados lo arreglan.","body":["Probablemente lo has sentido: una canción que amas, un movimiento que conoces y, de alguna manera, todo se siente mal. Te apuras, se te cae, te culpas. A menudo el problema no eres tú. Es que el tempo de la canción no coincide con el movimiento.","Cada movimiento de flow tiene un rango de tempo cómodo. Por debajo, los props se estancan; por encima, los lanzamientos salen bajos y frenéticos. Una pista a 128 BPM bajo un movimiento de hoop que prefiere 90 te obliga a elegir entre la música y el hoop. La buena noticia es que half time y double time ayudan: 128 puede llevar un movimiento a 64, un ciclo cada dos beats.","El drift es el problema más sutil. Si la música dice 120 pero los counts dicen 116, los dos se separan con el tiempo, y tu cuerpo no puede seguir a ambos. Por eso SynthFlow usa tempos medidos para sus pistas incluidas, genera percusión a cualquier tempo exacto y verifica las pistas de tu dispositivo con un tap test.","Cuando una pista te pelea, no le devuelvas el golpe. Cambia al beat generado para el paso, o deja que el builder te sugiera una pista en el rango correcto. Guarda las canciones que amas para el free play, donde nada necesita cuadrar.","La música debe sentirse como una compañera. Si se siente como una oponente, cambia la música, no tu movimiento."]},"learning-alongside-my-kid":{"title":"Aprender a hacer malabares junto a mi hijo","summary":"Dos principiantes, una bolsa de pelotas y una regla: celebramos las caídas tan fuerte como las atrapadas.","body":["Mi hija pidió aprender malabares, y me di cuenta de que yo tampoco sabía. Así que aprendimos juntos, diez minutos después de cenar, con tres beanbags cada uno y una regla: celebramos las caídas tan fuerte como las atrapadas.","La regla suena tonta. Resultó ser la parte más importante. Los niños, y los adultos, se tensan cuando creen que un error es vergonzoso. La tensión empeora los lanzamientos. Celebrar cada caída convirtió el suelo en parte del juego y nos mantuvo sueltos a los dos.","Empezamos con una pelota, lanzándola de mano en mano al beat, con picos a la altura de los ojos. Se sintió demasiado fácil durante unas tres sesiones y luego, de repente, importante, porque los intercambios con dos pelotas solo funcionan si esos lanzamientos individuales son consistentes. Ella dominó el intercambio antes que yo y fue insoportable al respecto.","La música con counts nos ayudó a practicar juntos. Mismo tempo, mismo downbeat, dos personas lanzando a tiempo. Cuando uno perdía el patrón, el otro seguía, y el que había soltado volvía a entrar en el siguiente “one”.","A las cuatro semanas, los dos tenemos una cascade tambaleante. Más importante aún, tenemos un hábito que ambos esperamos con ganas. Si tienes un hijo que quiere aprender algo, apréndelo con él. Ser principiantes juntos está infravalorado."]},"why-your-throws-drift-forward":{"title":"Por qué tus lanzamientos se van hacia adelante","summary":"Si terminas cada cascade a tres pasos de donde empezaste, tus lanzamientos se están inclinando lejos de ti. Aquí te contamos cómo traerlos de vuelta.","body":["Todo malabarista conoce el caminar. Empiezas la cascade en el centro de la sala y la terminas con la nariz contra la pared, persiguiendo el patrón paso a paso. Se siente como si las pelotas te tiraran. No lo hacen. Las estás lanzando hacia adelante, unos centímetros a la vez, y luego caminas para alcanzarlas.","La causa casi siempre son los codos. Cuando te pones tenso, los antebrazos se inclinan hacia adelante y las manos sueltan la pelota un poco delante del cuerpo. Cada lanzamiento cae un poco más lejos, así que la siguiente recepción ocurre más lejos, así que el siguiente lanzamiento empieza más lejos. Se acumula rápido.","La solución que enseño primero es pegar los codos. Mantén los codos cerca de las costillas, los antebrazos más o menos nivelados, y lanza las pelotas rectas hacia arriba, pasando por delante de tus ojos, en lugar de hacia adelante. Se siente apretado por un día. Después se siente tranquilo.","La segunda solución es una pared. Párate frente a ella, a un antebrazo de distancia, y haz malabares. Si los lanzamientos se desvían, la pared te lo dice de inmediato, y fuerte. Diez minutos de práctica contra la pared le enseñan al cuerpo cómo se siente un patrón vertical más rápido que cualquier cosa que yo pueda decir.","El modo cámara de SynthFlow también detecta la deriva. Rastrea cuánto más grande se ve tu torso ante la cámara con cada paso, lo que significa que estás caminando hacia ella, y te avisa con una señal corta. El coach 3D también puede mostrar el fantasma de un lanzamiento hacia adelante junto al limpio, para que veas la diferencia en lugar de solo escucharla.","La deriva no es un defecto de carácter. Es un hábito de tensión, y los hábitos cambian con la repetición. Pega los codos, lanza hacia arriba y no hacia afuera, y deja que la pared te mantenga honesto."]},"practising-to-a-click":{"title":"Practicar con un click","summary":"Un metrónomo suena como lo menos divertido del mundo. Resultó ser lo que hizo que mi flow se sintiera como bailar.","body":["Resistí el click durante años. La música era el sentido del flow arts para mí, y un metrónomo se sentía como tarea. Entonces una amiga que toca batería me vio hacer malabares y me dijo, con cariño, que aceleraba cada vez que me emocionaba y frenaba cada vez que me asustaba. Tenía razón, y yo no tenía idea.","Así que probé una semana de práctica con nada más que un clic. El primer descubrimiento fue que un pulso constante es más difícil de lo que suena. Mi patrón de dos en una mano quería acelerarse. Mi figura-8 con el staff quería arrastrarse en el lado débil. Al clic no le importaba cómo me sentía; solo mantenía el tiempo.","El segundo descubrimiento fue que el clic hacía la música más fácil. Después de una semana, cuando volví a poner pistas reales, podía sentir dónde se asentaba el beat dentro del sonido. Dejé de pelear con canciones de timing suelto y empecé a elegir en qué parte del groove engancharme.","La percusión generada de SynthFlow es una versión más amigable del clic. Eliges un kit, desde un clic simple hasta tambores de mano, y toca a cualquier tempo, así un patrón puede vivir exactamente a la velocidad que puedes sostener. También puede sonar bajito bajo una pista de música como guía. Yo todavía lo uso solo durante los primeros minutos de cada sesión.","Si quieres probar esto, elige un patrón y un tempo que se sienta un poco demasiado lento. Cuenta en voz alta durante cuatro compases, luego deja de contar y solo escucha. Cuando el patrón y el clic se sientan como un solo sonido, sube cuatro BPM. Ese es todo el método."]},"staff-in-a-small-apartment":{"title":"Staff en un apartamento pequeño","summary":"Un staff de 1,4 metros y un techo de 2,4 metros pueden convivir. Solo tienes que elegir tus planos.","body":["Mi piso tiene techos bajos, una lámpara a la que le tengo cariño y un vecino de abajo que trabaja de noche. Nada de eso es ideal para girar el staff. Practiqué en parques durante un año antes de darme cuenta de que la mayor parte de mi entrenamiento podía ocurrir bajo techo después de todo.","El truco son los planos. Los giros en plano de rueda, los grandes al lado del cuerpo, necesitan toda la altura del staff por encima de tu cabeza. El trabajo en plano de pared frente al cuerpo necesita anchura pero menos altura. Los giros en plano de suelo, como el helicóptero, necesitan espacio libre sobre tu cabeza pero nada alrededor de tus espinillas. Cada habitación soporta movimientos diferentes.","En mi sala puedo hacer isolations, giros frontales y figura-8s lentos con los brazos bajos. En el pasillo no puedo hacer nada en absoluto, así que el pasillo es para calentamientos de muñeca. El dormitorio tiene el techo más alto, así que el trabajo en plano de rueda ocurre ahí, despacio, con la lámpara quitada y guardada en un cajón.","Los staffs cortos también ayudan. Un staff de práctica una mano más corto que mi staff de presentación convirtió muchos casi-choques en espacio libre fácil. El timing cambia un poco, así que reviso mi staff de longitud completa afuera una vez por semana.","Para los vecinos: mats de práctica y staffs con puntas suaves. Una caída sobre un mat de yoga es un golpe sordo en vez de un estallido. También mantengo las sesiones bajo techo en rutinas contadas de diez minutos, lo que mantiene el ruido corto y la práctica enfocada.","SynthFlow te deja marcar movimientos que no puedes hacer en casa como no deseados para que el generador los deje fuera de las rutinas de interior. Los espacios pequeños no detienen el progreso. Solo te hacen muy bueno en isolations."]},"hooping-after-40":{"title":"Hooping después de los 40","summary":"Tomé un hoop por primera vez a los 43. Mi espalda, mis rodillas y mi orgullo tenían opiniones. Esto es lo que funcionó.","body":["Compré mi primer hoop de adulto por capricho después de un festival, convencido de que sería terrible. Fui terrible. También, en un mes, estaba haciendo hooping en la cintura durante canciones enteras, y en seis meses haciendo movimientos simples fuera del cuerpo. La edad no me detuvo. Solo cambió cómo necesitaba practicar.","La gran lección fue calentar bien. Círculos de cadera, giros de torso y rebotes suaves de rodilla toman tres minutos y hacen que el primer hoop de la sesión se sienta fluido en vez de crujiente. SynthFlow pone calentamientos al inicio de cada rutina por una razón, y dejé de saltármelos después de una mañana rígida.","La segunda lección fue el tamaño del hoop. Un hoop más grande y un poco más pesado gira más despacio, lo que te da más tiempo y le pide menos esfuerzo a la espalda baja. Empecé con un hoop que llegaba entre mi cintura y mi pecho cuando estaba de pie en el suelo, y todavía lo uso para sesiones largas de práctica.","Tercero: pulsa, no circules. Los principiantes a menudo balancean las caderas en un círculo, lo que tuerce la columna más de lo necesario. Un pulso de adelante hacia atrás, o de lado a lado si el hoop gira así para ti, mantiene el hoop arriba con menos tensión. El coach 3D muestra esto claramente si miras las caderas en vez del hoop.","Finalmente, corto y frecuente vence a largo y ocasional. Diez minutos cuatro veces por semana hicieron más por mí que una hora el domingo. Mi cuerpo se recuperaba entre sesiones, y los movimientos se quedaban.","Si tienes más de 40 y curiosidad, empieza. El hoop no sabe cuántos años tienes."]},"fire-and-the-beginner":{"title":"Fuego y el principiante","summary":"El fire spinning es la parte más visible de las flow arts y la parte por la que más preguntan los principiantes. La respuesta honesta es: todavía no, y no solo.","body":["Cada semana alguien nos pregunta cuándo SynthFlow enseñará fuego. Es una pregunta justa. El fuego es hermoso, y muchos spinners entraron a la escena después de ver un círculo de fuego de noche. Pero nunca vamos a entrenar a nadie para encender un prop, y este post explica por qué.","El fuego añade peligros que no tienen nada que ver con la habilidad: manejo de combustible, ropa, viento, espectadores, quemaduras y extinción. Estas cosas se aprenden de personas experimentadas en persona, con una persona de seguridad entrenada presente y equipo adecuado listo. Una app no puede revisar tu depósito de combustible, tu ropa de algodón o tu toalla de seguridad.","Lo que la app sí puede hacer es ayudarte a construir las habilidades que el fuego necesita antes de que te acerques a él. Eso significa movimientos que puedes hacer de forma confiable durante una canción entera, a un tempo constante, sin caídas. Si un patrón todavía te sorprende en casa con un prop de práctica, no está listo para fuego.","Una prueba útil de la comunidad de fuego: ¿puedes hacer la rutina con los ojos medio cerrados, en la oscuridad, mientras alguien te habla? El fuego es brillante, caliente y ruidoso, y toma tu atención. Tu cuerpo tiene que saber los movimientos sin supervisión.","Los props LED son un gran paso intermedio. Te dan el look nocturno, las estelas y la reacción del público sin el riesgo. El pack de estilo LED de SynthFlow muestra cómo se verán tus patrones iluminados, lo que también es una buena forma de detectar planos descuidados.","Cuando estés listo, encuentra un fire jam local, preséntate y pide aprender seguridad primero. Gira props de práctica hasta entonces. El fuego seguirá ahí."]},"four-balls-taught-me-patience":{"title":"Cuatro pelotas me enseñaron paciencia","summary":"Pasar de tres pelotas a cuatro me tomó más tiempo que aprender tres desde cero, y cambió cómo pienso sobre la práctica.","body":["Tres pelotas me tomaron cinco semanas. Cuatro me tomaron cinco meses. Nadie me advirtió sobre esto, así que te advierto: cuatro pelotas no es tres pelotas más una. Es un patrón completamente diferente, y tu cuerpo tiene que aprenderlo desde cero.","En una fuente de cuatro pelotas, cada mano hace malabares con dos pelotas por su cuenta, y las pelotas nunca se cruzan. Las manos normalmente alternan, pero no hay intercambio entre ellas en absoluto. Todo lo que había aprendido sobre atrapar una pelota de la otra mano de repente era inútil.","Así que volví a una mano. Dos pelotas en la mano derecha, en columnas, luego círculos, hasta que podía hacer cincuenta lanzamientos sin pensar. Luego la mano izquierda, que tomó tres veces más. Luego ambas manos juntas, primero en sincronía, luego alternando. La escalera de tempo en SynthFlow ayudó aquí: empezaba cada semana en el fondo del rango de la fuente y solo subía después de una ronda limpia.","La lección de paciencia vino de los estancamientos. Algunas semanas nada mejoraba. Grabé caídas y rondas limpias de todos modos, y el gráfico mostraba progreso lento incluso cuando se sentía como nada. Los datos hicieron las semanas aburridas soportables.","La otra lección fue sobre el descanso. Cuatro pelotas cansaban mis antebrazos de una forma que tres nunca lo hicieron. Cuando practicaba todos los días, empeoraba. Cuando practicaba día por medio, mejoraba. Los músculos de agarre necesitan recuperación como cualquier otro.","Si estás atascado entre tres y cuatro, divide el problema, confía en las semanas lentas y dale un día libre a tus antebrazos. Llega."]},"the-escalator-and-hand-traffic":{"title":"La escalera y el arte del tráfico de manos","summary":"Los movimientos de manos con hoop parecen magia hasta que ves que son solo una gestión cuidadosa del tráfico entre dos manos.","body":["La primera vez que vi una escalera, el hoop parecía subir por los brazos del hooper y flotar hacia abajo de nuevo, sin fin, sin un agarre obvio. Asumí que necesitaba años de práctica. Necesitó unas tres semanas, una vez que entendí que es solo un patrón de traspasos.","Casi todo movimiento de hoop fuera del cuerpo se trata de qué mano sostiene el hoop, cuándo lo suelta y dónde lo encuentra la otra mano. Si el timing entre las manos es difuso, el hoop se tambalea fuera de su plano y el movimiento se desmorona. Si el timing es limpio, el hoop parece moverse por sí solo.","Así que empecé a nombrar los traspasos. Sobre el conteo de SynthFlow decía las manos en voz alta en lugar de los números: derecha, izquierda, derecha, izquierda, una en cada beat. Decirlas con la música me obligaba a notar cuándo mi mano izquierda agarraba antes de tiempo. Los agarres anticipados eran la fuente de casi todos los tambaleos.","La segunda clave era mantener el hoop en su plano. Una mano que gira al agarrar inclina el hoop, y un hoop inclinado es un hoop que se cae medio segundo después. La superposición de plano ayuda aquí, y también practicar frente a un espejo con tempos lentos.","Una vez que la escalera se sintió confiable, otros movimientos de manos llegaron más rápido. Isolations, pases y lassos usan la misma idea: traspasos claros, planos planos, timing constante. La magia es solo gestión de tráfico."]},"behind-the-back-without-fear":{"title":"Detrás de la espalda sin miedo","summary":"Los pases de staff por detrás de la espalda son donde la mayoría de los spinners se estancan. El problema normalmente no es la habilidad sino las ganas de mirar.","body":["Durante meses mi pase por detrás de la espalda fue un pase frontal con un giro esperanzado. Empezaba el movimiento, entraba en pánico cuando el staff salía de mi vista, y lo traía de vuelta al frente. El staff nunca llegaba realmente detrás de mi espalda. Mi cerebro no lo permitía.","El avance vino de aceptar que no podía ver el movimiento. No puedes mirar un pase por detrás de la espalda. Tienes que sentir dónde está el staff desde la mano que suelta y confiar en la mano que espera.","Entrené esa sensación en cámara lenta. Sin girar en absoluto, pasaba el staff detrás de mi espalda, de mano a mano, con los ojos al frente. Luego con un medio giro lento primero. Luego en el rango más bajo del tempo del movimiento, contado. Cada paso se sentía ridículo. Cada paso funcionó.","El coach 3D fue sorprendentemente útil porque podía rotar la vista y ver el movimiento desde atrás. Ver dónde se encuentran las manos, y cómo el staff se mantiene en el plano de pared mientras da la vuelta, le dio a mi cuerpo un mapa que no podía obtener desde el frente.","El segundo miedo era golpearme. Un staff de práctica con puntas blandas y un espacio amplio y despejado lo resolvieron. Una vez que supe que un error costaría un golpe suave en lugar de un moretón, dejé de encogerme, y el encogimiento había estado causando los fallos.","Si detrás de la espalda todavía te da miedo, bájale la velocidad, quita el giro, y mantén los ojos al frente. Tus manos saben más de lo que crees."]},"why-reverse-feels-wrong":{"title":"Por qué la cascade inversa se siente mal","summary":"La cascade inversa usa las mismas manos, las mismas pelotas y el mismo ritmo que la cascade. Entonces, ¿por qué se siente como empezar de nuevo?","body":["Cuando aprendí la cascade inversa, esperaba que me tomara una tarde. Son las mismas tres pelotas, las mismas manos alternadas y el mismo tempo que la cascade. Me tomó tres semanas, y no podía entender por qué.","La respuesta es la dirección. En una cascade normal, cada pelota se lanza desde el interior del patrón y se atrapa por fuera. En una cascade inversa, la pelota se lanza desde fuera, por encima de la pelota que llega, y se atrapa por dentro. Tus manos hacen el mismo ritmo pero formas completamente diferentes.","La nueva forma rompe tu timing. En la cascade, lanzas justo cuando la pelota que llega empieza a caer. En la inversa, necesitas lanzar un poco antes para que tu pelota pase por encima de la otra. Lanza en el momento antiguo y las pelotas chocan.","Lo arreglé con dos pelotas primero. Dos pelotas, dirección inversa, contado en el beat, hasta que se sintió automático. Luego tres pelotas a tempo lento con los conteos dichos en voz alta. La superposición fantasma de SynthFlow me mostró un error típico, un lanzamiento demasiado bajo que roza la otra pelota, y pude ver que estaba haciendo exactamente eso.","Una vez que hizo clic, desbloqueó mucho. Mezclar cascade e inversa es la base de muchos trucos, y la forma inversa vuelve a aparecer en Mills Mess. Haber sido malo en eso durante tres semanas valió la pena."]},"making-a-prop-stand-still":{"title":"Isolations: hacer que un prop se quede quieto","summary":"Una isolation es un movimiento donde el prop parece quedarse en un solo lugar mientras tú te mueves alrededor de él. Es la ilusión más satisfactoria en las artes de flow.","body":["La primera vez que logré una isolation de staff, mi amigo preguntó cómo flotaba el staff. No flotaba, por supuesto. Mis manos se movían en un círculo cuidadoso para que un punto del staff se mantuviera fijo en el aire. Pero desde fuera parecía imposible, y esa sensación es por lo que amo las isolations.","Toda isolation funciona igual. Elige un punto en el prop, normalmente el centro o un extremo, y mantén ese punto quieto mientras el resto del prop gira. Tus manos tienen que moverse exactamente en la dirección opuesta a como el prop quiere moverse. Es contraintuitivo y ligeramente hipnótico.","La parte más difícil es que tu cuerpo también se mueve. Las caderas se desplazan, los hombros giran, y cada pequeño movimiento aparece como tambaleo en el punto fijo. Practiqué frente a un espejo con un pedazo de cinta en el vidrio marcando dónde debería estar el punto fijo. Si el centro del prop dejaba la cinta, lo sabía.","Las isolations de hoop siguen la misma idea. En SynthFlow activo los trails en el visor 3D y observo al coach: en una isolation limpia, el trail alrededor del punto fijo se mantiene diminuto. Cuando bajé mucho el tempo y lo copié, pude sentir mis manos desviándose en la parte superior de cada círculo.","Las isolations también construyen control que ayuda a todo lo demás. Una vez que puedes mantener un prop quieto, puedes colocarlo donde quieras. Los planos se vuelven más planos, las transiciones más limpias, y tu flow empieza a verse intencional en lugar de afortunado.","Empieza lento, marca el punto fijo, y obsérvalo como un halcón. Luego muéstraselo a un amigo y disfruta su cara."]}}`),i={"zero-to-cascade":{name:`De cero a cascade en 4 semanas`,description:`Una pelota, luego dos, luego se suma la tercera. Una sesión corta al día es suficiente: completa la rutina de cada semana para dominar su movimiento y abrir la siguiente.`,weeks:[{label:`Semana 1 · Una pelota`},{label:`Semana 2 · Dos pelotas`},{label:`Semana 3 · La tercera pelota`},{label:`Semana 4 · Cascade`}]},"beyond-the-cascade":{name:`Más allá de la cascada`,description:`Cuatro semanas de variedad con tres bolas: tenis y garras, luego lanzamientos por el cuerpo, y al final patrones síncronos de dos bolas a la vez.`,weeks:[{label:`Semana 1 · Tenis y garras`},{label:`Semana 2 · Media ducha`},{label:`Semana 3 · Lanzamientos por el cuerpo`},{label:`Semana 4 · Columnas`}]},"first-clubs":{name:`Primeras mazas`,description:`Desde una sola maza girando hasta una cascada estable de tres mazas, y después dobles para controlar la altura y el giro.`,weeks:[{label:`Semana 1 · Una maza`},{label:`Semana 2 · Intercambio`},{label:`Semana 3 · Cascada`},{label:`Semana 4 · Dobles`}]},"passing-with-a-partner":{name:`Passing con un compañero`,description:`Dos malabaristas, frente a frente. Una pelota de un lado a otro, luego dos cada uno al mismo beat, y después el seis tiempos, el cuatro tiempos y el dos tiempos con tres pelotas cada uno.`,weeks:[{label:`Semana 1 · Una pelota de un lado a otro`},{label:`Semana 2 · Dos pelotas cada uno`},{label:`Semana 3 · Seis tiempos y cuatro tiempos`},{label:`Semana 4 · Dos tiempos`}]},"staff-foundations":{name:`Fundamentos de staff`,description:`Wheel y front spins, el figure 8 y el pass-through: los cuatro movimientos sobre los que se construye casi todo el staff flow.`,weeks:[{label:`Semana 1 · Wheel spin`},{label:`Semana 2 · Front spin`},{label:`Semana 3 · Figure 8`},{label:`Semana 4 · Pass-through`}]},"staff-contact":{name:`Bastón de contacto`,description:`Afloja el agarre semana a semana: volante y cola de pez, luego rodadas de mano, y al final el bastón girando sobre el antebrazo.`,weeks:[{label:`Semana 1 · Volante`},{label:`Semana 2 · Cola de pez`},{label:`Semana 3 · Rodada de mano`},{label:`Semana 4 · Roll de antebrazo`},{label:`Week 5 · Angel / session`}]},"double-staff-start":{name:`Inicio con doble staff`,description:`Desde dos staff al mismo tiempo hasta split time y wheels en ambos lados.`,weeks:[{label:`Semana 1 · Mismo tiempo`},{label:`Semana 2 · Split time`},{label:`Semana 3 · Wheels`},{label:`Semana 4 · Split wheels`}]},"hoop-body-ladder":{name:`Escalera corporal con aro`,description:`Hula en la cintura en ambos sentidos, luego baja a caderas y muslos y sube al pecho.`,weeks:[{label:`Semana 1 · Ambos sentidos`},{label:`Semana 2 · Caderas`},{label:`Semana 3 · Muslos`},{label:`Semana 4 · Elevación al pecho`}]},"hoop-doubles-start":{name:`Inicio con doble aro`,description:`Un aro en cada mano: giros en espejo, giros desfasados, giros laterales y luego uno en la cintura y otro en la mano.`,weeks:[{label:`Semana 1 · Giros en espejo`},{label:`Semana 2 · Giros desfasados`},{label:`Semana 3 · Giros laterales`},{label:`Semana 4 · Cintura y mano`}]},"off-body-hoop":{name:`Hoop off-body`,description:`Desde girar el hoop en una mano hasta lassos, passes, wedgies y la isolation que hace que el hoop parezca flotar.`,weeks:[{label:`Semana 1 · Hand spin`},{label:`Semana 2 · Lasso y pass`},{label:`Semana 3 · Wedgie`},{label:`Semana 4 · Isolation`},{label:`Week 5 · Planes + on↔off`}]},"first-poi":{name:`Tu primer poi`,description:`Un poi y luego un par: giros en plano de pared en ambos sentidos, ruedas a los lados y, para terminar, tiempo dividido.`,weeks:[{label:`Semana 1 · Un poi`},{label:`Semana 2 · Plano de pared`},{label:`Semana 3 · Plano de rueda`},{label:`Semana 4 · Tiempo dividido`}]},"poi-weave-ladder":{name:`Escalera de tejidos con poi`,description:`Del chase the sun al tejido de tres tiempos en ambos sentidos, y luego el tejido de dos tiempos, más rápido.`,weeks:[{label:`Semana 1 · Chase the sun`},{label:`Semana 2 · Tejido de tres tiempos`},{label:`Semana 3 · Tejido inverso`},{label:`Semana 4 · Tejido de dos tiempos`},{label:`Week 5 · Five-beat / degrees`}]},"poi-antispin-start":{name:`Inicio con antispin`,description:`Primero extensiones y aislamientos, luego antispin con un poi y la flor de cuatro pétalos con dos.`,weeks:[{label:`Semana 1 · Extensiones`},{label:`Semana 2 · Aislamiento`},{label:`Semana 3 · Antispin con un poi`},{label:`Semana 4 · Flor antispin`},{label:`Week 5 · Hybrids`}]},"staff-tech-map":{name:`Staff tech map`,description:`Timing cells and flowers: symmetry lab, then isolation and antispin flower work.`,weeks:[{label:`Week 1 · Symmetry cells`},{label:`Week 2 · Figure 8`},{label:`Week 3 · Isolation`},{label:`Week 4 · Antispin flower`}]},"hoop-isolation-ladder":{name:`Hoop isolation ladder`,description:`Float isolations and cateyes, then reconnect with weave and pass.`,weeks:[{label:`Week 1 · Isolation`},{label:`Week 2 · Cateye`},{label:`Week 3 · Weave`},{label:`Week 4 · Pass link`}]}},a={"sf-ambient-70":{name:`Órbita lenta`},"sf-world-75":{name:`Pasos de mercado`},"sf-ambient-80":{name:`Deriva de farol`},"sf-world-85":{name:`Rueda del desierto`},"sf-handdrum-90":{name:`Tambor circular`},"sf-funk-95":{name:`Muñecas sueltas`},"sf-handdrum-100":{name:`Manos de fuego`},"sf-world-105":{name:`Campanas de río`},"sf-funk-110":{name:`Cascada de bolsillo`},"sf-handdrum-115":{name:`Groove de patio`},"sf-electronic-120":{name:`Staff de neón`},"sf-funk-125":{name:`Patrón de Rebote`},"sf-electronic-130":{name:`Hula Hoop Pixel`},"sf-handdrum-135":{name:`Djembe del Atardecer`},"sf-electronic-140":{name:`Estelas LED`},"sf-funk-145":{name:`Ciclo de Giro`},"sf-electronic-150":{name:`Flow Estroboscópico`},"sf-handdrum-155":{name:`Palmas Rápidas`},"sf-electronic-160":{name:`Girante Nocturno`}},o={poses:e,routines:t,learn:n,blog:r,progressions:i,music:a};export{r as blog,o as default,n as learn,a as music,e as poses,i as progressions,t as routines};